#Requires -Version 5.1
<#
.SYNOPSIS
    Windows Deployment Builder - unattended Windows Update engine.

.DESCRIPTION
    Installs applicable Windows updates through the documented Windows Update Agent (WUA) COM API,
    reboots when required, resumes after each reboot through a SYSTEM scheduled task, and repeats
    until nothing applicable remains. Written independently for this project; no third-party code
    or modules.

    Modes:
      Run   (default) Full engine. Must run elevated (normally as SYSTEM from the scheduled task).
      Scan  Read-only: searches for updates and prints how each one would be handled. Installs
            nothing, writes no state, needs no elevation.

    Final states (result.json, Application event log source "WindowsDeploymentBuilder"):
      Succeeded               Nothing applicable remains.
      CompletedWithFailures   Everything else is installed, but some updates failed repeatedly
                              and were given up.
      Failed                  A limit was reached (reboots, runtime, errors) or scanning failed.
      Offline                 No network was available before the runtime limit.

    On Succeeded and CompletedWithFailures the marker <dataRoot>\state\windows-update.done is
    written for the deployment orchestrator. The scheduled task is removed on every final state.

    Coordination (1.1.0, Phase 3): updates are installed and restarts are scheduled only while
    holding the machine-wide install lock shared with the application engine, so Windows Update
    never restarts the computer during an application installation. When the lock stays busy the
    engine exits with WaitingForLock or RebootDeferred (not final) and tries again at the next
    start or hourly trigger. The final states above are unchanged.
#>
[CmdletBinding()]
param(
    [ValidateSet('Run', 'Scan')]
    [string] $Mode = 'Run',
    [string] $ConfigPath = ''
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

$script:EngineVersion = '1.1.0'
$script:UpgradeCategoryId = '3689bdc8-b205-4af4-8d4b-a63924c5e9d5'   # WUA category "Upgrades"
$script:MicrosoftUpdateServiceId = '7971f918-a847-4430-9279-4a52d1efe18d'
$script:EventSource = 'WindowsDeploymentBuilder'
$script:Session = $null
$script:LogFile = $null
$script:StatusFile = $null

# ------------------------------------------------------------------------------------------------
# Small helpers (time, waiting, JSON) - kept as functions so tests can replace them.
# ------------------------------------------------------------------------------------------------

function Get-WduNow { [DateTime]::UtcNow }

function Wait-Wdu { param([int] $Seconds) if ($Seconds -gt 0) { Start-Sleep -Seconds $Seconds } }

function ConvertTo-WduDate {
    param($Value)
    if ($Value -is [DateTime]) { return $Value.ToUniversalTime() }
    [DateTime]::Parse([string] $Value, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime()
}

function Format-WduHResult {
    param($HResult)
    if ($null -eq $HResult) { return '' }
    '0x{0:X8}' -f ([int64] $HResult -band [int64] 4294967295)
}

function ConvertTo-WduHashtable {
    param($InputObject)
    if ($null -eq $InputObject) { return $null }
    if ($InputObject -is [System.Collections.IDictionary]) {
        $h = @{}
        foreach ($k in $InputObject.Keys) { $h[$k] = ConvertTo-WduHashtable $InputObject[$k] }
        return $h
    }
    if ($InputObject -is [System.Management.Automation.PSCustomObject]) {
        $h = @{}
        foreach ($p in $InputObject.PSObject.Properties) { $h[$p.Name] = ConvertTo-WduHashtable $p.Value }
        return $h
    }
    if ($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [string]) {
        return , @($InputObject | ForEach-Object { ConvertTo-WduHashtable $_ })
    }
    return $InputObject
}

function Write-WduJson {
    param([string] $Path, $Value)
    $json = $Value | ConvertTo-Json -Depth 10
    $tmp = "$Path.tmp"
    [System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding($false)))
    Move-Item -LiteralPath $tmp -Destination $Path -Force
}

function Read-WduJson {
    param([string] $Path)
    if (-not (Test-Path -LiteralPath $Path)) { return $null }
    ConvertTo-WduHashtable (Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json)
}

# ------------------------------------------------------------------------------------------------
# Configuration, paths, logging, status
# ------------------------------------------------------------------------------------------------

function Get-WduConfig {
    param([string] $Path)
    if (-not $Path) { $Path = Join-Path $PSScriptRoot 'config.json' }
    $raw = Read-WduJson $Path
    if (-not $raw) { throw "Configuration file not found: $Path" }
    $defaults = @{
        dataRoot             = 'C:\ProgramData\WindowsDeploymentBuilder'
        taskPath             = '\WindowsDeploymentBuilder\'
        taskName             = 'WindowsUpdate'
        mutexName            = 'Global\WindowsDeploymentBuilder-WindowsUpdate'
        drivers              = 'exclude'
        featureUpdates       = 'skip'
        optionalUpdates      = 'skip'
        microsoftUpdate      = $false
        maxReboots           = 10
        maxAttemptsPerUpdate = 2
        maxRuntimeHours      = 6
        maxErrors            = 5
        networkWaitMinutes   = 15
        confirmationScans    = 1
        confirmationDelaySeconds = 60
        resetComponentsOnce  = $true
        rebootWarningSeconds = 60
        initialDelaySeconds  = 60
        lockWaitMinutes      = 60
        excludedKbs          = @()
    }
    foreach ($k in @($defaults.Keys)) { if (-not $raw.ContainsKey($k)) { $raw[$k] = $defaults[$k] } }
    $raw.excludedKbs = @($raw.excludedKbs | Where-Object { $_ } | ForEach-Object { ([string] $_).ToUpperInvariant() })
    return $raw
}

function Get-WduPaths {
    param([hashtable] $Config)
    $root = Join-Path $Config.dataRoot 'Updates'
    @{
        Root     = $root
        Logs     = Join-Path $root 'logs'
        Log      = Join-Path (Join-Path $root 'logs') 'engine.log'
        State    = Join-Path $root 'state.json'
        Status   = Join-Path $root 'status.json'
        Result   = Join-Path $root 'result.json'
        MarkerDir = Join-Path $Config.dataRoot 'state'
        Marker   = Join-Path (Join-Path $Config.dataRoot 'state') 'windows-update.done'
    }
}

function Write-WduLog {
    param([string] $Message, [ValidateSet('INFO', 'WARN', 'ERROR')] [string] $Level = 'INFO')
    $line = '{0}  {1,-5}  {2}' -f (Get-WduNow).ToString('yyyy-MM-dd HH:mm:ss'), $Level, $Message
    Write-Verbose $line
    if (-not $script:LogFile) { return }
    for ($i = 0; $i -lt 3; $i++) {
        try { [System.IO.File]::AppendAllText($script:LogFile, $line + "`r`n"); return }
        catch { Start-Sleep -Milliseconds 200 }
    }
}

function Limit-WduLogSize {
    param([string] $Path, [int64] $MaxBytes = 5MB)
    if ((Test-Path -LiteralPath $Path) -and (Get-Item -LiteralPath $Path).Length -gt $MaxBytes) {
        Move-Item -LiteralPath $Path -Destination "$Path.1" -Force
    }
}

function Set-WduStatus {
    param([string] $Phase, [string] $Detail = '', [hashtable] $State)
    if (-not $script:StatusFile) { return }
    $o = [ordered]@{
        phase      = $Phase
        detail     = $Detail
        updatedUtc = (Get-WduNow).ToString('o')
        computer   = $env:COMPUTERNAME
        version    = $script:EngineVersion
    }
    if ($State) {
        $o.starts = $State.starts
        $o.reboots = $State.reboots
        $o.installed = @($State.installed).Count
    }
    try { Write-WduJson $script:StatusFile $o } catch { Write-WduLog "Could not write status: $($_.Exception.Message)" 'WARN' }
}

function Write-WduEvent {
    param([int] $EventId, [string] $Message, [ValidateSet('Information', 'Warning', 'Error')] [string] $EntryType = 'Information')
    try {
        if (-not [System.Diagnostics.EventLog]::SourceExists($script:EventSource)) {
            New-EventLog -LogName Application -Source $script:EventSource
        }
        Write-EventLog -LogName Application -Source $script:EventSource -EventId $EventId -EntryType $EntryType -Message $Message
    } catch {
        Write-WduLog "Could not write event $EventId to the Application log: $($_.Exception.Message)" 'WARN'
    }
}

# ------------------------------------------------------------------------------------------------
# State
# ------------------------------------------------------------------------------------------------

function New-WduState {
    @{
        version         = 1
        firstStartUtc   = $null
        starts          = 0
        reboots         = 0
        errors          = 0
        offlineStarts   = 0
        everOnline      = $false
        componentReset  = $false
        attempts        = @{}
        installed       = @()
        final           = $null
    }
}

function Read-WduState {
    param([hashtable] $Paths)
    $s = $null
    try { $s = Read-WduJson $Paths.State }
    catch {
        Write-WduLog "State file unreadable ($($_.Exception.Message)); keeping a copy and starting over." 'WARN'
        Copy-Item -LiteralPath $Paths.State -Destination "$($Paths.State).corrupt" -Force -ErrorAction SilentlyContinue
    }
    $fresh = New-WduState
    if (-not $s) { return $fresh }
    foreach ($k in @($fresh.Keys)) { if (-not $s.ContainsKey($k)) { $s[$k] = $fresh[$k] } }
    if ($null -eq $s.attempts) { $s.attempts = @{} }
    $s.installed = @($s.installed | Where-Object { $_ })
    return $s
}

function Save-WduState { param([hashtable] $State, [hashtable] $Paths) Write-WduJson $Paths.State $State }

# ------------------------------------------------------------------------------------------------
# Windows Update Agent adapter. Everything that touches the system lives here.
# Update objects returned to the engine are hashtables:
#   Id, Revision, Title, Kbs[], IsDriver, IsUpgrade, IsOptional, NeedsUserInput, IsDownloaded, Native
# ------------------------------------------------------------------------------------------------

function Get-WduSession {
    if (-not $script:Session) {
        $script:Session = New-Object -ComObject 'Microsoft.Update.Session'
        $script:Session.ClientApplicationID = 'Windows Deployment Builder'
    }
    $script:Session
}

function Get-WduAvailableUpdates {
    param([hashtable] $Config)
    $searcher = (Get-WduSession).CreateUpdateSearcher()
    if ($Config.microsoftUpdate) {
        $sm = New-Object -ComObject 'Microsoft.Update.ServiceManager'
        $sm.ClientApplicationID = 'Windows Deployment Builder'
        # 7 = asfAllowPendingRegistration + asfAllowOnlineRegistration + asfRegisterServiceWithAU
        [void] $sm.AddService2($script:MicrosoftUpdateServiceId, 7, '')
        $searcher.ServerSelection = 3   # ssOthers
        $searcher.ServiceID = $script:MicrosoftUpdateServiceId
    }
    $criteria = "IsInstalled=0 and IsHidden=0"
    if ($Config.drivers -ne 'include') { $criteria += " and Type='Software'" }
    $result = $searcher.Search($criteria)
    if ($result.ResultCode -notin 2, 3) { throw "Windows Update search returned result code $($result.ResultCode)." }
    $list = @()
    foreach ($u in $result.Updates) {
        $cats = @()
        foreach ($c in $u.Categories) { $cats += ([string] $c.CategoryID).ToLowerInvariant() }
        $kbs = @()
        foreach ($k in $u.KBArticleIDs) { $kbs += "KB$k" }
        $list += @{
            Id             = [string] $u.Identity.UpdateID
            Revision       = [int] $u.Identity.RevisionNumber
            Title          = [string] $u.Title
            Kbs            = $kbs
            IsDriver       = ([int] $u.Type -eq 2)
            IsUpgrade      = ($cats -contains $script:UpgradeCategoryId)
            IsOptional     = [bool] $u.BrowseOnly
            NeedsUserInput = [bool] $u.InstallationBehavior.CanRequestUserInput
            IsDownloaded   = [bool] $u.IsDownloaded
            Native         = $u
        }
    }
    return , $list
}

function ConvertTo-WduResultCode {
    param([int] $Code)
    switch ($Code) { 0 { 'NotStarted' } 1 { 'InProgress' } 2 { 'Succeeded' } 3 { 'SucceededWithErrors' } 4 { 'Failed' } 5 { 'Aborted' } default { "Unknown$Code" } }
}

function New-WduCollection {
    param([object[]] $Updates)
    $coll = New-Object -ComObject 'Microsoft.Update.UpdateColl'
    foreach ($u in $Updates) {
        if (-not $u.Native.EulaAccepted) { $u.Native.AcceptEula() }
        [void] $coll.Add($u.Native)
    }
    $coll
}

function Invoke-WduDownload {
    param([object[]] $Updates)
    $out = @{}
    $pending = @($Updates | Where-Object { -not $_.IsDownloaded })
    foreach ($u in $Updates) { if ($u.IsDownloaded) { $out[$u.Id] = @{ Result = 'Succeeded'; HResult = 0 } } }
    if ($pending.Count -eq 0) { return $out }
    try {
        $coll = New-WduCollection $pending
        $dl = (Get-WduSession).CreateUpdateDownloader()
        $dl.Updates = $coll
        $r = $dl.Download()
        for ($i = 0; $i -lt $pending.Count; $i++) {
            $ur = $r.GetUpdateResult($i)
            $out[$pending[$i].Id] = @{ Result = (ConvertTo-WduResultCode $ur.ResultCode); HResult = $ur.HResult }
        }
    } catch {
        foreach ($u in $pending) { $out[$u.Id] = @{ Result = 'Failed'; HResult = $_.Exception.HResult } }
        Write-WduLog "Download call failed: $($_.Exception.Message)" 'ERROR'
    }
    return $out
}

function Invoke-WduInstall {
    param([object[]] $Updates)
    $out = @{ RebootRequired = $false; Results = @{} }
    try {
        $coll = New-WduCollection $Updates
        $inst = (Get-WduSession).CreateUpdateInstaller()
        try { $inst.ForceQuiet = $true } catch { }
        $inst.Updates = $coll
        $r = $inst.Install()
        $out.RebootRequired = [bool] $r.RebootRequired
        for ($i = 0; $i -lt $Updates.Count; $i++) {
            $ur = $r.GetUpdateResult($i)
            $out.Results[$Updates[$i].Id] = @{ Result = (ConvertTo-WduResultCode $ur.ResultCode); HResult = $ur.HResult }
        }
    } catch {
        foreach ($u in $Updates) { $out.Results[$u.Id] = @{ Result = 'Failed'; HResult = $_.Exception.HResult } }
        Write-WduLog "Install call failed: $($_.Exception.Message)" 'ERROR'
    }
    return $out
}

function Test-WduRebootPending {
    try { if ((New-Object -ComObject 'Microsoft.Update.SystemInfo').RebootRequired) { return $true } } catch { }
    foreach ($key in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired',
                     'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') {
        if (Test-Path -LiteralPath $key) { return $true }
    }
    return $false
}

function Test-WduInstallerBusy {
    try { return [bool] (New-Object -ComObject 'Microsoft.Update.Installer').IsBusy } catch { return $false }
}

function Test-WduNetwork {
    # Managed (WSUS) clients only need their update server; everyone else needs the Internet.
    $wsus = $null
    try {
        $au = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU' -ErrorAction Stop
        if ($au.UseWUServer -eq 1) {
            $wsus = (Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate' -ErrorAction Stop).WUServer
        }
    } catch { }
    if ($wsus) {
        $uri = [Uri] $wsus
        return (Test-WduTcp $uri.Host $uri.Port)
    }
    try {
        # Network Connectivity Status Indicator probe documented by Microsoft.
        $r = Invoke-WebRequest -Uri 'http://www.msftconnecttest.com/connecttest.txt' -UseBasicParsing -TimeoutSec 10
        if ($r.Content -eq 'Microsoft Connect Test') { return $true }
    } catch { }
    return (Test-WduTcp 'fe3.delivery.mp.microsoft.com' 443)
}

function Test-WduTcp {
    param([string] $HostName, [int] $Port)
    $tcp = New-Object System.Net.Sockets.TcpClient
    try {
        $iar = $tcp.BeginConnect($HostName, $Port, $null, $null)
        return ($iar.AsyncWaitHandle.WaitOne(5000) -and $tcp.Connected)
    } catch { return $false } finally { $tcp.Close() }
}

function Invoke-WduReboot {
    param([int] $WarningSeconds, [string] $Reason)
    # p:2:17 = planned, Operating System: Hot fix
    & "$env:SystemRoot\System32\shutdown.exe" /r /t $WarningSeconds /d p:2:17 /c "Windows Deployment Builder: $Reason. The computer restarts in $WarningSeconds seconds; updating resumes automatically."
    if ($LASTEXITCODE -ne 0) { throw "shutdown.exe failed with exit code $LASTEXITCODE" }
}

function Reset-WduComponents {
    # Microsoft's documented manual reset: stop the services, rename the data stores, restart.
    $services = 'wuauserv', 'bits', 'cryptsvc'
    foreach ($s in $services) { try { Stop-Service -Name $s -Force -ErrorAction Stop } catch { Write-WduLog "Could not stop ${s}: $($_.Exception.Message)" 'WARN' } }
    $stamp = (Get-WduNow).ToString('yyyyMMddHHmmss')
    foreach ($dir in "$env:SystemRoot\SoftwareDistribution", "$env:SystemRoot\System32\catroot2") {
        if (Test-Path -LiteralPath $dir) {
            try { Rename-Item -LiteralPath $dir -NewName ("{0}.{1}.old" -f (Split-Path $dir -Leaf), $stamp) -ErrorAction Stop; Write-WduLog "Renamed $dir." }
            catch { Write-WduLog "Could not rename ${dir}: $($_.Exception.Message)" 'WARN' }
        }
    }
    foreach ($s in $services) { try { Start-Service -Name $s -ErrorAction Stop } catch { Write-WduLog "Could not start ${s}: $($_.Exception.Message)" 'WARN' } }
    $script:Session = $null
}

function Unregister-WduTask {
    param([hashtable] $Config)
    try {
        $t = Get-ScheduledTask -TaskName $Config.taskName -TaskPath $Config.taskPath -ErrorAction Stop
        $t | Unregister-ScheduledTask -Confirm:$false
        Write-WduLog "Removed scheduled task $($Config.taskPath)$($Config.taskName)."
    } catch {
        Write-WduLog "Scheduled task $($Config.taskPath)$($Config.taskName) not removed: $($_.Exception.Message)" 'WARN'
    }
}

# ------------------------------------------------------------------------------------------------
# Coordination with the application engine
# ------------------------------------------------------------------------------------------------

# region WDB coordination
# Shared by WindowsUpdateEngine.ps1 and ApplicationEngine.ps1; both copies must stay identical
# (tests/unit/applications-engine.test.ts checks this).
#
# install.lock         Machine-wide installation lock: a file opened exclusively. Windows releases
#                      it when the owning process ends, so a crash can never leave a stale lock.
#                      Whoever installs something or restarts the computer holds it.
# restart-pending.json Written just before an engine schedules a restart. Valid only in the boot
#                      it was written in (and for 30 minutes), so it disappears with the restart.

function Get-WdbBootTime {
    try { return (Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop).LastBootUpTime.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
    catch { return 'unknown' }
}

function Wait-WdbLockPoll { Start-Sleep -Seconds 5 }

function Get-WdbCoordinationPaths {
    param([string] $DataRoot)
    $dir = Join-Path $DataRoot 'state'
    @{ Dir = $dir; Lock = (Join-Path $dir 'install.lock'); Restart = (Join-Path $dir 'restart-pending.json') }
}

function Enter-WdbInstallLock {
    param([string] $DataRoot, [string] $Owner, [int] $TimeoutSeconds = 0)
    $p = Get-WdbCoordinationPaths $DataRoot
    if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null }
    $polls = [int] [Math]::Ceiling([Math]::Max(0, $TimeoutSeconds) / 5)
    for ($i = 0; ; $i++) {
        try {
            $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)
            $bytes = [System.Text.Encoding]::UTF8.GetBytes(('{{"owner":"{0}","pid":{1},"sinceUtc":"{2}"}}' -f $Owner, $PID, [DateTime]::UtcNow.ToString('o')))
            $fs.SetLength(0)
            $fs.Write($bytes, 0, $bytes.Length)
            $fs.Flush()
            return $fs
        } catch [System.IO.IOException] {
            if ($i -ge $polls) { return $null }
            Wait-WdbLockPoll
        }
    }
}

function Exit-WdbInstallLock {
    param($Lock)
    if ($Lock) { try { $Lock.Dispose() } catch { } }
}

function Get-WdbInstallLockOwner {
    param([string] $DataRoot)
    $p = Get-WdbCoordinationPaths $DataRoot
    try {
        $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try { return (New-Object System.IO.StreamReader($fs)).ReadToEnd() } finally { $fs.Dispose() }
    } catch { return '' }
}

function Set-WdbRestartPending {
    param([string] $DataRoot, [string] $Owner, [string] $Reason)
    $p = Get-WdbCoordinationPaths $DataRoot
    if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null }
    $o = [ordered]@{ owner = $Owner; reason = $Reason; requestedUtc = [DateTime]::UtcNow.ToString('o'); bootTimeUtc = (Get-WdbBootTime) }
    [System.IO.File]::WriteAllText($p.Restart, ($o | ConvertTo-Json), (New-Object System.Text.UTF8Encoding($false)))
}

function Test-WdbRestartPending {
    param([string] $DataRoot)
    $p = Get-WdbCoordinationPaths $DataRoot
    if (-not (Test-Path -LiteralPath $p.Restart)) { return $false }
    $m = $null
    try { $m = Get-Content -LiteralPath $p.Restart -Raw | ConvertFrom-Json } catch { }
    if ($m -and ([string] $m.bootTimeUtc) -eq (Get-WdbBootTime)) {
        $age = [DateTime]::UtcNow - [DateTime]::Parse([string] $m.requestedUtc, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime()
        if ($age.TotalMinutes -lt 30) { return $true }
    }
    # Written before the last restart, unreadable or abandoned: the restart is no longer pending.
    Remove-Item -LiteralPath $p.Restart -Force -ErrorAction SilentlyContinue
    return $false
}

# endregion WDB coordination

# ------------------------------------------------------------------------------------------------
# Single instance
# ------------------------------------------------------------------------------------------------

function Enter-WduMutex {
    param([string] $Name)
    $m = New-Object System.Threading.Mutex($false, $Name)
    try {
        if ($m.WaitOne([TimeSpan]::FromSeconds(10))) { return $m }
    } catch [System.Threading.AbandonedMutexException] {
        return $m   # previous owner died; we own it now
    }
    $m.Dispose()
    return $null
}

function Exit-WduMutex {
    param($Mutex)
    if ($Mutex) { try { $Mutex.ReleaseMutex() } catch { }; $Mutex.Dispose() }
}

# ------------------------------------------------------------------------------------------------
# Planning
# ------------------------------------------------------------------------------------------------

function Get-WduSkipReason {
    param([hashtable] $Update, [hashtable] $Config, [hashtable] $State)
    if ($Update.IsUpgrade -and $Config.featureUpdates -ne 'install') { return 'feature update (policy: skip)' }
    if ($Update.IsDriver -and $Config.drivers -ne 'include') { return 'driver (policy: exclude)' }
    if ($Update.IsOptional -and $Config.optionalUpdates -ne 'install') { return 'optional update (policy: skip)' }
    foreach ($kb in $Update.Kbs) { if ($Config.excludedKbs -contains $kb.ToUpperInvariant()) { return "excluded by configuration ($kb)" } }
    if ($Update.NeedsUserInput) { return 'requires user input' }
    $a = $State.attempts[$Update.Id]
    if ($a -and [int] $a.count -ge [int] $Config.maxAttemptsPerUpdate) { return "gave up after $($a.count) attempt(s)" }
    return $null
}

function Get-WduPlan {
    param([object[]] $Updates, [hashtable] $Config, [hashtable] $State)
    $plan = @{ Install = @(); Skipped = @(); GaveUp = @() }
    foreach ($u in $Updates) {
        $reason = Get-WduSkipReason $u $Config $State
        if (-not $reason) { $plan.Install += $u; continue }
        $entry = @{ id = $u.Id; title = $u.Title; kbs = @($u.Kbs); reason = $reason }
        if ($reason -like 'gave up*') {
            $a = $State.attempts[$u.Id]
            $entry.attempts = $a.count; $entry.lastResult = $a.lastResult; $entry.lastHResult = $a.lastHResult
            $plan.GaveUp += $entry
        } else {
            $plan.Skipped += $entry
        }
    }
    $plan
}

function Get-WduLabel { param([hashtable] $U) $kb = if (@($U.Kbs).Count) { ($U.Kbs -join ',') + ' ' } else { '' }; "$kb$($U.Title)" }

# ------------------------------------------------------------------------------------------------
# Outcomes
# ------------------------------------------------------------------------------------------------

function Complete-Wdu {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [string] $Status, [string] $Reason, $Plan = $null)
    $now = (Get-WduNow).ToString('o')
    $result = [ordered]@{
        status        = $Status
        reason        = $Reason
        engineVersion = $script:EngineVersion
        computer      = $env:COMPUTERNAME
        startedUtc    = $State.firstStartUtc
        finishedUtc   = $now
        starts        = $State.starts
        reboots       = $State.reboots
        installed     = @($State.installed)
        failed        = @(if ($Plan) { $Plan.GaveUp })
        skipped       = @(if ($Plan) { $Plan.Skipped })
    }
    Write-WduJson $Paths.Result $result
    $State.final = $Status
    Save-WduState $State $Paths
    if ($Status -in 'Succeeded', 'CompletedWithFailures') {
        if (-not (Test-Path -LiteralPath $Paths.MarkerDir)) { New-Item -ItemType Directory -Path $Paths.MarkerDir -Force | Out-Null }
        Write-WduJson $Paths.Marker ([ordered]@{ status = $Status; finishedUtc = $now; result = $Paths.Result })
    }
    $level = switch ($Status) { 'Succeeded' { 'INFO' } 'CompletedWithFailures' { 'WARN' } default { 'ERROR' } }
    Write-WduLog ("FINISHED: {0}. {1} Installed {2}, failed {3}, skipped {4}, reboots {5}." -f $Status, $Reason, @($result.installed).Count, @($result.failed).Count, @($result.skipped).Count, $State.reboots) $level
    foreach ($f in $result.failed) { Write-WduLog ("  FAILED   {0} {1} ({2} attempts, last {3} {4})" -f ($f.kbs -join ','), $f.title, $f.attempts, $f.lastResult, $f.lastHResult) 'WARN' }
    foreach ($s in $result.skipped) { Write-WduLog ("  SKIPPED  {0} {1}: {2}" -f ($s.kbs -join ','), $s.title, $s.reason) }
    $eventId = switch ($Status) { 'Succeeded' { 1100 } 'CompletedWithFailures' { 1101 } 'Failed' { 1102 } default { 1103 } }
    $entryType = switch ($Status) { 'Succeeded' { 'Information' } 'CompletedWithFailures' { 'Warning' } default { 'Error' } }
    Write-WduEvent $eventId "Windows Update automation finished: $Status. $Reason See $($Paths.Result)." $entryType
    Set-WduStatus $Status $Reason $State
    Unregister-WduTask $Config
    return "Finished:$Status"
}

function Request-WduReboot {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [string] $Reason, $Plan = $null)
    if ([int] $State.reboots -ge [int] $Config.maxReboots) {
        return Complete-Wdu $Config $Paths $State 'Failed' "Reboot limit ($($Config.maxReboots)) reached while a restart is still required ($Reason)." $Plan
    }
    # Never restart while an application is being installed.
    $lock = Enter-WdbInstallLock $Config.dataRoot 'WindowsUpdate' ([int] $Config.lockWaitMinutes * 60)
    if (-not $lock) {
        Write-WduLog "Restart deferred ($Reason): another installation holds the install lock. Trying again at the next start." 'WARN'
        Set-WduStatus 'RebootDeferred' $Reason $State
        return 'RebootDeferred'
    }
    try {
        $State.reboots = [int] $State.reboots + 1
        Save-WduState $State $Paths
        Write-WduLog "Restart $($State.reboots)/$($Config.maxReboots): $Reason. Resuming after boot."
        Set-WduStatus 'Rebooting' $Reason $State
        Write-WduEvent 1001 "Restarting to continue Windows Update ($Reason)."
        Set-WdbRestartPending $Config.dataRoot 'WindowsUpdate' $Reason
        Invoke-WduReboot -WarningSeconds ([int] $Config.rebootWarningSeconds) -Reason $Reason
        # Hold the lock through the warning period so nothing starts installing before the restart.
        Wait-Wdu ([int] $Config.rebootWarningSeconds + 120)
    } finally {
        Exit-WdbInstallLock $lock
    }
    return 'Rebooting'
}

function Test-WduDeadline {
    param([hashtable] $Config, [hashtable] $State)
    ((Get-WduNow) - (ConvertTo-WduDate $State.firstStartUtc)).TotalHours -ge [double] $Config.maxRuntimeHours
}

# ------------------------------------------------------------------------------------------------
# Main loop
# ------------------------------------------------------------------------------------------------

function Invoke-WduRun {
    param([hashtable] $Config, [hashtable] $Paths)
    $State = Read-WduState $Paths
    if ($State.final) {
        Write-WduLog "Already finished with status $($State.final); nothing to do."
        Unregister-WduTask $Config
        return 'AlreadyFinished'
    }
    $first = -not $State.firstStartUtc
    if ($first) { $State.firstStartUtc = (Get-WduNow).ToString('o') }
    $State.starts = [int] $State.starts + 1
    Save-WduState $State $Paths
    Write-WduLog "==== Engine $($script:EngineVersion) start $($State.starts) (reboots so far: $($State.reboots)) ===="
    Set-WduStatus 'Starting' "Start $($State.starts)" $State
    if ($first) {
        Write-WduEvent 1000 'Windows Update automation started.'
        Write-WduLog ("Policy: drivers={0}, feature updates={1}, optional={2}, Microsoft Update={3}; limits: {4} reboots, {5} attempts/update, {6} h." -f $Config.drivers, $Config.featureUpdates, $Config.optionalUpdates, $Config.microsoftUpdate, $Config.maxReboots, $Config.maxAttemptsPerUpdate, $Config.maxRuntimeHours)
        Wait-Wdu ([int] $Config.initialDelaySeconds)
    }

    if (Test-WduDeadline $Config $State) {
        if ($State.everOnline) { return Complete-Wdu $Config $Paths $State 'Failed' "Runtime limit ($($Config.maxRuntimeHours) h) reached." }
        return Complete-Wdu $Config $Paths $State 'Offline' "No network connection before the runtime limit ($($Config.maxRuntimeHours) h)."
    }

    # Network
    Set-WduStatus 'WaitingForNetwork' '' $State
    $deadline = (Get-WduNow).AddMinutes([double] $Config.networkWaitMinutes)
    $online = $false
    while ($true) {
        if (Test-WduNetwork) { $online = $true; break }
        if ((Get-WduNow) -ge $deadline) { break }
        Wait-Wdu 15
    }
    if (-not $online) {
        $State.offlineStarts = [int] $State.offlineStarts + 1
        Save-WduState $State $Paths
        Write-WduLog "No network after $($Config.networkWaitMinutes) min. The task retries at the next start or within the hour." 'WARN'
        Set-WduStatus 'WaitingForNetwork' 'No network; will retry' $State
        if (Test-WduDeadline $Config $State) {
            if ($State.everOnline) { return Complete-Wdu $Config $Paths $State 'Failed' "Runtime limit ($($Config.maxRuntimeHours) h) reached while offline." }
            return Complete-Wdu $Config $Paths $State 'Offline' "No network connection before the runtime limit ($($Config.maxRuntimeHours) h)."
        }
        return 'WaitingForNetwork'
    }
    if (-not $State.everOnline) { $State.everOnline = $true; Save-WduState $State $Paths }
    Write-WduLog 'Network available.'

    # Another update operation (for example Windows' own automatic updates) may be installing.
    for ($i = 0; $i -lt 60 -and (Test-WduInstallerBusy); $i++) {
        if ($i -eq 0) { Write-WduLog 'Windows Update installer is busy; waiting (max 30 min).' }
        Set-WduStatus 'WaitingForInstaller' '' $State
        Wait-Wdu 30
    }

    $emptyScans = 0
    $scanFailures = 0
    for ($pass = 1; $pass -le 50; $pass++) {
        if (Test-WduDeadline $Config $State) { return Complete-Wdu $Config $Paths $State 'Failed' "Runtime limit ($($Config.maxRuntimeHours) h) reached." }

        Set-WduStatus 'Scanning' "Pass $pass" $State
        Write-WduLog "Scan pass $pass."
        try {
            $updates = Get-WduAvailableUpdates $Config
            $scanFailures = 0
        } catch {
            $scanFailures++
            $hr = Format-WduHResult $_.Exception.HResult
            Write-WduLog "Scan failed ($scanFailures/3): $($_.Exception.Message) $hr" 'ERROR'
            if ($scanFailures -lt 3) { Wait-Wdu 60; continue }
            if ($Config.resetComponentsOnce -and -not $State.componentReset) {
                Write-WduLog 'Resetting Windows Update components once after repeated scan failures.' 'WARN'
                Set-WduStatus 'ResettingComponents' 'Scan failures' $State
                Reset-WduComponents
                $State.componentReset = $true
                Save-WduState $State $Paths
                $scanFailures = 0
                continue
            }
            return Complete-Wdu $Config $Paths $State 'Failed' "Windows Update scan keeps failing: $($_.Exception.Message) $hr"
        }

        $plan = Get-WduPlan $updates $Config $State
        Write-WduLog ("Found {0} update(s): {1} to install, {2} skipped by policy, {3} given up." -f @($updates).Count, @($plan.Install).Count, @($plan.Skipped).Count, @($plan.GaveUp).Count)

        if (@($plan.Install).Count -eq 0) {
            if (Test-WduRebootPending) { return Request-WduReboot $Config $Paths $State 'a restart is pending to finish installed updates' $plan }
            $emptyScans++
            if ($emptyScans -le [int] $Config.confirmationScans) {
                Write-WduLog "Nothing to install; confirmation scan $emptyScans/$($Config.confirmationScans) after $($Config.confirmationDelaySeconds) s."
                Set-WduStatus 'Confirming' "Confirmation scan $emptyScans" $State
                Wait-Wdu ([int] $Config.confirmationDelaySeconds)
                continue
            }
            if (@($plan.GaveUp).Count -gt 0) {
                return Complete-Wdu $Config $Paths $State 'CompletedWithFailures' "$(@($plan.GaveUp).Count) update(s) failed repeatedly and were given up." $plan
            }
            return Complete-Wdu $Config $Paths $State 'Succeeded' 'No applicable updates remain.' $plan
        }
        $emptyScans = 0

        # Coordination: no update installation while an application is being installed.
        $lock = Enter-WdbInstallLock $Config.dataRoot 'WindowsUpdate' ([int] $Config.lockWaitMinutes * 60)
        if (-not $lock) {
            Write-WduLog 'Another installation holds the install lock; trying again at the next start.' 'WARN'
            Set-WduStatus 'WaitingForLock' '' $State
            return 'WaitingForLock'
        }
        try {
        # Count the attempt before acting, so a crash or hang mid-install still counts.
        foreach ($u in $plan.Install) {
            $a = $State.attempts[$u.Id]
            if (-not $a) { $a = @{ count = 0; title = $u.Title; kbs = @($u.Kbs); lastResult = ''; lastHResult = '' }; $State.attempts[$u.Id] = $a }
            $a.count = [int] $a.count + 1
            Write-WduLog ("  queued   {0} (attempt {1}/{2})" -f (Get-WduLabel $u), $a.count, $Config.maxAttemptsPerUpdate)
        }
        Save-WduState $State $Paths

        Set-WduStatus 'Downloading' "$(@($plan.Install).Count) update(s)" $State
        $dl = Invoke-WduDownload $plan.Install
        $ready = @()
        foreach ($u in $plan.Install) {
            $r = $dl[$u.Id]
            if ($r -and $r.Result -in 'Succeeded', 'SucceededWithErrors') { $ready += $u; continue }
            $a = $State.attempts[$u.Id]
            $a.lastResult = if ($r) { "Download$($r.Result)" } else { 'DownloadMissing' }
            $a.lastHResult = if ($r) { Format-WduHResult $r.HResult } else { '' }
            Write-WduLog ("  download failed {0}: {1} {2}" -f (Get-WduLabel $u), $a.lastResult, $a.lastHResult) 'WARN'
        }

        $rebootRequired = $false
        if ($ready.Count -gt 0) {
            Set-WduStatus 'Installing' "$($ready.Count) update(s)" $State
            $in = Invoke-WduInstall $ready
            $rebootRequired = [bool] $in.RebootRequired
            foreach ($u in $ready) {
                $r = $in.Results[$u.Id]
                $a = $State.attempts[$u.Id]
                $a.lastResult = if ($r) { $r.Result } else { 'Missing' }
                $a.lastHResult = if ($r) { Format-WduHResult $r.HResult } else { '' }
                if ($r -and $r.Result -in 'Succeeded', 'SucceededWithErrors') {
                    $State.installed += @{ id = $u.Id; title = $u.Title; kbs = @($u.Kbs); result = $r.Result; atUtc = (Get-WduNow).ToString('o') }
                    Write-WduLog ("  installed {0} ({1})" -f (Get-WduLabel $u), $r.Result)
                } else {
                    Write-WduLog ("  install failed {0}: {1} {2}" -f (Get-WduLabel $u), $a.lastResult, $a.lastHResult) 'WARN'
                }
            }
        }
        Save-WduState $State $Paths
        } finally {
            Exit-WdbInstallLock $lock
        }

        # An update about to be given up gets one more chance after a component reset.
        $exhausted = @($plan.Install | Where-Object {
            $a = $State.attempts[$_.Id]
            [int] $a.count -ge [int] $Config.maxAttemptsPerUpdate -and $a.lastResult -notin 'Succeeded', 'SucceededWithErrors'
        })
        if ($exhausted.Count -gt 0 -and $Config.resetComponentsOnce -and -not $State.componentReset) {
            Write-WduLog "$($exhausted.Count) update(s) keep failing; resetting Windows Update components once." 'WARN'
            Set-WduStatus 'ResettingComponents' 'Repeated update failures' $State
            Reset-WduComponents
            $State.componentReset = $true
            foreach ($u in $exhausted) { $State.attempts[$u.Id].count = [int] $Config.maxAttemptsPerUpdate - 1 }
            Save-WduState $State $Paths
            return Request-WduReboot $Config $Paths $State 'Windows Update components were reset'
        }

        if ($rebootRequired -or (Test-WduRebootPending)) {
            return Request-WduReboot $Config $Paths $State 'installed updates require a restart'
        }
    }
    return Complete-Wdu $Config $Paths $State 'Failed' 'Safety limit of 50 passes without a restart reached.'
}

function Invoke-WduMain {
    param([hashtable] $Config)
    $paths = Get-WduPaths $Config
    foreach ($d in $paths.Root, $paths.Logs) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } }
    $script:LogFile = $paths.Log
    $script:StatusFile = $paths.Status
    Limit-WduLogSize $paths.Log

    $mutex = Enter-WduMutex $Config.mutexName
    if (-not $mutex) {
        Write-WduLog 'Another engine instance is running; exiting.'
        return 'AlreadyRunning'
    }
    try {
        return Invoke-WduRun -Config $Config -Paths $paths
    } catch {
        $err = $_
        Write-WduLog "Unhandled error: $($err.Exception.Message) $(Format-WduHResult $err.Exception.HResult)`r`n$($err.ScriptStackTrace)" 'ERROR'
        $state = Read-WduState $paths
        $state.errors = [int] $state.errors + 1
        Save-WduState $state $paths
        if ($state.errors -ge [int] $Config.maxErrors -and -not $state.final) {
            return Complete-Wdu $Config $paths $state 'Failed' "Stopped after $($state.errors) unexpected errors. Last: $($err.Exception.Message)"
        }
        Set-WduStatus 'Error' "$($err.Exception.Message) (will retry)" $state
        return 'Error'
    } finally {
        Exit-WduMutex $mutex
    }
}

function Invoke-WduScan {
    param([hashtable] $Config)
    $state = New-WduState
    $updates = Get-WduAvailableUpdates $Config
    $plan = Get-WduPlan $updates $Config $state
    $rows = @()
    foreach ($u in $plan.Install) { $rows += [pscustomobject]@{ Action = 'Install'; KB = ($u.Kbs -join ','); Title = $u.Title; Reason = '' } }
    foreach ($s in $plan.Skipped) { $rows += [pscustomobject]@{ Action = 'Skip'; KB = ($s.kbs -join ','); Title = $s.title; Reason = $s.reason } }
    [pscustomobject]@{
        Updates       = $rows
        RebootPending = Test-WduRebootPending
        InstallerBusy = Test-WduInstallerBusy
    }
}

# Dot-sourcing (tests) only defines the functions.
if ($MyInvocation.InvocationName -ne '.') {
    $cfg = Get-WduConfig $ConfigPath
    if ($Mode -eq 'Scan') {
        $scan = Invoke-WduScan $cfg
        $scan.Updates | Format-Table -AutoSize -Wrap | Out-String -Width 200
        "Reboot pending: $($scan.RebootPending). Installer busy: $($scan.InstallerBusy)."
        exit 0
    }
    $outcome = Invoke-WduMain $cfg
    Write-Output $outcome
    if ($outcome -eq 'Error' -or $outcome -eq 'Finished:Failed') { exit 1 }
    exit 0
}

#Requires -Version 5.1 <# .SYNOPSIS Windows Deployment Builder - WinGet application provisioning engine.
.DESCRIPTION Installs the selected WinGet packages after Windows setup, one at a time, with explicit identifiers and sources, and records a result for every package. Written independently for this project on documented interfaces (winget.exe, Appx cmdlets, Task Scheduler); no third-party code.
Runs as the signed-in user with full (elevated) rights from the scheduled task \WindowsDeploymentBuilder\Applications. WinGet is a per-user packaged app and is not supported in the SYSTEM account, so this engine refuses to run as SYSTEM.
Order of work on each start: 1. Preparation (allowed while Windows Update runs): network, WinGet check (no repair), package availability ("winget show"). 2. Gate (coordination policy "updatesFirst"): waits until the Windows Update engine has a final result, or is not part of this deployment. 3. WinGet repair when needed (under the install lock), then the queue: for each package "winget list" (already installed?) and "winget install" while holding the machine-wide install lock, so Windows Update cannot restart the computer meanwhile. 4. Additional Software (manual follow-up entries; automatic only for reviewed installers). Catalog entries without an unattended installation are reported as manual follow-ups; portable packages get a Start menu shortcut after installation (engine 1.1.0). 5. Restart when packages require it (policy), resume after sign-in, verify, finish.
Package results: Pending, Installing, Succeeded, AlreadyInstalled, Skipped, SkippedByUser, RequiresInteraction, RequiresRestart, Failed, Unavailable. (SkippedByUser: deselected for this deployment, recorded so the report shows it; RequiresInteraction also covers manual follow-ups.) Final states (result.json): Succeeded, CompletedWithFollowUp, CompletedWithFailures, Failed, Offline. The marker <dataRoot>\state\applications.done is written for the first three.
Resilience (engine 1.2.0, Phase 5): every failure is classified (Transient, Network, Timeout, Resource, Unknown are retried; Permanent, Integrity, Policy, User are not), retries wait with bounded exponential backoff and jitter, a network-class failure is checked against the network and the package source before it counts (lost connectivity defers the package instead of failing it), every attempt is recorded (state history and logs\attempts.jsonl), and the state file is replaced atomically with a backup of the last good copy. The status values above are unchanged; the lifecycle (Pending, Running, Succeeded, AlreadySatisfied, FailedRetryable, FailedPermanent, WaitingForNetwork, WaitingForReboot, ManualActionRequired, SkippedByUser, BlockedByDependency) is derived from them (Get-WdaLifecycle).
Modes: Run (default) Full engine. Plan Read-only dry run: WinGet check, installed/available state and the exact command for every package. Installs nothing, writes nothing, needs no elevation. Retry Technician recovery (called by DeploymentRecovery.ps1): reopens failed or unfinished operations of this deployment for another run. Installs nothing itself. #> [CmdletBinding()] param( [ValidateSet('Run', 'Plan', 'Retry')] [string] $Mode = 'Run', [string] $ConfigPath = '', # Retry mode only: operation ids ("app:winget:git.git", "additional:<id>") or -AllFailed / -PendingOnly. [string[]] $Operation = @(), [switch] $AllFailed, [switch] $PendingOnly, [switch] $IncludePermanent )
Set-StrictMode -Version 2.0 $ErrorActionPreference = 'Stop'
$script:EngineVersion = '1.2.0' $script:StateVersion = 2 $script:EventSource = 'WindowsDeploymentBuilder' $script:LogFile = $null $script:StatusFile = $null $script:WinGet = $null
$script:WingetId = '^(?=.{3,128}$)[A-Za-z0-9][A-Za-z0-9_+-]{0,31}(?:\.[A-Za-z0-9_+-]{1,32}){1,7}$' $script:StoreId = '^(?:9[A-Z0-9]{11}|XP[A-Z0-9]{12})$' $script:VersionPattern = '^[A-Za-z0-9][A-Za-z0-9._+-]{0,63}$' $script:SafeToken = '^[A-Za-z0-9][A-Za-z0-9._+-]{0,127}$|^--[a-z][a-z-]{1,40}$|^(list|show|install)$' # Portable packages: shortcut target pattern and name (plain names; see catalog.ts PORTABLE_EXE/SHORTCUT_NAME). $script:PortableExe = '^[A-Za-z0-9][A-Za-z0-9._+*-]{0,79}\.exe$' $script:ShortcutName = '^[A-Za-z0-9][A-Za-z0-9 ._()+-]{0,59}$' $script:CatalogKey = '^catalog:[a-z0-9][a-z0-9-]{0,47}$'
# WinGet HRESULTs (AppInstallerErrors.h) -> Status, Retry, Restart (none|later|now|initiated), Text, Class. # Class (Phase 5): Success, Restart, Network, Transient, Resource (retried automatically while the # budget lasts, Resource only where Retry is true), Permanent, Integrity, Policy, User (never retried # automatically; Integrity and Policy failures are never weakened by a retry). $script:ExitCodes = @{ '0x00000000' = @('Succeeded', $false, 'none', 'Installed.', 'Success') '0x8A150061' = @('AlreadyInstalled', $false, 'none', 'Already installed (PACKAGE_ALREADY_INSTALLED).', 'Success') '0x8A15010D' = @('AlreadyInstalled', $false, 'none', 'Already installed (INSTALL_ALREADY_INSTALLED).', 'Success') '0x8A15002B' = @('AlreadyInstalled', $false, 'none', 'Installed; no applicable upgrade (UPDATE_NOT_APPLICABLE).', 'Success') '0x8A15010E' = @('AlreadyInstalled', $false, 'none', 'A newer version is already installed (INSTALL_DOWNGRADE).', 'Success') '0x8A150109' = @('RequiresRestart', $false, 'later', 'Installed; a restart is required to finish (INSTALL_REBOOT_REQUIRED_TO_FINISH).', 'Restart') '0x8A15010A' = @('RequiresRestart', $true, 'now', 'A restart is required before it can install (INSTALL_REBOOT_REQUIRED_FOR_INSTALL).', 'Restart') '0x8A15010B' = @('RequiresRestart', $false, 'initiated', 'The installer started a restart (INSTALL_REBOOT_INITIATED).', 'Restart') '0x00000BC2' = @('RequiresRestart', $false, 'later', 'Installed; a restart is required to finish (3010).', 'Restart') '0x00000669' = @('RequiresRestart', $false, 'initiated', 'The installer started a restart (1641).', 'Restart') '0x8A150014' = @('Unavailable', $false, 'none', 'No package with this identifier in the source (NO_APPLICATIONS_FOUND).', 'Permanent') '0x8A150113' = @('Unavailable', $false, 'none', 'The package does not support this system (INSTALL_SYSTEM_NOT_SUPPORTED).', 'Permanent') '0x8A150016' = @('Failed', $false, 'none', 'More than one package matched (MULTIPLE_APPLICATIONS_FOUND).', 'Permanent') '0x8A15010C' = @('RequiresInteraction', $false, 'none', 'The installer was cancelled or needs a person (INSTALL_CANCELLED_BY_USER).', 'User') '0x8A150011' = @('Failed', $false, 'none', 'Installer hash mismatch; not installed for safety (INSTALLER_HASH_MISMATCH).', 'Integrity') '0x8A15003A' = @('Failed', $false, 'none', 'Blocked by policy (BLOCKED_BY_POLICY).', 'Policy') '0x8A15010F' = @('Failed', $false, 'none', 'Blocked by policy (INSTALL_BLOCKED_BY_POLICY).', 'Policy') '0x8A15001B' = @('Failed', $false, 'none', 'Microsoft Store blocked by policy (MSSTORE_BLOCKED_BY_POLICY).', 'Policy') '0x8A15001C' = @('Failed', $false, 'none', 'App blocked by Store policy (MSSTORE_APP_BLOCKED_BY_POLICY).', 'Policy') '0x8A150041' = @('Failed', $false, 'none', 'Package agreements not accepted (PACKAGE_AGREEMENTS_NOT_ACCEPTED).', 'Permanent') '0x8A150046' = @('Failed', $false, 'none', 'Source agreements not accepted (SOURCE_AGREEMENTS_NOT_ACCEPTED).', 'Permanent') '0x8A150105' = @('Failed', $false, 'none', 'Not enough disk space (INSTALL_DISK_FULL).', 'Resource') '0x8A150107' = @('Failed', $true, 'none', 'No network (INSTALL_NO_NETWORK).', 'Network') '0x8A150008' = @('Failed', $true, 'none', 'Download failed (DOWNLOAD_FAILED).', 'Network') '0x8A150045' = @('Failed', $true, 'none', 'The source could not be opened (SOURCE_OPEN_FAILED).', 'Network') '0x8A150101' = @('Failed', $true, 'none', 'The application is in use (INSTALL_PACKAGE_IN_USE).', 'Transient') '0x8A150102' = @('Failed', $true, 'none', 'Another installation is in progress (INSTALL_INSTALL_IN_PROGRESS).', 'Transient') '0x8A150103' = @('Failed', $true, 'none', 'A file is in use (INSTALL_FILE_IN_USE).', 'Transient') '0x8A150111' = @('Failed', $true, 'none', 'The application is in use (INSTALL_PACKAGE_IN_USE_BY_APPLICATION).', 'Transient') '0x8A150104' = @('Failed', $true, 'none', 'A dependency is missing (INSTALL_MISSING_DEPENDENCY).', 'Transient') '0x8A150110' = @('Failed', $true, 'none', 'Dependencies could not be installed (INSTALL_DEPENDENCIES).', 'Transient') '0x8A150106' = @('Failed', $true, 'none', 'Not enough memory (INSTALL_INSUFFICIENT_MEMORY).', 'Resource') }
$script:Terminal = @('Succeeded', 'AlreadyInstalled', 'Skipped', 'SkippedByUser', 'RequiresInteraction', 'Failed', 'Unavailable')
# ------------------------------------------------------------------------------------------------ # Small helpers (time, waiting, JSON) - kept as functions so tests can replace them. # ------------------------------------------------------------------------------------------------
function Get-WdaNow { [DateTime]::UtcNow }
function Wait-Wda { param([int] $Seconds) if ($Seconds -gt 0) { Start-Sleep -Seconds $Seconds } }
function ConvertTo-WdaDate { param($Value) if ($Value -is [DateTime]) { return $Value.ToUniversalTime() } [DateTime]::Parse([string] $Value, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime() }
function Format-WdaHResult { param($Code) if ($null -eq $Code -or "$Code" -eq '') { return '' } '0x{0:X8}' -f ([int64] $Code -band [int64] 4294967295) }
function ConvertTo-WdaHashtable { param($InputObject) if ($null -eq $InputObject) { return $null } if ($InputObject -is [System.Collections.IDictionary]) { $h = @{} foreach ($k in $InputObject.Keys) { $h[$k] = ConvertTo-WdaHashtable $InputObject[$k] } return $h } if ($InputObject -is [System.Management.Automation.PSCustomObject]) { $h = @{} foreach ($p in $InputObject.PSObject.Properties) { $h[$p.Name] = ConvertTo-WdaHashtable $p.Value } return $h } if ($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [string]) { return , @($InputObject | ForEach-Object { ConvertTo-WdaHashtable $_ }) } return $InputObject }
<# Atomic write: the JSON goes to <Path>.tmp (written through to disk), then replaces <Path> in one file-system operation. -Backup keeps the replaced file as <Path>.bak (the last good copy), so a power loss can leave the old file, the new file or both, never a half-written one. #> function Write-WdaJson { param([string] $Path, $Value, [switch] $Backup) $json = $Value | ConvertTo-Json -Depth 12 $tmp = "$Path.tmp" $bytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes($json) $fs = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 4096, [System.IO.FileOptions]::WriteThrough) try { $fs.Write($bytes, 0, $bytes.Length); $fs.Flush($true) } finally { $fs.Dispose() } if (Test-Path -LiteralPath $Path) { try { [System.IO.File]::Replace($tmp, $Path, $(if ($Backup) { "$Path.bak" } else { $null })) return } catch { # Replace is unavailable on some file systems; fall back to copy-aside and move. if ($Backup) { Copy-Item -LiteralPath $Path -Destination "$Path.bak" -Force } } } Move-Item -LiteralPath $tmp -Destination $Path -Force }
function Read-WdaJson { param([string] $Path) if (-not (Test-Path -LiteralPath $Path)) { return $null } # UTF-8 explicitly: Get-Content would read a BOM-less file in the ANSI code page in PowerShell 5.1. ConvertTo-WdaHashtable ([System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8) | ConvertFrom-Json) }
# ------------------------------------------------------------------------------------------------ # Configuration, paths, logging, status # ------------------------------------------------------------------------------------------------
function Get-WdaConfig { param([string] $Path) if (-not $Path) { $Path = Join-Path $PSScriptRoot 'applications-config.json' } $raw = Read-WdaJson $Path if (-not $raw) { throw "Configuration file not found: $Path" } $defaults = @{ dataRoot = 'C:\ProgramData\WindowsDeploymentBuilder' taskPath = '\WindowsDeploymentBuilder\' taskName = 'Applications' mutexName = 'Global\WindowsDeploymentBuilder-Applications' packagesFile = 'winget-packages.json' restartPolicy = 'whenRequired' registerAppInstaller = $true onlineRepair = $false minimumWinGetVersion = '1.6.0' maxReboots = 3 maxAttemptsPerPackage = 2 packageTimeoutMinutes = 30 networkWaitMinutes = 15 maxRuntimeHours = 4 waitForUpdatesHours = 8 gatePollMinutes = 50 lockWaitMinutes = 60 maxErrors = 5 rebootWarningSeconds = 60 retryDelaySeconds = 30 packages = @() unresolved = @() additionalSoftware = @() manual = @() deselected = @() coordination = @{ policy = 'updatesFirst'; windowsUpdate = @{ enabled = $false } } } foreach ($k in @($defaults.Keys)) { if (-not $raw.ContainsKey($k) -or $null -eq $raw[$k]) { $raw[$k] = $defaults[$k] } } foreach ($k in 'packages', 'unresolved', 'additionalSoftware', 'manual', 'deselected') { $raw[$k] = @($raw[$k] | Where-Object { $_ }) } $raw.configDirectory = Split-Path -Parent ([IO.Path]::GetFullPath($Path)) return $raw }
function Get-WdaPaths { param([hashtable] $Config) $root = Join-Path $Config.dataRoot 'Applications' @{ Root = $root Logs = Join-Path $root 'logs' Log = Join-Path (Join-Path $root 'logs') 'engine.log' PackageLogs = Join-Path (Join-Path $root 'logs') 'packages' State = Join-Path $root 'state.json' Status = Join-Path $root 'status.json' Result = Join-Path $root 'result.json' FollowUp = Join-Path $root 'follow-up.txt' Installers = Join-Path $root 'installers' Offline = Join-Path $root 'offline' MarkerDir = Join-Path $Config.dataRoot 'state' Marker = Join-Path (Join-Path $Config.dataRoot 'state') 'applications.done' } }
function Write-WdaLog { param([string] $Message, [ValidateSet('INFO', 'WARN', 'ERROR')] [string] $Level = 'INFO') $line = '{0} {1,-5} {2}' -f (Get-WdaNow).ToString('yyyy-MM-dd HH:mm:ss'), $Level, $Message Write-Verbose $line if (-not $script:LogFile) { return } for ($i = 0; $i -lt 3; $i++) { try { [System.IO.File]::AppendAllText($script:LogFile, $line + "`r`n"); return } catch { Start-Sleep -Milliseconds 200 } } }
function Limit-WdaLogSize { param([string] $Path, [int64] $MaxBytes = 5MB) if ((Test-Path -LiteralPath $Path) -and (Get-Item -LiteralPath $Path).Length -gt $MaxBytes) { Move-Item -LiteralPath $Path -Destination "$Path.1" -Force } }
function Set-WdaStatus { param([string] $Phase, [string] $Detail = '', [hashtable] $State) if (-not $script:StatusFile) { return } $o = [ordered]@{ phase = $Phase detail = $Detail updatedUtc = (Get-WdaNow).ToString('o') computer = $env:COMPUTERNAME version = $script:EngineVersion } if ($State) { $o.starts = $State.starts $o.reboots = $State.reboots $o.done = @($State.packages.Values | Where-Object { $_.status -in $script:Terminal }).Count $o.total = @($State.packages.Values).Count } try { Write-WdaJson $script:StatusFile $o } catch { Write-WdaLog "Could not write status: $($_.Exception.Message)" 'WARN' } }
function Write-WdaEvent { param([int] $EventId, [string] $Message, [ValidateSet('Information', 'Warning', 'Error')] [string] $EntryType = 'Information') try { if (-not [System.Diagnostics.EventLog]::SourceExists($script:EventSource)) { New-EventLog -LogName Application -Source $script:EventSource } Write-EventLog -LogName Application -Source $script:EventSource -EventId $EventId -EntryType $EntryType -Message $Message } catch { Write-WdaLog "Could not write event $EventId to the Application log: $($_.Exception.Message)" 'WARN' } }
# ------------------------------------------------------------------------------------------------ # State # ------------------------------------------------------------------------------------------------
function New-WdaState { @{ version = $script:StateVersion firstStartUtc = $null installStartUtc = $null starts = 0 reboots = 0 errors = 0 offlineStarts = 0 everOnline = $false prepared = $false restartForPending = $false bootstrap = $null packages = @{} additional = @{} final = $null # Phase 5: technician recoveries (Retry mode) and where this state came from. recoveries = @() recoveredFrom = '' originalStartUtc = $null halted = '' } }
$script:PackageStatuses = @('Pending', 'Installing', 'Succeeded', 'AlreadyInstalled', 'Skipped', 'SkippedByUser', 'RequiresInteraction', 'RequiresRestart', 'Failed', 'Unavailable')
<# Fields every entry has since state version 2; older entries get them without changing status. #> function Add-WdaEntryFields { param([hashtable] $Entry, [string] $Kind = 'app') $id = $(if ($Kind -eq 'additional') { "additional:$($Entry['id'])" } else { "app:$($Entry['key'])" }) $defaults = @{ operationId = $id; failureClass = ''; retryable = $false; nextAttemptUtc = $null; waitingFor = ''; detection = '' history = @(); networkDeferrals = 0; manualRetries = 0; totalAttempts = [int] $Entry['attempts']; interrupted = $false; restart = ''; restartBoot = '' } foreach ($k in @($defaults.Keys)) { if (-not $Entry.ContainsKey($k)) { $Entry[$k] = $defaults[$k] } } if ($null -eq $Entry.history) { $Entry.history = @() } $Entry.history = @($Entry.history | Where-Object { $_ -is [hashtable] }) }
<# Accepts a state only if its shape is sane: a version this engine understands, entry maps whose keys match their entries, known statuses and numeric attempt counts. Anything else is treated as corrupt (and never as "nothing installed yet", see Read-WdaState). Returns a reason or $null. #> function Test-WdaStateShape { param($S) if ($S -isnot [hashtable]) { return 'not an object' } if (-not $S.ContainsKey('version') -or "$($S.version)" -notmatch '^\d{1,3}$' -or [int] $S.version -lt 1 -or [int] $S.version -gt $script:StateVersion) { return "unsupported state version '$(if ($S.ContainsKey('version')) { $S.version })'" } foreach ($map in 'packages', 'additional') { if (-not $S.ContainsKey($map) -or $null -eq $S[$map]) { continue } if ($S[$map] -isnot [hashtable]) { return "$map is not a map" } foreach ($k in @($S[$map].Keys)) { $e = $S[$map][$k] if ($e -isnot [hashtable]) { return "entry $k is not an object" } $own = $(if ($map -eq 'packages') { [string] $e['key'] } else { [string] $e['id'] }) if ($own -ne $k) { return "entry $k does not match its key" } if ([string] $e['status'] -notin $script:PackageStatuses) { return "entry $k has an unknown status '$($e['status'])'" } if ("$($e['attempts'])" -notmatch '^\d{1,4}$') { return "entry $k has an invalid attempt count" } } } if ($S.ContainsKey('final') -and $S.final -and [string] $S.final -notin 'Succeeded', 'CompletedWithFollowUp', 'CompletedWithFailures', 'Failed', 'Offline') { return "unknown final status '$($S.final)'" } return $null }
<# Reads the state. A missing file is a first start. An unreadable or malformed file is kept aside (state.json.corrupt) and the last good copy (state.json.bak, written by every save) is used instead; only when that is unusable too does the engine start over, and then every package is checked with "winget list" before anything is installed, so nothing completed is repeated. Version 1 states are upgraded in place without changing any status (completed work stays done). #> function Read-WdaState { param([hashtable] $Paths) $fresh = New-WdaState $s = $null $from = '' foreach ($candidate in @($Paths.State, "$($Paths.State).bak")) { if (-not (Test-Path -LiteralPath $candidate)) { continue } $reason = $null try { $s = Read-WdaJson $candidate; $reason = Test-WdaStateShape $s } catch { $reason = $_.Exception.Message } if (-not $reason) { if ($candidate -ne $Paths.State) { $from = 'backup' }; break } Write-WdaLog "State file $(Split-Path -Leaf $candidate) is unusable ($reason); keeping a copy." 'WARN' Copy-Item -LiteralPath $candidate -Destination "$candidate.corrupt" -Force -ErrorAction SilentlyContinue $s = $null $from = 'rebuilt' } if (-not $s) { if ($from) { $fresh.recoveredFrom = $from; Write-WdaLog 'Starting with a new state; every package is checked with winget list before any installation.' 'WARN' } return $fresh } if ($from) { $s.recoveredFrom = $from; Write-WdaLog 'Recovered the state from its last good copy (state.json.bak).' 'WARN' } foreach ($k in @($fresh.Keys)) { if (-not $s.ContainsKey($k)) { $s[$k] = $fresh[$k] } } if ($null -eq $s.packages) { $s.packages = @{} } if ($null -eq $s.additional) { $s.additional = @{} } if ($null -eq $s.recoveries) { $s.recoveries = @() } foreach ($e in @($s.packages.Values)) { Add-WdaEntryFields $e 'app' } foreach ($e in @($s.additional.Values)) { Add-WdaEntryFields $e 'additional' } $s.version = $script:StateVersion return $s }
function Save-WdaState { param([hashtable] $State, [hashtable] $Paths) Write-WdaJson $Paths.State $State -Backup }
# ------------------------------------------------------------------------------------------------ # Package queue. The native WinGet package list is the package specification; applications-config # adds order and metadata. Every identifier is validated again here (defence in depth). # ------------------------------------------------------------------------------------------------
function Get-WdaKey { param([string] $Source, [string] $Id) "$($Source.ToLowerInvariant()):$($Id.ToLowerInvariant())" }
function Test-WdaPackageSpec { param([hashtable] $P) $source = [string] $P.source $id = [string] $P.packageIdentifier if ($source -eq 'winget') { if ($id -cnotmatch $script:WingetId) { return "Invalid winget identifier '$id'." } } elseif ($source -eq 'msstore') { if ($id -cnotmatch $script:StoreId) { return "Invalid Microsoft Store identifier '$id'." } } else { return "Unsupported source '$source'." } if ($P.version -and ([string] $P.version) -cnotmatch $script:VersionPattern) { return "Invalid version '$($P.version)'." } if ($P.scope -and $P.scope -notin 'user', 'machine') { return "Invalid scope '$($P.scope)'." } if ($P.method -and $P.method -notin 'winget', 'msstore', 'portable') { return "Unsupported installation method '$($P.method)'." } if ($P.method -eq 'portable') { if ($source -ne 'winget' -or $P.scope -ne 'machine') { return 'Portable packages must come from winget with machine scope.' } if (-not $P.portable -or ([string] $P.portable.executable) -cnotmatch $script:PortableExe -or ([string] $P.portable.shortcut) -cnotmatch $script:ShortcutName) { return 'Invalid portable shortcut definition.' } } return $null }
function Read-WdaNativePackages { param([string] $Path) $out = @() if (-not (Test-Path -LiteralPath $Path)) { return , $out } $doc = Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json foreach ($s in @($doc.Sources)) { $d = $s.SourceDetails $source = switch -Regex ([string] $d.Identifier) { '^Microsoft\.Winget\.Source_8wekyb3d8bbwe$' { 'winget'; break } '^StoreEdgeFD$' { 'msstore'; break } default { [string] $d.Name } } foreach ($p in @($s.Packages)) { $id = [string] $p.PackageIdentifier if ($source -eq 'msstore') { $id = $id.ToUpperInvariant() } $version = ''; $scope = '' if ($p.PSObject.Properties['Version']) { $version = [string] $p.Version } if ($p.PSObject.Properties['Scope']) { $scope = [string] $p.Scope } $out += @{ packageIdentifier = $id; source = $source; version = $version; scope = $scope } } } return , $out }
function Get-WdaQueue { param([hashtable] $Config) $native = Read-WdaNativePackages (Join-Path $Config.configDirectory $Config.packagesFile) $nativeKeys = @{} foreach ($n in $native) { $nativeKeys[(Get-WdaKey $n.source $n.packageIdentifier)] = $n } $queue = @() $seen = @{} foreach ($p in @($Config.packages)) { $k = Get-WdaKey $p.source $p.packageIdentifier if ($seen.ContainsKey($k)) { continue } $seen[$k] = $true $queue += @{ key = $k; packageIdentifier = [string] $p.packageIdentifier; source = [string] $p.source name = $(if ($p.displayName) { [string] $p.displayName } else { [string] $p.packageIdentifier }) version = [string] $p.version; scope = [string] $p.scope interaction = $(if ($p.interaction) { [string] $p.interaction } else { 'unknown' }) after = @($p.after | Where-Object { $_ }); inNative = $nativeKeys.ContainsKey($k) # Optional since engine 1.1.0: configs written for 1.0.0 have neither key (StrictMode # throws on a missing hashtable key, so test for it first). method = $(if ($p.ContainsKey('method') -and $p.method) { [string] $p.method } else { [string] $p.source }) portable = $(if ($p.ContainsKey('portable') -and $p.portable -is [hashtable]) { @{ executable = [string] $p.portable['executable']; shortcut = [string] $p.portable['shortcut'] } } else { $null }) } } # Packages only in the native list (for example a WinGet export placed there by hand). foreach ($n in $native) { $k = Get-WdaKey $n.source $n.packageIdentifier if ($seen.ContainsKey($k)) { continue } $seen[$k] = $true $queue += @{ key = $k; packageIdentifier = $n.packageIdentifier; source = $n.source; name = $n.packageIdentifier version = $n.version; scope = $n.scope; interaction = 'unknown'; after = @(); inNative = $true; method = $n.source; portable = $null } } return , $queue }
function Get-WdaArguments { param([string] $Verb, [hashtable] $P) $a = @($Verb, '--id', $P.packageIdentifier, '--exact', '--source', $P.source) if ($Verb -eq 'install') { if ($P.version) { $a += @('--version', $P.version) } if ($P.scope) { $a += @('--scope', $P.scope) } $a += @('--silent', '--no-upgrade', '--accept-package-agreements') } $a += @('--accept-source-agreements', '--disable-interactivity') , $a }
function ConvertFrom-WdaExitCode { param($Code) $hex = Format-WdaHResult $Code $m = $script:ExitCodes[$hex] if ($m) { return @{ Status = $m[0]; Retry = $m[1]; Restart = $m[2]; Message = $m[3]; Code = $hex; Class = $m[4] } } # Unknown codes: retried within the normal budget (never more), and recorded as Unknown. @{ Status = 'Failed'; Retry = $true; Restart = 'none'; Message = "WinGet exit code $hex (not a documented WinGet result)."; Code = $hex; Class = 'Unknown' } }
# ------------------------------------------------------------------------------------------------ # System adapters. Everything that touches WinGet, the network, tasks or restarts lives here. # ------------------------------------------------------------------------------------------------
function Get-WdaContext { $id = [Security.Principal.WindowsIdentity]::GetCurrent() $principal = New-Object Security.Principal.WindowsPrincipal($id) @{ User = $id.Name; IsSystem = ($id.User.Value -eq 'S-1-5-18'); IsElevated = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } }
<# Runs winget.exe with validated tokens only. Every argument must match a strict pattern (no spaces, quotes or shell characters), so joining them into one command line cannot inject. #> function Invoke-WdaWinGet { param([string[]] $Arguments, [int] $TimeoutMinutes = 10, [string] $LogFile = '') foreach ($t in $Arguments) { if ($t -cnotmatch $script:SafeToken) { throw "Refusing unsafe WinGet argument '$t'." } } if (-not $script:WinGet) { throw 'WinGet path not resolved.' } $psi = New-Object System.Diagnostics.ProcessStartInfo $psi.FileName = $script:WinGet $psi.Arguments = $Arguments -join ' ' $psi.UseShellExecute = $false $psi.CreateNoWindow = $true $psi.RedirectStandardOutput = $true $psi.RedirectStandardError = $true $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8 $proc = [System.Diagnostics.Process]::Start($psi) $stdout = $proc.StandardOutput.ReadToEndAsync() $stderr = $proc.StandardError.ReadToEndAsync() $timedOut = -not $proc.WaitForExit([int] [Math]::Min([int]::MaxValue, $TimeoutMinutes * 60000)) if ($timedOut) { try { $proc.Kill() } catch { } } $proc.WaitForExit() $text = ($stdout.Result + $stderr.Result) -replace '[\u2580-\u259F\u2800-\u28FF]', '' -replace "(?m)^\s*[-\\|/]\s*$", '' if ($LogFile) { try { [System.IO.File]::AppendAllText($LogFile, ("`r`n> winget {0}`r`n{1}`r`nexit {2}`r`n" -f $psi.Arguments, $text.Trim(), $(if ($timedOut) { 'timeout' } else { Format-WdaHResult $proc.ExitCode }))) } catch { } } @{ ExitCode = $(if ($timedOut) { $null } else { $proc.ExitCode }); TimedOut = $timedOut; Output = $text } }
<# $true = installed, $false = not installed, $null = could not tell. #> function Test-WdaInstalled { param([hashtable] $P, [string] $LogFile = '') $r = Invoke-WdaWinGet (Get-WdaArguments 'list' $P) 5 $LogFile if ($r.TimedOut) { return $null } if ($r.ExitCode -eq 0) { return $true } if ((Format-WdaHResult $r.ExitCode) -eq '0x8A150014') { return $false } return $null }
<# Available, NotFound or Unknown. #> function Test-WdaAvailable { param([hashtable] $P, [string] $LogFile = '') $r = Invoke-WdaWinGet (Get-WdaArguments 'show' $P) 5 $LogFile if ($r.TimedOut) { return 'Unknown' } if ($r.ExitCode -eq 0) { return 'Available' } if ((Format-WdaHResult $r.ExitCode) -eq '0x8A150014') { return 'NotFound' } return 'Unknown' }
function Install-WdaPackage { param([hashtable] $P, [int] $TimeoutMinutes, [string] $LogFile = '') Invoke-WdaWinGet (Get-WdaArguments 'install' $P) $TimeoutMinutes $LogFile }
<# Folders where WinGet puts machine-scope portable packages (its documented defaults). #> function Get-WdaPortableRoots { @($env:ProgramFiles, ${env:ProgramFiles(x86)}) | Where-Object { $_ } | ForEach-Object { Join-Path $_ 'WinGet\Packages' } | Select-Object -Unique }
function Get-WdaShortcutFolder { Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs\Windows Deployment Tools' }
function New-WdaShortcutFile { param([string] $Path, [string] $Target) $shell = New-Object -ComObject WScript.Shell $lnk = $shell.CreateShortcut($Path) $lnk.TargetPath = $Target $lnk.WorkingDirectory = Split-Path -Parent $Target $lnk.Save() }
<# Finds the executable of an installed portable package inside WinGet's package folder (<root>\<PackageIdentifier>_<source id>). Only plain files below that folder count: reparse points (links, junctions) are skipped and every match must resolve inside the folder, so a crafted archive cannot redirect the shortcut. The shortest path wins (top-level file first). #> function Find-WdaPortableExe { param([string[]] $Roots, [string] $PackageIdentifier, [string] $Pattern) if ($Pattern -cnotmatch $script:PortableExe -or $PackageIdentifier -cnotmatch $script:WingetId) { return $null } foreach ($root in $Roots) { if (-not $root -or -not (Test-Path -LiteralPath $root)) { continue } $dirs = @(Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name.StartsWith("$($PackageIdentifier)_", [StringComparison]::OrdinalIgnoreCase) -and -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) }) foreach ($dir in $dirs) { $base = [IO.Path]::GetFullPath($dir.FullName).TrimEnd('\') + '\' $found = @() $level = @($dir) for ($depth = 0; $depth -lt 4 -and $level.Count; $depth++) { $next = @() foreach ($d in $level) { foreach ($f in @(Get-ChildItem -LiteralPath $d.FullName -Filter $Pattern -File -ErrorAction SilentlyContinue)) { $full = [IO.Path]::GetFullPath($f.FullName) if (-not ($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -and $full.StartsWith($base, [StringComparison]::OrdinalIgnoreCase)) { $found += $full } } $next += @(Get-ChildItem -LiteralPath $d.FullName -Directory -ErrorAction SilentlyContinue | Where-Object { -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) }) } $level = $next } if ($found.Count) { return ($found | Sort-Object Length, { $_ } | Select-Object -First 1) } } } return $null }
<# Creates (or replaces) the Start menu shortcut of a portable package. Never fails the package. #> function Set-WdaPortableShortcut { param([hashtable] $P) try { $exe = Find-WdaPortableExe @(Get-WdaPortableRoots) $P.packageIdentifier $P.portable.executable if (-not $exe) { return @{ Ok = $false; Message = "Start menu shortcut not created: $($P.portable.executable) was not found in WinGet's machine package folder." } } $folder = Get-WdaShortcutFolder if (-not (Test-Path -LiteralPath $folder)) { New-Item -ItemType Directory -Path $folder -Force | Out-Null } $lnk = Join-Path $folder ($P.portable.shortcut + '.lnk') New-WdaShortcutFile $lnk $exe return @{ Ok = $true; Message = "Start menu shortcut: $lnk -> $exe." } } catch { return @{ Ok = $false; Message = "Start menu shortcut not created: $($_.Exception.Message)" } } }
function Test-WdaNetwork { try { # Network Connectivity Status Indicator probe documented by Microsoft. $r = Invoke-WebRequest -Uri 'http://www.msftconnecttest.com/connecttest.txt' -UseBasicParsing -TimeoutSec 10 if ($r.Content -eq 'Microsoft Connect Test') { return $true } } catch { } $tcp = New-Object System.Net.Sockets.TcpClient try { $iar = $tcp.BeginConnect('cdn.winget.microsoft.com', 443, $null, $null) return ($iar.AsyncWaitHandle.WaitOne(5000) -and $tcp.Connected) } catch { return $false } finally { $tcp.Close() } }
<# Phase 5: where connectivity breaks, checked after a network-class failure. Levels, in order: NoInterface (no adapter is up), NoLocalNetwork (no default route), DnsUnavailable (the package source's host name does not resolve), SourceUnavailable (the Internet is reachable but the package source is not), InternetUnavailable, Online. A check that cannot run (missing cmdlet) is skipped rather than reported as a failure. Nothing is changed: no adapter, DNS, proxy or firewall setting is ever touched. #> function Get-WdaNetworkDiagnosis { param([string] $Source = 'winget') $hosts = @{ winget = 'cdn.winget.microsoft.com'; msstore = 'storeedgefd.dsx.mp.microsoft.com' } $target = $(if ($hosts.ContainsKey($Source)) { $hosts[$Source] } else { $hosts.winget }) try { if (Get-Command Get-NetAdapter -ErrorAction SilentlyContinue) { if (@(Get-NetAdapter -ErrorAction Stop | Where-Object { $_.Status -eq 'Up' }).Count -eq 0) { return @{ Level = 'NoInterface'; Detail = 'no network adapter is connected' } } } if (Get-Command Get-NetRoute -ErrorAction SilentlyContinue) { if (@(Get-NetRoute -DestinationPrefix '0.0.0.0/0', '::/0' -ErrorAction SilentlyContinue).Count -eq 0) { return @{ Level = 'NoLocalNetwork'; Detail = 'no default gateway' } } } } catch { } try { [void] [System.Net.Dns]::GetHostAddresses($target) } catch { return @{ Level = 'DnsUnavailable'; Detail = "$target does not resolve" } } $tcp = New-Object System.Net.Sockets.TcpClient $reachable = $false try { $iar = $tcp.BeginConnect($target, 443, $null, $null); $reachable = ($iar.AsyncWaitHandle.WaitOne(5000) -and $tcp.Connected) } catch { } finally { $tcp.Close() } if ($reachable) { return @{ Level = 'Online'; Detail = "$target reachable" } } $internet = $false try { $internet = ((Invoke-WebRequest -Uri 'http://www.msftconnecttest.com/connecttest.txt' -UseBasicParsing -TimeoutSec 10).Content -eq 'Microsoft Connect Test') } catch { } if ($internet) { return @{ Level = 'SourceUnavailable'; Detail = "$target (source $Source) is not reachable on port 443" } } return @{ Level = 'InternetUnavailable'; Detail = 'the Internet is not reachable' } }
function Test-WdaRebootPending { try { if ((New-Object -ComObject 'Microsoft.Update.SystemInfo').RebootRequired) { return $true } } catch { } foreach ($key in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired', 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { if (Test-Path -LiteralPath $key) { return $true } } return $false }
function Invoke-WdaReboot { param([int] $WarningSeconds, [string] $Reason) # p:4:2 = planned, Application: Installation & "$env:SystemRoot\System32\shutdown.exe" /r /t $WarningSeconds /d p:4:2 /c "Windows Deployment Builder: $Reason. The computer restarts in $WarningSeconds seconds; application setup resumes after sign-in." if ($LASTEXITCODE -ne 0) { throw "shutdown.exe failed with exit code $LASTEXITCODE" } }
function Test-WdaUpdateTask { param([hashtable] $WU) try { [void] (Get-ScheduledTask -TaskName $WU.taskName -TaskPath $WU.taskPath -ErrorAction Stop); return $true } catch { return $false } }
function Unregister-WdaTask { param([hashtable] $Config) try { $t = Get-ScheduledTask -TaskName $Config.taskName -TaskPath $Config.taskPath -ErrorAction Stop $t | Unregister-ScheduledTask -Confirm:$false Write-WdaLog "Removed scheduled task $($Config.taskPath)$($Config.taskName)." } catch { Write-WdaLog "Scheduled task $($Config.taskPath)$($Config.taskName) not removed: $($_.Exception.Message)" 'WARN' } }
function Get-WdaFileHash { param([string] $Path) (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function Test-WdaSignature { param([string] $Path) (Get-AuthenticodeSignature -LiteralPath $Path).Status -eq 'Valid' }
<# Runs a reviewed installer with an argument list (never through a shell). Returns the exit code. #> function Start-WdaInstaller { param([string] $Path, [string] $Type, [string[]] $Arguments, [int] $TimeoutMinutes) $quoted = @($Arguments | ForEach-Object { if ($_ -match '\s') { '"' + $_ + '"' } else { $_ } }) if ($Type -eq 'msi') { $file = Join-Path $env:SystemRoot 'System32\msiexec.exe' $quoted = @('/i', ('"' + $Path + '"')) + $quoted } else { $file = $Path } $proc = Start-Process -FilePath $file -ArgumentList $quoted -PassThru -WindowStyle Hidden if (-not $proc.WaitForExit([int] [Math]::Min([int]::MaxValue, $TimeoutMinutes * 60000))) { try { $proc.Kill() } catch { }; return $null } $proc.ExitCode }
# ------------------------------------------------------------------------------------------------ # Coordination with the Windows Update engine # ------------------------------------------------------------------------------------------------
# region WDB coordination # Shared by WindowsUpdateEngine.ps1 and ApplicationEngine.ps1; both copies must stay identical # (tests/unit/applications-engine.test.ts checks this). # # install.lock Machine-wide installation lock: a file opened exclusively. Windows releases # it when the owning process ends, so a crash can never leave a stale lock. # Whoever installs something or restarts the computer holds it. # restart-pending.json Written just before an engine schedules a restart. Valid only in the boot # it was written in (and for 30 minutes), so it disappears with the restart.
function Get-WdbBootTime { try { return (Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop).LastBootUpTime.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') } catch { return 'unknown' } }
function Wait-WdbLockPoll { Start-Sleep -Seconds 5 }
function Get-WdbCoordinationPaths { param([string] $DataRoot) $dir = Join-Path $DataRoot 'state' @{ Dir = $dir; Lock = (Join-Path $dir 'install.lock'); Restart = (Join-Path $dir 'restart-pending.json') } }
function Enter-WdbInstallLock { param([string] $DataRoot, [string] $Owner, [int] $TimeoutSeconds = 0) $p = Get-WdbCoordinationPaths $DataRoot if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null } $polls = [int] [Math]::Ceiling([Math]::Max(0, $TimeoutSeconds) / 5) for ($i = 0; ; $i++) { try { $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read) $bytes = [System.Text.Encoding]::UTF8.GetBytes(('{{"owner":"{0}","pid":{1},"sinceUtc":"{2}"}}' -f $Owner, $PID, [DateTime]::UtcNow.ToString('o'))) $fs.SetLength(0) $fs.Write($bytes, 0, $bytes.Length) $fs.Flush() return $fs } catch [System.IO.IOException] { if ($i -ge $polls) { return $null } Wait-WdbLockPoll } } }
function Exit-WdbInstallLock { param($Lock) if ($Lock) { try { $Lock.Dispose() } catch { } } }
function Get-WdbInstallLockOwner { param([string] $DataRoot) $p = Get-WdbCoordinationPaths $DataRoot try { $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite) try { return (New-Object System.IO.StreamReader($fs)).ReadToEnd() } finally { $fs.Dispose() } } catch { return '' } }
function Set-WdbRestartPending { param([string] $DataRoot, [string] $Owner, [string] $Reason) $p = Get-WdbCoordinationPaths $DataRoot if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null } $o = [ordered]@{ owner = $Owner; reason = $Reason; requestedUtc = [DateTime]::UtcNow.ToString('o'); bootTimeUtc = (Get-WdbBootTime) } [System.IO.File]::WriteAllText($p.Restart, ($o | ConvertTo-Json), (New-Object System.Text.UTF8Encoding($false))) }
function Test-WdbRestartPending { param([string] $DataRoot) $p = Get-WdbCoordinationPaths $DataRoot if (-not (Test-Path -LiteralPath $p.Restart)) { return $false } $m = $null try { $m = Get-Content -LiteralPath $p.Restart -Raw | ConvertFrom-Json } catch { } if ($m -and ([string] $m.bootTimeUtc) -eq (Get-WdbBootTime)) { $age = [DateTime]::UtcNow - [DateTime]::Parse([string] $m.requestedUtc, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime() if ($age.TotalMinutes -lt 30) { return $true } } # Written before the last restart, unreadable or abandoned: the restart is no longer pending. Remove-Item -LiteralPath $p.Restart -Force -ErrorAction SilentlyContinue return $false }
# endregion WDB coordination
<# "updatesFirst": applications are installed only after the Windows Update engine finished (any final status), or when it is not part of this deployment, or after waitForUpdatesHours. #> function Get-WdaUpdatesGate { param([hashtable] $Config, [hashtable] $State) $wu = $Config.coordination.windowsUpdate if (-not $wu -or -not $wu.enabled) { return @{ Open = $true; Reason = 'Windows Update automation is not part of this deployment.' } } $s = $null try { $s = Read-WdaJson $wu.stateFile } catch { } if ($s -and $s.final) { return @{ Open = $true; Reason = "Windows Update finished: $($s.final)." } } if (Test-Path -LiteralPath $wu.resultFile) { return @{ Open = $true; Reason = 'Windows Update result found.' } } $waited = ((Get-WdaNow) - (ConvertTo-WdaDate $State.firstStartUtc)).TotalHours if ($waited -ge [double] $Config.waitForUpdatesHours) { return @{ Open = $true; Reason = "Windows Update still not finished after $($Config.waitForUpdatesHours) h; continuing anyway."; Warn = $true } } if (-not $s -and -not (Test-WdaUpdateTask $wu) -and $waited -ge 0.5) { return @{ Open = $true; Reason = 'The Windows Update engine is not installed (no task, no state); continuing.'; Warn = $true } } @{ Open = $false; Reason = 'Waiting for Windows Update to finish.' } }
# ------------------------------------------------------------------------------------------------ # Single instance # ------------------------------------------------------------------------------------------------
function Enter-WdaMutex { param([string] $Name) $m = New-Object System.Threading.Mutex($false, $Name) try { if ($m.WaitOne([TimeSpan]::FromSeconds(10))) { return $m } } catch [System.Threading.AbandonedMutexException] { return $m } $m.Dispose() return $null }
function Exit-WdaMutex { param($Mutex) if ($Mutex) { try { $Mutex.ReleaseMutex() } catch { }; $Mutex.Dispose() } }
# ------------------------------------------------------------------------------------------------ # Package bookkeeping # ------------------------------------------------------------------------------------------------
function Set-WdaPackage { param([hashtable] $Entry, [string] $Status, [string] $Message = '', $Code = $null) $Entry.status = $Status if ($Message) { $Entry.message = $Message } if ($null -ne $Code) { $Entry.exitCode = [string] $Code } $Entry.updatedUtc = (Get-WdaNow).ToString('o') }
# ------------------------------------------------------------------------------------------------ # Retry policy, failure classes and the operation lifecycle (Phase 5) # ------------------------------------------------------------------------------------------------
# Never retried automatically; a technician may retry them after fixing the cause (-IncludePermanent). $script:PermanentClasses = @('Permanent', 'Integrity', 'Policy', 'User', 'Manual')
<# Retry settings from applications-config.json "retry" (engine 1.2.0). Configurations written for earlier engines have no "retry" block and get these defaults. Every value is clamped, so no configuration can make retries unbounded. #> function Get-WdaRetryPolicy { param([hashtable] $Config) $r = @{ automatic = $true; baseDelaySeconds = 60; maxDelaySeconds = 900; jitterRatio = 0.2; continueAfterFailure = $true; maxNetworkDeferrals = 6 } if ($Config.ContainsKey('retry') -and $Config['retry'] -is [hashtable]) { foreach ($k in @($r.Keys)) { if ($Config['retry'].ContainsKey($k) -and $null -ne $Config['retry'][$k]) { $r[$k] = $Config['retry'][$k] } } } $r.automatic = [bool] $r.automatic $r.continueAfterFailure = [bool] $r.continueAfterFailure $r.baseDelaySeconds = [int] [Math]::Min(3600, [Math]::Max(0, [int] $r.baseDelaySeconds)) $r.maxDelaySeconds = [int] [Math]::Min(3600, [Math]::Max([int] $r.baseDelaySeconds, [int] $r.maxDelaySeconds)) $r.jitterRatio = [double] [Math]::Min(0.5, [Math]::Max(0.0, [double] $r.jitterRatio)) $r.maxNetworkDeferrals = [int] [Math]::Min(24, [Math]::Max(0, [int] $r.maxNetworkDeferrals)) # Automatic retry off: one attempt per run; failures stay retryable by the recovery tool. $r.maxAttempts = $(if ($r.automatic) { [int] [Math]::Min(10, [Math]::Max(1, [int] $Config.maxAttemptsPerPackage)) } else { 1 }) return $r }
function Get-WdaRandom { Get-Random -Minimum 0.0 -Maximum 1.0 }
<# Delay before attempt n+1: base * 2^(n-1), +/- jitter, never more than maxDelaySeconds. #> function Get-WdaBackoffSeconds { param([hashtable] $Policy, [int] $Attempt) $exp = [Math]::Min(20, [Math]::Max(0, $Attempt - 1)) $d = [Math]::Min([double] $Policy.maxDelaySeconds, [double] $Policy.baseDelaySeconds * [Math]::Pow(2, $exp)) $j = 1 + [double] $Policy.jitterRatio * (2 * [double] (Get-WdaRandom) - 1) return [int] [Math]::Round([Math]::Min([double] $Policy.maxDelaySeconds, [Math]::Max(0, $d * $j))) }
<# The lifecycle state of an operation, derived from its status (one model, no second copy). #> function Get-WdaLifecycle { param([hashtable] $Entry) switch ([string] $Entry['status']) { 'Pending' { if ($Entry['waitingFor']) { return 'WaitingForNetwork' } if ([int] $Entry['attempts'] -gt 0 -or $Entry['nextAttemptUtc']) { return 'FailedRetryable' } return 'Pending' } 'Installing' { return 'Running' } 'Succeeded' { return 'Succeeded' } 'AlreadyInstalled' { return 'AlreadySatisfied' } 'SkippedByUser' { return 'SkippedByUser' } 'Skipped' { return 'BlockedByDependency' } 'RequiresRestart' { return 'WaitingForReboot' } 'RequiresInteraction' { return 'ManualActionRequired' } 'Unavailable' { return 'FailedPermanent' } 'Failed' { if ([string] $Entry['failureClass'] -in $script:PermanentClasses) { return 'FailedPermanent' }; return 'FailedRetryable' } } return 'Pending' }
<# Records one attempt: in the entry's history (last 20) and as one JSON line in logs\attempts.jsonl (machine-readable, for diagnostics and the later health dashboard). Never contains secrets: only identifiers, codes, classes and the engine's own messages. #> function Add-WdaAttempt { param([hashtable] $Paths, [hashtable] $Entry, [hashtable] $Record) $rec = [ordered]@{ operationId = $Entry.operationId; name = $Entry.name } foreach ($k in 'trigger', 'attempt', 'startUtc', 'endUtc', 'result', 'exitCode', 'class', 'countsTowardLimit', 'nextAction', 'nextAttemptUtc', 'rebootRequired', 'message', 'packageIdentifier', 'source') { if ($Record.ContainsKey($k)) { $rec[$k] = $Record[$k] } } $h = @{} foreach ($k in $rec.Keys) { if ($k -notin 'operationId', 'name') { $h[$k] = $rec[$k] } } $Entry.history = @(@(@($Entry.history) + @($h)) | Select-Object -Last 20) try { [System.IO.File]::AppendAllText((Join-Path $Paths.Logs 'attempts.jsonl'), (($rec | ConvertTo-Json -Compress -Depth 4) + "`r`n")) } catch { Write-WdaLog "Could not append to attempts.jsonl: $($_.Exception.Message)" 'WARN' } }
function Initialize-WdaEntries { param([hashtable] $Config, [hashtable] $State, [object[]] $Queue) foreach ($p in $Queue) { if ($State.packages.ContainsKey($p.key)) { continue } $e = @{ key = $p.key; name = $p.name; packageIdentifier = $p.packageIdentifier; source = $p.source; status = 'Pending' attempts = 0; exitCode = ''; message = ''; updatedUtc = (Get-WdaNow).ToString('o'); restart = ''; restartBoot = ''; interrupted = $false } $bad = Test-WdaPackageSpec $p if ($bad) { Set-WdaPackage $e 'Unavailable' "Not installed: $bad" } $State.packages[$p.key] = $e } foreach ($u in @($Config.unresolved)) { $k = Get-WdaKey ([string] $u.source) ([string] $u.packageIdentifier) if ($State.packages.ContainsKey($k)) { continue } $State.packages[$k] = @{ key = $k; name = [string] $u.displayName; packageIdentifier = [string] $u.packageIdentifier; source = [string] $u.source status = 'Unavailable'; attempts = 0; exitCode = ''; message = "Unresolved: $($u.reason)"; updatedUtc = (Get-WdaNow).ToString('o') restart = ''; restartBoot = ''; interrupted = $false } } foreach ($m in @($Config.manual)) { $k = ([string] $m.key).ToLowerInvariant() if ($k -cnotmatch $script:CatalogKey -or $State.packages.ContainsKey($k)) { continue } $how = [string] $m.instructions if ($m.ContainsKey('url') -and ([string] $m.url) -match '^https://[^\s"''<>]+$') { $how = "$how ($($m.url))" } $State.packages[$k] = @{ key = $k; name = [string] $m.displayName; packageIdentifier = $k.Substring(8); source = 'catalog' status = 'RequiresInteraction'; attempts = 0; exitCode = ''; message = "Manual action required: $how"; updatedUtc = (Get-WdaNow).ToString('o') restart = ''; restartBoot = ''; interrupted = $false } } foreach ($d in @($Config.deselected)) { $k = Get-WdaKey ([string] $d.source) ([string] $d.packageIdentifier) if ($State.packages.ContainsKey($k)) { continue } $State.packages[$k] = @{ key = $k; name = [string] $d.displayName; packageIdentifier = [string] $d.packageIdentifier; source = [string] $d.source status = 'SkippedByUser'; attempts = 0; exitCode = ''; message = 'Deselected for this deployment; not installed.'; updatedUtc = (Get-WdaNow).ToString('o') restart = ''; restartBoot = ''; interrupted = $false } } foreach ($a in @($Config.additionalSoftware)) { if ($State.additional.ContainsKey($a.id)) { continue } $State.additional[$a.id] = @{ id = $a.id; name = [string] $a.name; status = 'Pending'; attempts = 0; exitCode = ''; message = ''; updatedUtc = (Get-WdaNow).ToString('o') } } foreach ($e in @($State.packages.Values)) { $new = -not $e.ContainsKey('operationId') Add-WdaEntryFields $e 'app' if ($new -and $e.status -eq 'Unavailable') { $e.failureClass = 'Permanent' } elseif ($new -and $e.status -eq 'RequiresInteraction') { $e.failureClass = 'Manual' } } foreach ($e in @($State.additional.Values)) { Add-WdaEntryFields $e 'additional' } }
<# After a restart, packages waiting for one are verified or retried. An operation left Running (Installing) by a crash, a power loss or an installer-initiated restart is never assumed to have failed or succeeded: it goes back to Pending with "interrupted" set, and the queue checks with "winget list" whether it is installed before anything else happens. #> function Resume-WdaEntries { param([hashtable] $State, [hashtable] $Paths = $null) $boot = Get-WdbBootTime foreach ($e in @($State.packages.Values)) { if ($e.status -eq 'Installing') { $e.interrupted = $true Set-WdaPackage $e 'Pending' 'The previous attempt was interrupted; checking again.' if ($Paths) { Add-WdaAttempt $Paths $e @{ trigger = 'automatic'; attempt = [int] $e.totalAttempts; endUtc = (Get-WdaNow).ToString('o'); result = 'Interrupted'; class = 'Interrupted'; countsTowardLimit = $true; nextAction = 'reconcile with winget list'; message = 'The engine stopped during this attempt (crash, power loss or restart).' } } Write-WdaLog " $($e.name): previous attempt was interrupted." 'WARN' } elseif ($e.status -eq 'RequiresRestart' -and $e.restart -and $e.restartBoot -ne $boot) { $e.interrupted = $true Set-WdaPackage $e 'Pending' 'Checking again after the restart.' } } }
<# Portable packages: (re)creates the Start menu shortcut; a failure is noted, the package stays installed. #> function Complete-WdaPortable { param([hashtable] $P, [hashtable] $Entry) if ($P.method -ne 'portable' -or -not $P.portable) { return } $r = Set-WdaPortableShortcut $P $Entry.shortcutFailed = -not $r.Ok Set-WdaPackage $Entry $Entry.status ("$($Entry.message) $($r.Message)".Trim()) Write-WdaLog " $($P.name): $($r.Message)" $(if ($r.Ok) { 'INFO' } else { 'WARN' }) }
function Get-WdaCounts { param([hashtable] $State) $c = [ordered]@{ total = 0; succeeded = 0; alreadyInstalled = 0; skipped = 0; skippedByUser = 0; requiresInteraction = 0; requiresRestart = 0; failed = 0; unavailable = 0; pending = 0 } foreach ($e in @($State.packages.Values) + @($State.additional.Values)) { $c.total++ switch ($e.status) { 'Succeeded' { $c.succeeded++ } 'AlreadyInstalled' { $c.alreadyInstalled++ } 'Skipped' { $c.skipped++ } 'SkippedByUser' { $c.skippedByUser++ } 'RequiresInteraction' { $c.requiresInteraction++ } 'RequiresRestart' { $c.requiresRestart++ } 'Failed' { $c.failed++ } 'Unavailable' { $c.unavailable++ } default { $c.pending++ } } } $c }
# ------------------------------------------------------------------------------------------------ # Outcomes # ------------------------------------------------------------------------------------------------
function Complete-Wda { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [string] $Status, [string] $Reason, [object[]] $Queue = @()) $now = (Get-WdaNow).ToString('o') $order = @{} $i = 0 foreach ($q in $Queue) { $order[$q.key] = $i++ } # Phase 5 (result schema 2): the lifecycle, failure class and attempt history of every operation. $resilience = { param($E) [ordered]@{ operationId = [string] $E['operationId']; lifecycle = (Get-WdaLifecycle $E); failureClass = [string] $E['failureClass']; retryable = [bool] $E['retryable'] detection = [string] $E['detection']; nextAttemptUtc = $E['nextAttemptUtc']; waitingFor = [string] $E['waitingFor']; totalAttempts = [int] $E['totalAttempts'] manualRetries = [int] $E['manualRetries']; history = @($E['history']) } } $packages = @($State.packages.Values | Sort-Object @{ Expression = { if ($order.ContainsKey($_.key)) { $order[$_.key] } else { 100000 } } }, key | ForEach-Object { $o = [ordered]@{ key = $_.key; name = $_.name; packageIdentifier = $_.packageIdentifier; source = $_.source; status = $_.status attempts = [int] $_.attempts; exitCode = $_.exitCode; message = $_.message; timestampUtc = $_.updatedUtc } $x = & $resilience $_ foreach ($k in $x.Keys) { $o[$k] = $x[$k] } $o }) $additional = @($State.additional.Values | Sort-Object name | ForEach-Object { $o = [ordered]@{ id = $_.id; name = $_.name; status = $_.status; attempts = [int] $_.attempts; exitCode = $_.exitCode; message = $_.message; timestampUtc = $_.updatedUtc } $x = & $resilience $_ foreach ($k in $x.Keys) { $o[$k] = $x[$k] } $o }) $followUp = @() $outstanding = @() foreach ($e in $packages + $additional) { if ($e.status -in 'RequiresInteraction', 'RequiresRestart', 'Failed', 'Unavailable', 'Pending', 'Skipped') { $followUp += ('{0} [{1}]: {2}' -f $e.name, $e.status, $e.message) } elseif ($e.Contains('key') -and $State.packages.ContainsKey($e.key) -and $State.packages[$e.key].ContainsKey('shortcutFailed') -and $State.packages[$e.key].shortcutFailed) { $followUp += ('{0} [shortcut]: {1}' -f $e.name, $e.message) } elseif ($e.status -eq 'Succeeded' -and $e.detection -eq 'Unconfirmed') { $followUp += ('{0} [unconfirmed]: {1}' -f $e.name, $e.message) } # Outstanding work survives the end of the run: the recovery tool reads it from here. if ($e.lifecycle -notin 'Succeeded', 'AlreadySatisfied', 'SkippedByUser') { $outstanding += [ordered]@{ operationId = $e.operationId; name = $e.name; status = $e.status; lifecycle = $e.lifecycle; failureClass = $e.failureClass; retryable = $e.retryable; message = $e.message } } } $policy = Get-WdaRetryPolicy $Config $b = $State.bootstrap $result = [ordered]@{ schemaVersion = 2 stage = 'applications' status = $Status reason = $Reason engineVersion = $script:EngineVersion computer = $env:COMPUTERNAME user = $env:USERNAME startedUtc = $State.firstStartUtc finishedUtc = $now starts = $State.starts reboots = $State.reboots bootstrap = [ordered]@{ status = $(if ($b) { $b.status } else { 'NotRun' }); method = $(if ($b) { $b.method } else { '' }); winGetVersion = $(if ($b) { $b.version } else { '' }); message = $(if ($b) { $b.message } else { '' }) } counts = Get-WdaCounts $State packages = $packages additionalSoftware = $additional followUp = $followUp outstanding = $outstanding retryPolicy = [ordered]@{ automatic = $policy.automatic; maxAttempts = $policy.maxAttempts; baseDelaySeconds = $policy.baseDelaySeconds; maxDelaySeconds = $policy.maxDelaySeconds; jitterRatio = $policy.jitterRatio; continueAfterFailure = $policy.continueAfterFailure; maxNetworkDeferrals = $policy.maxNetworkDeferrals } recoveries = @($State.recoveries) stateRecoveredFrom = [string] $State.recoveredFrom } Write-WdaJson $Paths.Result $result $State.final = $Status Save-WdaState $State $Paths $text = @("Windows Deployment Builder - application setup: $Status", $Reason, '') + @($followUp | ForEach-Object { "- $_" }) try { [System.IO.File]::WriteAllText($Paths.FollowUp, ($text -join "`r`n") + "`r`n", (New-Object System.Text.UTF8Encoding($false))) } catch { } if ($Status -in 'Succeeded', 'CompletedWithFollowUp', 'CompletedWithFailures') { if (-not (Test-Path -LiteralPath $Paths.MarkerDir)) { New-Item -ItemType Directory -Path $Paths.MarkerDir -Force | Out-Null } Write-WdaJson $Paths.Marker ([ordered]@{ status = $Status; finishedUtc = $now; result = $Paths.Result }) } $level = switch ($Status) { 'Succeeded' { 'INFO' } { $_ -in 'CompletedWithFollowUp', 'CompletedWithFailures' } { 'WARN' } default { 'ERROR' } } $c = $result.counts Write-WdaLog ("FINISHED: {0}. {1} Succeeded {2}, already installed {3}, follow-up {4}, failed {5}, unavailable {6}, pending {7}, restarts {8}." -f $Status, $Reason, $c.succeeded, $c.alreadyInstalled, ($c.requiresInteraction + $c.requiresRestart), $c.failed, $c.unavailable, $c.pending, $State.reboots) $level foreach ($e in $packages) { if ($e.status -notin 'Succeeded', 'AlreadyInstalled') { Write-WdaLog (" {0,-19} {1} ({2}:{3}) {4}" -f $e.status.ToUpperInvariant(), $e.name, $e.source, $e.packageIdentifier, $e.message) } } $eventId = switch ($Status) { 'Succeeded' { 2100 } 'CompletedWithFailures' { 2101 } 'Failed' { 2102 } 'Offline' { 2103 } default { 2104 } } $entryType = switch ($Status) { 'Succeeded' { 'Information' } { $_ -in 'CompletedWithFollowUp', 'CompletedWithFailures' } { 'Warning' } default { 'Error' } } Write-WdaEvent $eventId "Application setup finished: $Status. $Reason See $($Paths.Result)." $entryType Set-WdaStatus $Status $Reason $State Unregister-WdaTask $Config return "Finished:$Status" }
function Request-WdaReboot { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [string] $Reason) $lock = Enter-WdbInstallLock $Config.dataRoot 'Applications' ([int] $Config.lockWaitMinutes * 60) if (-not $lock) { Write-WdaLog "Restart deferred ($Reason): another installation holds the install lock." 'WARN' Set-WdaStatus 'RebootDeferred' $Reason $State return 'RebootDeferred' } try { $State.reboots = [int] $State.reboots + 1 $boot = Get-WdbBootTime foreach ($e in @($State.packages.Values)) { if ($e.status -eq 'RequiresRestart') { $e.restartBoot = $boot } } Save-WdaState $State $Paths Write-WdaLog "Restart $($State.reboots)/$($Config.maxReboots): $Reason. Resuming after sign-in." Set-WdaStatus 'Rebooting' $Reason $State Write-WdaEvent 2001 "Restarting to continue application setup ($Reason)." Set-WdbRestartPending $Config.dataRoot 'Applications' $Reason Invoke-WdaReboot -WarningSeconds ([int] $Config.rebootWarningSeconds) -Reason $Reason Wait-Wda ([int] $Config.rebootWarningSeconds + 120) } finally { Exit-WdbInstallLock $lock } return 'Rebooting' }
function Test-WdaCanRestart { param([hashtable] $Config, [hashtable] $State) ($Config.restartPolicy -eq 'whenRequired') -and ([int] $State.reboots -lt [int] $Config.maxReboots) }
function Get-WdaFinalStatus { param([hashtable] $State) $c = Get-WdaCounts $State if ($c.failed -gt 0 -or $c.unavailable -gt 0) { return 'CompletedWithFailures' } if ($c.requiresInteraction -gt 0 -or $c.requiresRestart -gt 0) { return 'CompletedWithFollowUp' } # Phase 5: a success WinGet reported but winget list cannot confirm is not a silent success. if (@($State.packages.Values | Where-Object { $_.status -eq 'Succeeded' -and $_['detection'] -eq 'Unconfirmed' }).Count) { return 'CompletedWithFollowUp' } return 'Succeeded' }
# ------------------------------------------------------------------------------------------------ # Stages # ------------------------------------------------------------------------------------------------
function Invoke-WdaBootstrapStep { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [switch] $CheckOnly) $b = Invoke-WgbBootstrap -CheckOnly:$CheckOnly -AllowRegister ([bool] $Config.registerAppInstaller) -AllowOnlineRepair ([bool] $Config.onlineRepair) ` -OfflinePath $Paths.Offline -MinimumVersion ([string] $Config.minimumWinGetVersion) foreach ($s in @($b.Steps)) { Write-WdaLog " WinGet: $s" } $State.bootstrap = @{ status = $b.Status; method = $b.Method; version = $b.Version; message = $b.Message; path = $b.Path; atUtc = (Get-WdaNow).ToString('o') } if ($b.Status -in 'Healthy', 'Repaired') { $script:WinGet = $b.Path } $b }
function Invoke-WdaAvailability { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [object[]] $Queue) foreach ($p in $Queue) { $e = $State.packages[$p.key] if ($e.status -ne 'Pending' -or $e.attempts -gt 0) { continue } $a = Test-WdaAvailable $p (Join-Path $Paths.PackageLogs 'availability.log') if ($a -eq 'NotFound') { Set-WdaPackage $e 'Unavailable' "No package $($p.packageIdentifier) in source $($p.source)." '0x8A150014' Write-WdaLog " unavailable $($p.name) ($($p.source):$($p.packageIdentifier))" 'WARN' } } $State.prepared = $true }
function Invoke-WdaAdditional { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State) foreach ($a in @($Config.additionalSoftware)) { $e = $State.additional[$a.id] if ($e.status -in $script:Terminal) { continue } if ($a.execution -ne 'automatic') { $where = $(if ($a.downloadUrl) { "official download $($a.downloadUrl)" } else { 'the publisher' }) $hash = $(if ($a.sha256) { "; verify SHA-256 $($a.sha256)" } else { '' }) $e.failureClass = 'Manual' Set-WdaPackage $e 'RequiresInteraction' "Manual follow-up: install from $where$hash." continue } $file = Join-Path $Paths.Installers ([string] $a.fileName) if (-not $a.fileName -or -not (Test-Path -LiteralPath $file)) { $e.failureClass = 'Manual' Set-WdaPackage $e 'RequiresInteraction' "Installer not supplied: place $($a.fileName) in $($Paths.Installers) and run the installer again." continue } $actual = Get-WdaFileHash $file if ($actual -ne ([string] $a.sha256).ToUpperInvariant()) { $e.failureClass = 'Integrity' Set-WdaPackage $e 'Failed' "SHA-256 mismatch (expected $($a.sha256), found $actual); not executed." continue } if ($a.installerType -in 'exe', 'msi' -and -not (Test-WdaSignature $file)) { $e.failureClass = 'Integrity' Set-WdaPackage $e 'Failed' 'No valid Authenticode signature; not executed.' continue } $lock = Enter-WdbInstallLock $Config.dataRoot 'Applications' ([int] $Config.lockWaitMinutes * 60) if (-not $lock) { return 'WaitingForLock' } try { $e.attempts = [int] $e.attempts + 1 $e.totalAttempts = [int] $e.totalAttempts + 1 Set-WdaPackage $e 'Installing' Save-WdaState $State $Paths $started = (Get-WdaNow).ToString('o') $code = Start-WdaInstaller $file ([string] $a.installerType) @($a.silentArgs) ([int] $Config.packageTimeoutMinutes) $e.failureClass = '' if ($null -eq $code) { $e.failureClass = 'Timeout'; Set-WdaPackage $e 'Failed' 'Timed out.' } elseif ($code -eq 0) { Set-WdaPackage $e 'Succeeded' 'Installed.' $code } elseif ($code -in 3010, 1641) { Set-WdaPackage $e 'Succeeded' 'Installed; a restart is required to finish.' $code } else { $e.failureClass = 'Unknown'; Set-WdaPackage $e 'Failed' "Installer exit code $code." $code } $e.retryable = ($e.status -eq 'Failed') Add-WdaAttempt $Paths $e @{ trigger = 'automatic'; attempt = [int] $e.totalAttempts; startUtc = $started; endUtc = (Get-WdaNow).ToString('o'); result = $e.status; exitCode = [string] $e.exitCode class = [string] $e.failureClass; countsTowardLimit = $true; nextAction = $(if ($e.status -eq 'Failed') { 'manual retry (recovery tool)' } else { 'none' }); rebootRequired = [bool] ($code -in 3010, 1641); message = $e.message } } finally { Exit-WdbInstallLock $lock } Write-WdaLog " additional $($a.name): $($e.status) $($e.message)" } return $null }
<# Installs pending packages in queue order. Returns $null when the queue is done for this run, or an outcome string (Rebooting, WaitingForLock, WaitingForRestart, WaitingForNetwork, Finished:*) to stop.
Phase 5: a failed attempt is classified (ConvertFrom-WdaExitCode). Retryable classes wait with bounded exponential backoff before the next attempt (nextAttemptUtc, kept across restarts); the loop waits for the earliest due retry within the run. A network-class failure is checked first (Get-WdaNetworkDiagnosis): if connectivity or the package source is really gone, the attempt is not held against the package; it is deferred (bounded by maxNetworkDeferrals) and the run stops with WaitingForNetwork, or, when only one source is unreachable, packages from other sources continue. Every iteration acts on a package or waits for one, and the loop has a hard bound. #> function Invoke-WdaQueue { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [object[]] $Queue) $policy = Get-WdaRetryPolicy $Config $blockedSources = @{} $guardMax = 2 * ([int] $policy.maxAttempts + [int] $policy.maxNetworkDeferrals + 2) * [Math]::Max(1, @($Queue).Count) + 10 for ($guard = 0; $guard -lt $guardMax; $guard++) { $pending = @($Queue | Where-Object { $State.packages[$_.key].status -eq 'Pending' }) if ($pending.Count -eq 0) { return $null } if (((Get-WdaNow) - (ConvertTo-WdaDate $State.installStartUtc)).TotalHours -ge [double] $Config.maxRuntimeHours) { # Budget exhausted: what is done stays done; the rest is reported and can be retried later. foreach ($p in $pending) { $e = $State.packages[$p.key] $e.failureClass = 'Budget'; $e.retryable = $true; $e.nextAttemptUtc = $null Set-WdaPackage $e 'Failed' ("Not installed: the application runtime limit ($($Config.maxRuntimeHours) h) was reached. $(if ([int] $e.attempts) { "Last: $($e.message)" })".Trim()) } Write-WdaLog "Runtime limit ($($Config.maxRuntimeHours) h) reached; $($pending.Count) package(s) not installed." 'WARN' Save-WdaState $State $Paths return $null } $acted = $false $soonest = $null foreach ($p in $pending) { $e = $State.packages[$p.key] if ($e.status -ne 'Pending' -or $State.halted) { continue } # Dependencies first; a dependency that did not install makes this one Skipped. $blocked = $null; $waiting = $false foreach ($k in @($p.after)) { $d = $State.packages[$k] if (-not $d) { continue } if ($d.status -in 'Failed', 'Unavailable', 'RequiresInteraction', 'Skipped') { $blocked = $d.name } elseif ($d.status -notin 'Succeeded', 'AlreadyInstalled') { $waiting = $true } } if ($blocked) { $e.failureClass = 'Dependency'; $e.retryable = $true; Set-WdaPackage $e 'Skipped' "Not attempted: it needs $blocked, which was not installed."; $acted = $true; continue } if ($waiting) { continue } if ($p.interaction -eq 'required') { $e.failureClass = 'Manual' Set-WdaPackage $e 'RequiresInteraction' 'Marked as needing interaction; install it manually (winget install --id ... --interactive).' $acted = $true continue } if ($blockedSources.ContainsKey($p.source)) { continue } if ($e.nextAttemptUtc) { $due = ConvertTo-WdaDate $e.nextAttemptUtc if ($due -gt (Get-WdaNow)) { if (-not $soonest -or $due -lt $soonest) { $soonest = $due }; continue } } if (Test-WdbRestartPending $Config.dataRoot) { Save-WdaState $State $Paths Write-WdaLog 'A restart has been scheduled by another engine; stopping until after it.' 'WARN' return 'WaitingForRestart' } $lock = Enter-WdbInstallLock $Config.dataRoot 'Applications' ([int] $Config.lockWaitMinutes * 60) if (-not $lock) { Save-WdaState $State $Paths Write-WdaLog 'Another installation holds the install lock; trying again later.' 'WARN' Set-WdaStatus 'WaitingForLock' '' $State return 'WaitingForLock' } $restartNow = $null $offline = $null $acted = $true try { $log = Join-Path $Paths.PackageLogs (($p.key -replace '[^A-Za-z0-9._+-]', '_') + '.log') # Idempotency: an application that is already there is never installed again. $installed = Test-WdaInstalled $p $log if ($installed -eq $true) { if ($e.interrupted -or $e.attempts -gt 0) { Set-WdaPackage $e 'Succeeded' 'Installed (confirmed by winget list).' } else { Set-WdaPackage $e 'AlreadyInstalled' 'Already installed before this run; left unchanged.' } $e.detection = 'Installed'; $e.waitingFor = ''; $e.nextAttemptUtc = $null; $e.failureClass = ''; $e.retryable = $false Complete-WdaPortable $p $e Write-WdaLog " $($e.status.ToLowerInvariant()) $($p.name)" Save-WdaState $State $Paths continue } if ([int] $e.attempts -ge [int] $policy.maxAttempts) { $e.retryable = ([string] $e.failureClass) -notin $script:PermanentClasses Set-WdaPackage $e 'Failed' "Gave up after $($e.attempts) attempt(s). Last: $($e.message)" Save-WdaState $State $Paths continue } # Count the attempt before acting, so a crash or hang mid-install still counts. $e.attempts = [int] $e.attempts + 1 $e.totalAttempts = [int] $e.totalAttempts + 1 $e.interrupted = $false; $e.waitingFor = ''; $e.nextAttemptUtc = $null Set-WdaPackage $e 'Installing' "Attempt $($e.attempts)." Save-WdaState $State $Paths Set-WdaStatus 'Installing' $p.name $State $started = Get-WdaNow Write-WdaLog (" installing {0} ({1}:{2}) attempt {3}/{4}" -f $p.name, $p.source, $p.packageIdentifier, $e.attempts, $policy.maxAttempts) $r = Install-WdaPackage $p ([int] $Config.packageTimeoutMinutes) $log if ($r.TimedOut) { $m = @{ Status = 'Failed'; Retry = $true; Restart = 'none'; Message = "Timed out after $($Config.packageTimeoutMinutes) min."; Code = 'timeout'; Class = 'Timeout' } } else { $m = ConvertFrom-WdaExitCode $r.ExitCode } $status = $m.Status $counts = $true $next = '' if ($status -eq 'Failed' -and $m.Class -eq 'Network') { $diag = Get-WdaNetworkDiagnosis $p.source if ($diag.Level -ne 'Online') { $e.networkDeferrals = [int] $e.networkDeferrals + 1 if ([int] $e.networkDeferrals -le [int] $policy.maxNetworkDeferrals) { # Not the package's fault: the attempt is not held against it. $e.attempts = [int] $e.attempts - 1 $counts = $false $status = 'Pending' $e.waitingFor = $(if ($diag.Level -eq 'SourceUnavailable') { "source:$($p.source)" } else { 'network' }) $m.Message = "$($m.Message) Network check: $($diag.Level) ($($diag.Detail)); deferred until it is reachable ($($e.networkDeferrals)/$($policy.maxNetworkDeferrals))." if ($diag.Level -eq 'SourceUnavailable') { $blockedSources[$p.source] = $diag; $next = "wait for source $($p.source)" } else { $offline = $diag; $next = 'wait for network' } } else { $m.Message = "$($m.Message) Network check: $($diag.Level); already deferred $($policy.maxNetworkDeferrals) time(s)." } } } if ($status -eq 'Failed' -and $m.Retry -and [int] $e.attempts -lt [int] $policy.maxAttempts) { $delay = Get-WdaBackoffSeconds $policy ([int] $e.attempts) $e.nextAttemptUtc = (Get-WdaNow).AddSeconds($delay).ToString('o') $status = 'Pending' $next = "retry after $delay s" } if ($status -eq 'Succeeded') { # Do not rely on the exit code alone. $check = Test-WdaInstalled $p $log $e.detection = $(if ($check -eq $true) { 'Installed' } elseif ($check -eq $false) { 'Unconfirmed' } else { 'Unknown' }) if ($check -eq $false) { $m.Message = 'WinGet reported success, but winget list does not show the package; verify it manually.' } } if ($status -eq 'AlreadyInstalled') { $e.detection = 'Installed' } if ($status -eq 'RequiresRestart') { $e.restart = $(if ($m.Restart -eq 'later') { 'verify' } else { 'retry' }) $e.detection = $(if ($m.Restart -eq 'later') { 'InstalledRequiresRestart' } else { 'NotInstalled' }) if ($m.Restart -in 'now', 'initiated') { $restartNow = $m.Restart } } $e.failureClass = $(if ($status -in 'Succeeded', 'AlreadyInstalled', 'RequiresRestart') { '' } else { [string] $m.Class }) $e.retryable = ($status -in 'Failed', 'Pending') -and ([string] $m.Class) -notin $script:PermanentClasses Set-WdaPackage $e $status $m.Message $m.Code if ($status -in 'Succeeded', 'AlreadyInstalled') { Complete-WdaPortable $p $e } if (-not $next) { $next = switch ($status) { 'Succeeded' { 'none' } 'AlreadyInstalled' { 'none' } 'RequiresRestart' { 'restart' } 'RequiresInteraction' { 'manual action' } default { $(if ($e.retryable) { 'manual retry (recovery tool)' } else { 'none (permanent)' }) } } } Add-WdaAttempt $Paths $e @{ trigger = 'automatic'; attempt = [int] $e.totalAttempts; startUtc = $started.ToString('o'); endUtc = (Get-WdaNow).ToString('o') result = [string] $m.Status; exitCode = [string] $m.Code; class = [string] $m.Class; countsTowardLimit = $counts; nextAction = $next nextAttemptUtc = $e.nextAttemptUtc; rebootRequired = [bool] ($status -eq 'RequiresRestart'); message = $m.Message; packageIdentifier = $p.packageIdentifier; source = $p.source } $lvl = $(if ($status -in 'Succeeded', 'AlreadyInstalled') { 'INFO' } else { 'WARN' }) Write-WdaLog (" -> {0} {1} [{2}] {3} (class {4}; attempt {5}/{6}; next: {7})" -f $status, $p.name, $m.Code, $m.Message, $m.Class, $e.attempts, $policy.maxAttempts, $next) $lvl Save-WdaState $State $Paths } finally { Exit-WdbInstallLock $lock } if ($offline) { Write-WdaLog "Connectivity lost ($($offline.Level): $($offline.Detail)); progress is kept and the run continues when the network is back." 'WARN' Set-WdaStatus 'WaitingForNetwork' "Connectivity lost: $($offline.Level)" $State return 'WaitingForNetwork' } if ($e.status -eq 'Failed' -and -not $policy.continueAfterFailure) { $State.halted = $p.name Write-WdaLog "Stopping the queue after $($p.name) failed ('continue after a failure' is off)." 'WARN' Save-WdaState $State $Paths } if ($restartNow -eq 'initiated') { $State.reboots = [int] $State.reboots + 1 $e.restartBoot = Get-WdbBootTime Save-WdaState $State $Paths Write-WdaLog "$($p.name) started a restart itself; resuming after sign-in." 'WARN' return 'Rebooting' } if ($restartNow -eq 'now') { if (Test-WdaCanRestart $Config $State) { return Request-WdaReboot $Config $Paths $State "$($p.name) needs a restart before it can install" } Set-WdaPackage $e 'RequiresRestart' "$($e.message) Not installed: restarts are not allowed (policy or limit)." $e.restart = '' } } if ($acted) { continue } if ($soonest) { $wait = [int] [Math]::Min([double] $policy.maxDelaySeconds, [Math]::Max(1, [Math]::Ceiling(($soonest - (Get-WdaNow)).TotalSeconds))) Write-WdaLog "Next retry in $wait s." Set-WdaStatus 'WaitingForRetry' "Next retry at $($soonest.ToString('o'))" $State Wait-Wda $wait continue } break } $left = @($Queue | Where-Object { $State.packages[$_.key].status -eq 'Pending' }) if ($left.Count -and ($blockedSources.Count -or @($left | Where-Object { $State.packages[$_.key].waitingFor }).Count)) { $names = ($blockedSources.Keys | Sort-Object) -join ', ' Write-WdaLog "Package source(s) unreachable ($names); $($left.Count) package(s) wait for the next run." 'WARN' Set-WdaStatus 'WaitingForNetwork' "Package source unreachable: $names" $State Save-WdaState $State $Paths return 'WaitingForNetwork' } foreach ($p in $left) { $e = $State.packages[$p.key] if ($State.halted) { Set-WdaPackage $e 'Pending' "Not attempted: application setup stopped after $($State.halted) failed ('continue after a failure' is off). Retry it with the recovery tool." } else { $e.retryable = $true; Set-WdaPackage $e 'Failed' "Gave up after $($e.attempts) attempt(s). Last: $($e.message)" } } return $null }
# ------------------------------------------------------------------------------------------------ # Technician recovery (Retry mode) # ------------------------------------------------------------------------------------------------
<# Reopens operations for another run, under the engine's own mutex so it never races a running engine. Only operations of this deployment's configuration are eligible (the permitted set): queued WinGet/Store/portable packages and reviewed Additional Software. Never eligible: deselected apps, manual catalog entries, unresolved or invalid identifiers, anything already installed. Permanent failures (integrity, policy, cancelled, not found ...) need -IncludePermanent, i.e. a technician who has corrected the cause; their checks still apply on the next attempt because the engine installs exactly as before. Dependencies that did not install are reopened together with what needs them. Each reopened operation gets a fresh attempt budget; its history, total attempts and the previous result are kept. #> function Invoke-WdaRetry { param([hashtable] $Config, [string[]] $Operations = @(), [switch] $AllFailed, [switch] $PendingOnly, [switch] $IncludePermanent, [string] $RequestedBy = '') $paths = Get-WdaPaths $Config foreach ($d in $paths.Root, $paths.Logs, $paths.PackageLogs) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } } $script:LogFile = $paths.Log $script:StatusFile = $paths.Status $mutex = Enter-WdaMutex $Config.mutexName if (-not $mutex) { return @{ Outcome = 'Busy'; Accepted = @(); Refused = @(); Message = 'The application engine is running; try again when it has stopped.' } } try { if (-not (Test-Path -LiteralPath $paths.State) -and -not (Test-Path -LiteralPath "$($paths.State).bak")) { return @{ Outcome = 'NoState'; Accepted = @(); Refused = @(); Message = 'The application stage has not run on this computer yet.' } } $State = Read-WdaState $paths $queue = Get-WdaQueue $Config Initialize-WdaEntries $Config $State $queue $byKey = @{} foreach ($p in $queue) { $byKey[$p.key] = $p } $automatic = @{} foreach ($a in @($Config.additionalSoftware)) { if ($a.execution -eq 'automatic') { $automatic[[string] $a.id] = $true } }
# Eligibility of one operation id: $null (eligible) or a refusal reason. $why = { param([string] $Id) if ($Id -cmatch '^app:(winget|msstore):[a-z0-9][a-z0-9._+-]{0,127}$') { $k = $Id.Substring(4) $e = $State.packages[$k] if (-not $e) { return 'not part of this deployment' } if (-not $byKey.ContainsKey($k)) { if ($e.status -eq 'SkippedByUser') { return 'explicitly deselected for this deployment' } return "not installable by the engine ($($e.status): $($e.message))" } $bad = Test-WdaPackageSpec $byKey[$k] if ($bad) { return "invalid package definition: $bad" } if ($byKey[$k].interaction -eq 'required') { return 'needs interaction; install it manually' } $life = Get-WdaLifecycle $e if ($life -in 'Succeeded', 'AlreadySatisfied') { return 'already installed' } if ($life -eq 'Running') { return 'an installation is in progress' } if ($life -eq 'WaitingForReboot') { return 'waiting for a restart; restart the computer first' } if ($life -eq 'FailedPermanent' -and -not $IncludePermanent) { return "permanent failure ($($e.failureClass)): correct the cause, then retry with -IncludePermanent" } return $null } if ($Id -cmatch '^additional:[A-Za-z0-9][A-Za-z0-9._-]{0,63}$') { $k = $Id.Substring(11) $e = $State.additional[$k] if (-not $e) { return 'not part of this deployment' } if (-not $automatic.ContainsKey($k)) { return 'manual follow-up; install it by hand' } if ($e.status -eq 'Succeeded') { return 'already installed' } if ($e.status -eq 'Failed' -and ([string] $e.failureClass) -in $script:PermanentClasses -and -not $IncludePermanent) { return 'permanent failure (hash or signature): supply the correct installer, then retry with -IncludePermanent' } return $null } return 'not a valid operation id' }
$targets = New-Object System.Collections.Generic.List[string] if ($AllFailed -or $PendingOnly) { foreach ($e in @($State.packages.Values)) { $life = Get-WdaLifecycle $e $want = $(if ($PendingOnly) { $e.status -eq 'Pending' } else { ($life -in @('FailedRetryable', 'BlockedByDependency', 'WaitingForNetwork', 'Pending')) -or ($IncludePermanent -and $life -eq 'FailedPermanent') }) if ($want -and $byKey.ContainsKey($e.key)) { $targets.Add($e.operationId) } } if (-not $PendingOnly) { foreach ($e in @($State.additional.Values)) { if ($e.status -in 'Failed', 'Pending' -and $automatic.ContainsKey([string] $e.id)) { $targets.Add($e.operationId) } } } } foreach ($o in @($Operations | Where-Object { $_ })) { $id = ([string] $o).Trim() if ($id -notmatch '^(app|additional):') { $id = "app:$id" } if ($id.StartsWith('app:')) { $id = $id.ToLowerInvariant() } if (-not $targets.Contains($id)) { $targets.Add($id) } } $accepted = New-Object System.Collections.Generic.List[string] $refused = @() # Unmet dependencies are reopened with the operations that need them (dependency first). for ($i = 0; $i -lt $targets.Count; $i++) { $id = $targets[$i] $reason = & $why $id if ($reason) { $refused += @{ operationId = $id; reason = $reason }; continue } if ($id.StartsWith('app:')) { foreach ($dep in @($byKey[$id.Substring(4)].after)) { $d = $State.packages[$dep] if (-not $d -or $d.status -in 'Succeeded', 'AlreadyInstalled') { continue } $dr = & $why "app:$dep" if ($dr) { $reason = "its dependency $($d.name) cannot be retried ($dr)"; break } if (-not $targets.Contains("app:$dep")) { $targets.Add("app:$dep") } } if ($reason) { $refused += @{ operationId = $id; reason = $reason }; continue } } if (-not $accepted.Contains($id)) { $accepted.Add($id) } } if ($accepted.Count -eq 0) { return @{ Outcome = $(if ($targets.Count) { 'Refused' } else { 'NothingToRetry' }); Accepted = @(); Refused = $refused; Message = 'No operation was reopened.' } } $now = (Get-WdaNow).ToString('o') foreach ($id in $accepted) { $e = $(if ($id.StartsWith('app:')) { $State.packages[$id.Substring(4)] } else { $State.additional[$id.Substring(11)] }) $previous = "$($e.status): $($e.message)" Add-WdaAttempt $paths $e @{ trigger = 'manual'; attempt = [int] $e.totalAttempts; startUtc = $now; endUtc = $now; result = 'Reopened'; exitCode = [string] $e.exitCode class = [string] $e.failureClass; countsTowardLimit = $false; nextAction = 'retry'; nextAttemptUtc = $null; rebootRequired = $false message = "Retry requested$(if ($RequestedBy) { " by $RequestedBy" }). Previous: $previous" } $e.manualRetries = [int] $e.manualRetries + 1 $e.attempts = 0; $e.networkDeferrals = 0; $e.nextAttemptUtc = $null; $e.waitingFor = ''; $e.interrupted = $false; $e.failureClass = ''; $e.retryable = $false Set-WdaPackage $e 'Pending' "Retry requested$(if ($RequestedBy) { " by $RequestedBy" }) (previous: $previous)" } # The stage runs again with a fresh time budget; its previous result is kept in history\. if (Test-Path -LiteralPath $paths.Result) { $hist = Join-Path $paths.Root 'history' if (-not (Test-Path -LiteralPath $hist)) { New-Item -ItemType Directory -Path $hist -Force | Out-Null } Move-Item -LiteralPath $paths.Result -Destination (Join-Path $hist ("result-{0}.json" -f (Get-WdaNow).ToString('yyyyMMddHHmmss'))) -Force } if (Test-Path -LiteralPath $paths.Marker) { Remove-Item -LiteralPath $paths.Marker -Force } if (-not $State.originalStartUtc) { $State.originalStartUtc = $State.firstStartUtc } $State.final = $null $State.halted = '' $State.errors = 0 $State.firstStartUtc = $now $State.installStartUtc = $null $State.recoveries = @(@($State.recoveries) + @(@{ atUtc = $now; by = $RequestedBy; mode = $(if ($PendingOnly) { 'resume' } elseif ($AllFailed) { 'retryFailed' } else { 'retry' }); accepted = @($accepted); refused = @($refused | ForEach-Object { $_.operationId }); includePermanent = [bool] $IncludePermanent })) Save-WdaState $State $paths Write-WdaLog ("Recovery: reopened {0} operation(s){1}: {2}. Refused: {3}." -f $accepted.Count, $(if ($RequestedBy) { " for $RequestedBy" }), ($accepted -join ', '), $(if ($refused.Count) { ($refused | ForEach-Object { "$($_.operationId) ($($_.reason))" }) -join '; ' } else { 'none' })) 'WARN' Set-WdaStatus 'Pending' "Recovery reopened $($accepted.Count) operation(s)" $State return @{ Outcome = 'Accepted'; Accepted = @($accepted); Refused = $refused; Message = "Reopened $($accepted.Count) operation(s)." } } finally { Exit-WdaMutex $mutex } }
# ------------------------------------------------------------------------------------------------ # Main # ------------------------------------------------------------------------------------------------
function Invoke-WdaRun { param([hashtable] $Config, [hashtable] $Paths) $State = Read-WdaState $Paths if ($State.final) { Write-WdaLog "Already finished with status $($State.final); nothing to do." Unregister-WdaTask $Config return 'AlreadyFinished' } $ctx = Get-WdaContext $queue = Get-WdaQueue $Config $first = -not $State.firstStartUtc if ($first) { $State.firstStartUtc = (Get-WdaNow).ToString('o') } $State.starts = [int] $State.starts + 1 Initialize-WdaEntries $Config $State $queue Resume-WdaEntries $State $Paths Save-WdaState $State $Paths Write-WdaLog "==== Application engine $($script:EngineVersion) start $($State.starts) as $($ctx.User) (restarts so far: $($State.reboots)) ====" Set-WdaStatus 'Starting' "Start $($State.starts)" $State if ($first) { Write-WdaEvent 2000 'Application setup started.' Write-WdaLog ("Queue: {0} package(s), {1} unresolved, {2} additional item(s). Policy: {3}, restarts {4} (max {5}), {6} attempt(s) per package." -f @($queue).Count, @($Config.unresolved).Count, @($Config.additionalSoftware).Count, $Config.coordination.policy, $Config.restartPolicy, $Config.maxReboots, $Config.maxAttemptsPerPackage) } if ($ctx.IsSystem) { return Complete-Wda $Config $Paths $State 'Failed' 'The application stage must run as the signed-in user: WinGet is not supported in the SYSTEM account.' $queue } if (-not $ctx.IsElevated) { Write-WdaLog 'Not elevated: machine-wide installers may fail. The scheduled task should run with highest privileges.' 'WARN' }
# 1. Preparation (allowed while Windows Update is still working). Set-WdaStatus 'WaitingForNetwork' '' $State $deadline = (Get-WdaNow).AddMinutes([double] $Config.networkWaitMinutes) $online = $false while ($true) { if (Test-WdaNetwork) { $online = $true; break } if ((Get-WdaNow) -ge $deadline) { break } Wait-Wda 15 } if (-not $online) { $State.offlineStarts = [int] $State.offlineStarts + 1 Save-WdaState $State $Paths $limit = [double] $Config.waitForUpdatesHours + [double] $Config.maxRuntimeHours if (((Get-WdaNow) - (ConvertTo-WdaDate $State.firstStartUtc)).TotalHours -ge $limit) { if ($State.everOnline) { return Complete-Wda $Config $Paths $State 'Failed' "Runtime limit reached while offline." $queue } return Complete-Wda $Config $Paths $State 'Offline' "No network connection within $limit h; nothing was installed." $queue } Write-WdaLog "No network after $($Config.networkWaitMinutes) min; trying again at the next sign-in or within the hour." 'WARN' Set-WdaStatus 'WaitingForNetwork' 'No network; will retry' $State return 'WaitingForNetwork' } if (-not $State.everOnline) { $State.everOnline = $true; Save-WdaState $State $Paths }
$boot = $null if (-not $State.prepared) { Set-WdaStatus 'Preparing' 'Checking WinGet and package availability' $State $boot = Invoke-WdaBootstrapStep $Config $Paths $State -CheckOnly if ($boot.Status -eq 'Unsupported') { return Complete-Wda $Config $Paths $State 'Failed' $boot.Message $queue } if ($boot.Status -eq 'Healthy') { Invoke-WdaAvailability $Config $Paths $State $queue } Save-WdaState $State $Paths }
# 2. Gate: Windows Update first. $polls = [int] $Config.gatePollMinutes for ($i = 0; ; $i++) { $gate = Get-WdaUpdatesGate $Config $State if ($gate.Open) { Write-WdaLog $gate.Reason $(if ($gate.ContainsKey('Warn')) { 'WARN' } else { 'INFO' }) break } if ($i -eq 0) { Write-WdaLog $gate.Reason } if ($i -ge $polls) { Set-WdaStatus 'WaitingForUpdates' $gate.Reason $State; return 'WaitingForUpdates' } Set-WdaStatus 'WaitingForUpdates' $gate.Reason $State Wait-Wda 60 }
# 3. WinGet (repair under the install lock when needed), then the queue. if (-not $State.installStartUtc) { $State.installStartUtc = (Get-WdaNow).ToString('o'); Save-WdaState $State $Paths } if (-not $boot -or $boot.Status -ne 'Healthy') { $lock = Enter-WdbInstallLock $Config.dataRoot 'Applications' ([int] $Config.lockWaitMinutes * 60) if (-not $lock) { Set-WdaStatus 'WaitingForLock' '' $State; return 'WaitingForLock' } try { $boot = Invoke-WdaBootstrapStep $Config $Paths $State } finally { Exit-WdbInstallLock $lock } Save-WdaState $State $Paths if ($boot.Status -notin 'Healthy', 'Repaired') { foreach ($e in @($State.packages.Values)) { if ($e.status -eq 'Pending') { Set-WdaPackage $e 'Pending' 'Not attempted: WinGet is unavailable.' } } return Complete-Wda $Config $Paths $State 'Failed' $boot.Message $queue } if (-not $State.prepared) { Invoke-WdaAvailability $Config $Paths $State $queue; Save-WdaState $State $Paths } }
if (Test-WdbRestartPending $Config.dataRoot) { Write-WdaLog 'A restart is scheduled; waiting for it.' 'WARN'; return 'WaitingForRestart' } if (Test-WdaRebootPending) { if (-not $State.restartForPending -and (Test-WdaCanRestart $Config $State)) { $State.restartForPending = $true Save-WdaState $State $Paths return Request-WdaReboot $Config $Paths $State 'a restart is pending before applications can be installed' } Write-WdaLog 'Windows still reports a pending restart; installing anyway (already restarted once, or restarts are not allowed).' 'WARN' }
Set-WdaStatus 'Installing' '' $State $out = Invoke-WdaQueue $Config $Paths $State $queue if ($out) { return $out } Save-WdaState $State $Paths
# 4. Additional Software. $out = Invoke-WdaAdditional $Config $Paths $State if ($out) { Save-WdaState $State $Paths; return $out } Save-WdaState $State $Paths
# 5. Restart for packages that need one to finish, then verify on the next start. $needRestart = @($State.packages.Values | Where-Object { $_.status -eq 'RequiresRestart' -and $_.restart }) if ($needRestart.Count -gt 0) { if (Test-WdaCanRestart $Config $State) { return Request-WdaReboot $Config $Paths $State "$($needRestart.Count) package(s) need a restart to finish" } foreach ($e in $needRestart) { $e.restart = ''; Set-WdaPackage $e 'RequiresRestart' "$($e.message) Restart the computer to finish (restarts not allowed by policy or limit)." } }
$final = Get-WdaFinalStatus $State $reason = switch ($final) { 'Succeeded' { 'Every selected application is installed.' } 'CompletedWithFollowUp' { 'Some applications need manual follow-up (interaction, a restart or a manual check).' } default { 'Some applications could not be installed.' } } if (@($State.packages.Values | Where-Object { $_['failureClass'] -eq 'Budget' }).Count) { $reason += " The runtime limit ($($Config.maxRuntimeHours) h) was reached." } if ($State.halted) { $reason += " Stopped after $($State.halted) failed (continue after a failure is off)." } if ($final -ne 'Succeeded') { $reason += ' Failed and unfinished applications can be retried with the deployment recovery tool.' } return Complete-Wda $Config $Paths $State $final $reason $queue }
function Invoke-WdaMain { param([hashtable] $Config) $paths = Get-WdaPaths $Config foreach ($d in $paths.Root, $paths.Logs, $paths.PackageLogs) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } } $script:LogFile = $paths.Log $script:StatusFile = $paths.Status Limit-WdaLogSize $paths.Log
$mutex = Enter-WdaMutex $Config.mutexName if (-not $mutex) { Write-WdaLog 'Another application engine instance is running; exiting.' return 'AlreadyRunning' } try { return Invoke-WdaRun -Config $Config -Paths $paths } catch { $err = $_ Write-WdaLog "Unhandled error: $($err.Exception.Message) $(Format-WdaHResult $err.Exception.HResult)`r`n$($err.ScriptStackTrace)" 'ERROR' $state = Read-WdaState $paths $state.errors = [int] $state.errors + 1 Save-WdaState $state $paths if ($state.errors -ge [int] $Config.maxErrors -and -not $state.final) { return Complete-Wda $Config $paths $state 'Failed' "Stopped after $($state.errors) unexpected errors. Last: $($err.Exception.Message)" } Set-WdaStatus 'Error' "$($err.Exception.Message) (will retry)" $state return 'Error' } finally { Exit-WdaMutex $mutex } }
<# Read-only dry run. #> function Invoke-WdaPlan { param([hashtable] $Config) $paths = Get-WdaPaths $Config $queue = Get-WdaQueue $Config $b = Invoke-WgbBootstrap -CheckOnly -MinimumVersion ([string] $Config.minimumWinGetVersion) if ($b.Status -eq 'Healthy') { $script:WinGet = $b.Path } $rows = @() $n = 0 foreach ($p in $queue) { $n++ $bad = Test-WdaPackageSpec $p $installed = ''; $available = '' if (-not $bad -and $script:WinGet) { $i = Test-WdaInstalled $p $installed = $(if ($i -eq $true) { 'yes' } elseif ($i -eq $false) { 'no' } else { '?' }) $available = Test-WdaAvailable $p } $action = if ($bad) { "Unavailable: $bad" } elseif ($p.interaction -eq 'required') { 'RequiresInteraction (not attempted)' } elseif ($installed -eq 'yes') { 'AlreadyInstalled (skip)' } elseif ($available -eq 'NotFound') { 'Unavailable' } elseif ($p.method -eq 'portable') { "Install (portable) + shortcut $($p.portable.shortcut)" } else { 'Install' } $rows += [pscustomobject]@{ '#' = $n; Name = $p.name; Source = $p.source; Id = $p.packageIdentifier; Installed = $installed; Available = $available; Action = $action Command = $(if ($bad) { '' } else { 'winget ' + ((Get-WdaArguments 'install' $p) -join ' ') }) } } foreach ($u in @($Config.unresolved)) { $rows += [pscustomobject]@{ '#' = ''; Name = $u.displayName; Source = $u.source; Id = $u.packageIdentifier; Installed = ''; Available = ''; Action = "Unavailable: $($u.reason)"; Command = '' } } foreach ($m in @($Config.manual)) { $rows += [pscustomobject]@{ '#' = ''; Name = $m.displayName; Source = 'manual'; Id = $m.key; Installed = ''; Available = ''; Action = "Manual action required: $($m.instructions)"; Command = '' } } foreach ($d in @($Config.deselected)) { $rows += [pscustomobject]@{ '#' = ''; Name = $d.displayName; Source = $d.source; Id = $d.packageIdentifier; Installed = ''; Available = ''; Action = 'SkippedByUser (deselected)'; Command = '' } } foreach ($a in @($Config.additionalSoftware)) { $rows += [pscustomobject]@{ '#' = ''; Name = $a.name; Source = 'additional'; Id = $a.fileName; Installed = ''; Available = ''; Action = $(if ($a.execution -eq 'automatic') { 'Reviewed installer (hash + signature checked)' } else { 'Manual follow-up' }); Command = '' } } [pscustomobject]@{ WinGet = $b; Rows = $rows; Paths = $paths } }
# Dot-sourcing (tests) only defines the functions. if ($MyInvocation.InvocationName -ne '.') { $engineMode = $Mode $cfg = Get-WdaConfig $ConfigPath . (Join-Path $PSScriptRoot 'WinGetBootstrap.ps1') if ($engineMode -eq 'Retry') { $who = [Security.Principal.WindowsIdentity]::GetCurrent().Name $r = Invoke-WdaRetry $cfg -Operations $Operation -AllFailed:$AllFailed -PendingOnly:$PendingOnly -IncludePermanent:$IncludePermanent -RequestedBy $who [pscustomobject]$r | ConvertTo-Json -Depth 5 if ($r.Outcome -eq 'Accepted') { exit 0 } exit 1 } if ($engineMode -eq 'Plan') { $plan = Invoke-WdaPlan $cfg "WinGet: $($plan.WinGet.Status) $($plan.WinGet.Version) $($plan.WinGet.Message)" $plan.Rows | Format-Table -AutoSize -Wrap | Out-String -Width 220 exit 0 } $outcome = Invoke-WdaMain $cfg Write-Output $outcome if ($outcome -eq 'Error' -or $outcome -eq 'Finished:Failed') { exit 1 } exit 0 }

#Requires -Version 5.1
<#
.SYNOPSIS
    Windows Deployment Builder - WinGet availability check and documented repair.

.DESCRIPTION
    Decides whether WinGet (the Windows Package Manager client in Microsoft App Installer) works for
    the current user, and repairs it only when it does not. A healthy WinGet is never reinstalled.

    Check order (Mode Repair):
      1. Context. WinGet is a per-user packaged app; it is not supported in the SYSTEM account, so
         SYSTEM is refused with a clear message. Windows 10 1809 (build 17763) or later is required.
      2. Probe. Resolve winget.exe the documented way (the App Execution Alias on the user's PATH),
         run "winget --version" and "winget source list", and require the default "winget" source.
      3. Registration (documented by Microsoft for "WinGet not available yet after first sign-in"):
           Add-AppxPackage -RegisterByFamilyName -MainPackage Microsoft.DesktopAppInstaller_8wekyb3d8bbwe
      4. Offline packages, only if supplied: <OfflinePath>\*DesktopAppInstaller*.msixbundle plus its
         dependency packages (*.appx / *.msix). Every file must carry a valid Authenticode signature
         from Microsoft Corporation, or nothing is installed.
      5. Online repair, only if allowed: the Microsoft.WinGet.Client module from the PowerShell
         Gallery and Repair-WinGetPackageManager (Microsoft's documented procedure).
    After every step WinGet is probed again; the first healthy probe ends the procedure.

    Statuses: Healthy (nothing done), Repaired, NeedsRepair (Mode Check only), Unsupported, Failed.

    Mode Check is read-only and changes nothing. The application engine dot-sources this file and
    calls Invoke-WgbBootstrap.

.EXAMPLE
    powershell.exe -ExecutionPolicy Bypass -File .\WinGetBootstrap.ps1 -Mode Check
#>
[CmdletBinding()]
param(
    [ValidateSet('Check', 'Repair')]
    [string] $Mode = 'Check',
    [switch] $NoRegister,
    [switch] $AllowOnlineRepair,
    [string] $OfflinePath = '',
    [string] $MinimumVersion = '1.6.0'
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

$script:WgbAppInstallerFamily = 'Microsoft.DesktopAppInstaller_8wekyb3d8bbwe'

# ------------------------------------------------------------------------------------------------
# Adapters: everything that touches the system. Tests replace these functions.
# ------------------------------------------------------------------------------------------------

function Get-WgbContext {
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($id)
    @{
        User       = $id.Name
        IsSystem   = ($id.User.Value -eq 'S-1-5-18')
        IsElevated = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
        Build      = [Environment]::OSVersion.Version.Build
    }
}

function Find-WgbWinGet {
    $c = Get-Command -Name 'winget.exe' -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($c) { return $c.Source }
    return $null
}

function Invoke-WgbWinGetCommand {
    param([string] $Path, [string[]] $Arguments)
    $out = & $Path @Arguments 2>&1 | Out-String
    @{ ExitCode = $LASTEXITCODE; Output = $out }
}

function Get-WgbAppInstaller {
    $p = Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction SilentlyContinue | Sort-Object Version -Descending | Select-Object -First 1
    if ($p) { return @{ Installed = $true; Version = [string] $p.Version } }
    @{ Installed = $false; Version = '' }
}

function Register-WgbAppInstaller {
    Add-AppxPackage -RegisterByFamilyName -MainPackage $script:WgbAppInstallerFamily -ErrorAction Stop
}

function Find-WgbOfflinePackages {
    param([string] $Directory)
    if (-not $Directory -or -not (Test-Path -LiteralPath $Directory)) { return $null }
    $bundle = Get-ChildItem -LiteralPath $Directory -Filter '*DesktopAppInstaller*.msixbundle' -File -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $bundle) { return $null }
    $deps = @(Get-ChildItem -LiteralPath $Directory -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.appx', '.msix' } | ForEach-Object { $_.FullName })
    @{ Bundle = $bundle.FullName; Dependencies = $deps }
}

function Test-WgbSignature {
    param([string] $Path)
    $s = Get-AuthenticodeSignature -LiteralPath $Path
    ($s.Status -eq 'Valid') -and ($null -ne $s.SignerCertificate) -and ($s.SignerCertificate.Subject -match 'O=Microsoft Corporation')
}

function Install-WgbOfflinePackage {
    param([string] $Bundle, [string[]] $Dependencies)
    if (@($Dependencies).Count -gt 0) { Add-AppxPackage -Path $Bundle -DependencyPath $Dependencies -ErrorAction Stop }
    else { Add-AppxPackage -Path $Bundle -ErrorAction Stop }
}

function Invoke-WgbOnlineRepair {
    param([bool] $AllUsers)
    $scope = if ($AllUsers) { 'AllUsers' } else { 'CurrentUser' }
    Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force -Scope $scope -ErrorAction Stop | Out-Null
    Install-Module -Name Microsoft.WinGet.Client -Repository PSGallery -Force -Scope $scope -ErrorAction Stop
    Import-Module Microsoft.WinGet.Client -ErrorAction Stop
    if ($AllUsers) { Repair-WinGetPackageManager -AllUsers -ErrorAction Stop } else { Repair-WinGetPackageManager -ErrorAction Stop }
}

function Wait-Wgb { param([int] $Seconds) if ($Seconds -gt 0) { Start-Sleep -Seconds $Seconds } }

# ------------------------------------------------------------------------------------------------
# Procedure
# ------------------------------------------------------------------------------------------------

function Test-WgbWinGet {
    param([string] $MinimumVersion = '1.6.0')
    $path = Find-WgbWinGet
    if (-not $path) { return @{ Healthy = $false; Path = $null; Version = ''; Error = 'winget.exe is not on PATH for this user (App Installer not registered yet?).' } }
    try {
        $v = Invoke-WgbWinGetCommand $path @('--version')
        if ($v.ExitCode -ne 0 -or $v.Output -notmatch 'v?(\d+\.\d+\.\d+)') {
            return @{ Healthy = $false; Path = $path; Version = ''; Error = "winget --version failed (exit $($v.ExitCode))." }
        }
        $version = $Matches[1]
        if ([Version] $version -lt [Version] $MinimumVersion) {
            return @{ Healthy = $false; Path = $path; Version = $version; Error = "WinGet $version is older than the required $MinimumVersion." }
        }
        $s = Invoke-WgbWinGetCommand $path @('source', 'list', '--disable-interactivity')
        if ($s.ExitCode -ne 0) { return @{ Healthy = $false; Path = $path; Version = $version; Error = "winget source list failed (exit $($s.ExitCode))." } }
        if ($s.Output -notmatch '(?m)^\s*winget\s') { return @{ Healthy = $false; Path = $path; Version = $version; Error = 'The default "winget" source is missing.' } }
        return @{ Healthy = $true; Path = $path; Version = $version; Error = '' }
    } catch {
        return @{ Healthy = $false; Path = $path; Version = ''; Error = "WinGet could not be started: $($_.Exception.Message)" }
    }
}

<#
    Returns a hashtable: Status, Method, Path, Version, AppInstaller, Message, Steps (list of strings).
#>
function Invoke-WgbBootstrap {
    param(
        [switch] $CheckOnly,
        [bool] $AllowRegister = $true,
        [bool] $AllowOnlineRepair = $false,
        [string] $OfflinePath = '',
        [string] $MinimumVersion = '1.6.0',
        [int] $RegistrationWaitSeconds = 60
    )
    $steps = New-Object System.Collections.ArrayList
    $r = @{ Status = 'Failed'; Method = 'none'; Path = $null; Version = ''; AppInstaller = ''; Message = ''; Steps = $steps }
    $done = {
        param($Probe, $Method)
        $r.Status = $(if ($Method -eq 'existing') { 'Healthy' } else { 'Repaired' })
        $r.Method = $Method; $r.Path = $Probe.Path; $r.Version = $Probe.Version
        $r.Message = $(if ($Method -eq 'existing') { "WinGet $($Probe.Version) works; nothing to repair." } else { "WinGet $($Probe.Version) works after $Method." })
        [void] $steps.Add($r.Message)
        $r
    }

    $ctx = Get-WgbContext
    if ($ctx.IsSystem) {
        $r.Status = 'Unsupported'
        $r.Message = 'WinGet is not supported in the SYSTEM account. Run the application stage as the signed-in user.'
        [void] $steps.Add($r.Message)
        return $r
    }
    if ([int] $ctx.Build -lt 17763) {
        $r.Status = 'Unsupported'
        $r.Message = "WinGet needs Windows 10 1809 (build 17763) or later; this is build $($ctx.Build)."
        [void] $steps.Add($r.Message)
        return $r
    }

    $probe = Test-WgbWinGet $MinimumVersion
    if ($probe.Healthy) { return (& $done $probe 'existing') }
    [void] $steps.Add("Probe: $($probe.Error)")
    $ai = Get-WgbAppInstaller
    $r.AppInstaller = $(if ($ai.Installed) { "registered ($($ai.Version))" } else { 'not registered for this user' })
    [void] $steps.Add("App Installer: $($r.AppInstaller).")
    if ($CheckOnly) {
        $r.Status = 'NeedsRepair'
        $r.Message = $probe.Error
        return $r
    }

    $last = $probe.Error
    if ($AllowRegister) {
        try {
            Register-WgbAppInstaller
            [void] $steps.Add("Registered $($script:WgbAppInstallerFamily).")
            for ($i = 0; $i -le [Math]::Ceiling($RegistrationWaitSeconds / 10); $i++) {
                $probe = Test-WgbWinGet $MinimumVersion
                if ($probe.Healthy) { return (& $done $probe 'registration') }
                Wait-Wgb 10
            }
            $last = $probe.Error
            [void] $steps.Add("After registration: $last")
        } catch {
            $last = "Registration failed: $($_.Exception.Message)"
            [void] $steps.Add($last)
        }
    }

    $offline = Find-WgbOfflinePackages $OfflinePath
    if ($offline) {
        $files = @($offline.Bundle) + @($offline.Dependencies)
        $unsigned = @($files | Where-Object { -not (Test-WgbSignature $_) })
        if ($unsigned.Count -gt 0) {
            $last = "Offline packages not used: no valid Microsoft signature on $(($unsigned | ForEach-Object { Split-Path $_ -Leaf }) -join ', ')."
            [void] $steps.Add($last)
        } else {
            try {
                Install-WgbOfflinePackage $offline.Bundle $offline.Dependencies
                [void] $steps.Add("Installed the offline App Installer package $(Split-Path $offline.Bundle -Leaf).")
                $probe = Test-WgbWinGet $MinimumVersion
                if ($probe.Healthy) { return (& $done $probe 'offline package') }
                $last = "After the offline package: $($probe.Error)"
                [void] $steps.Add($last)
            } catch {
                $last = "Offline package installation failed: $($_.Exception.Message)"
                [void] $steps.Add($last)
            }
        }
    } elseif ($OfflinePath) {
        [void] $steps.Add("No offline App Installer package in $OfflinePath.")
    }

    if ($AllowOnlineRepair) {
        try {
            Invoke-WgbOnlineRepair -AllUsers ([bool] $ctx.IsElevated)
            [void] $steps.Add('Ran Repair-WinGetPackageManager (Microsoft.WinGet.Client from the PowerShell Gallery).')
            $probe = Test-WgbWinGet $MinimumVersion
            if ($probe.Healthy) { return (& $done $probe 'online repair') }
            $last = "After online repair: $($probe.Error)"
            [void] $steps.Add($last)
        } catch {
            $last = "Online repair failed: $($_.Exception.Message)"
            [void] $steps.Add($last)
        }
    }

    $r.Status = 'Failed'
    $r.Message = "WinGet could not be initialized. Last problem: $last"
    [void] $steps.Add($r.Message)
    return $r
}

# Dot-sourcing (the application engine, tests) only defines the functions.
if ($MyInvocation.InvocationName -ne '.') {
    $result = Invoke-WgbBootstrap -CheckOnly:($Mode -eq 'Check') -AllowRegister (-not $NoRegister) -AllowOnlineRepair ([bool] $AllowOnlineRepair) -OfflinePath $OfflinePath -MinimumVersion $MinimumVersion
    $result.Steps | ForEach-Object { "  $_" }
    "Status: $($result.Status)$(if ($result.Version) { " (WinGet $($result.Version))" })"
    if ($result.Status -in 'Healthy', 'Repaired') { exit 0 }
    exit 1
}

{
  "$schema": "https://aka.ms/winget-packages.schema.2.0.json",
  "Sources": [
    {
      "Packages": [
        {
          "PackageIdentifier": "Google.Chrome"
        },
        {
          "PackageIdentifier": "VideoLAN.VLC"
        },
        {
          "PackageIdentifier": "7zip.7zip"
        },
        {
          "PackageIdentifier": "CodeSector.TeraCopy"
        },
        {
          "PackageIdentifier": "Bitwarden.Bitwarden"
        },
        {
          "PackageIdentifier": "Microsoft.VCRedist.2015+.x64"
        },
        {
          "PackageIdentifier": "Microsoft.VCRedist.2015+.x86"
        }
      ],
      "SourceDetails": {
        "Name": "winget",
        "Identifier": "Microsoft.Winget.Source_8wekyb3d8bbwe",
        "Argument": "https://cdn.winget.microsoft.com/cache",
        "Type": "Microsoft.PreIndexed.Package"
      }
    }
  ]
}

#Requires -Version 5.1
<#
.SYNOPSIS
    Windows Deployment Builder - shared functions of the deployment orchestrator.

.DESCRIPTION
    Dot-sourced by Stage-Deployment.ps1, Initialize-Deployment.ps1, DeploymentOrchestrator.ps1,
    Show-DeploymentStatus.ps1, Resume-Deployment.ps1 and Complete-Deployment.ps1. Defines functions
    only; it never acts by itself.

    Everything that touches the system (scheduled tasks, ACLs, processes, shortcuts, the event log,
    time, identity) is a small adapter function, so tests can replace it with a simulation.

    The orchestrator coordinates; it does not install. Windows Update and applications are
    installed by the existing engines (WindowsUpdateEngine.ps1 as SYSTEM, ApplicationEngine.ps1 as
    the signed-in user), each from its own scheduled task. The orchestrator launches each engine's
    installer once, follows their real result files and writes one deployment status and report.

    Phase 5 (orchestrator 1.1.0): state files are replaced atomically with a backup of the last good
    copy (Read-WddDeploymentState falls back to it and never mistakes a damaged state for "no
    deployment"), and every snapshot carries a machine-readable outcome with a stable exit code
    (Get-WddDeploymentOutcome) for DeploymentRecovery.ps1 and later health reporting.
#>

Set-StrictMode -Version 2.0

$script:DeployVersion = '1.1.0'
$script:DeployStateVersion = 2
$script:EventSource = 'WindowsDeploymentBuilder'
$script:ManifestFormat = 'windows-deployment-builder/deployment-manifest'
$script:MutexName = 'Global\WindowsDeploymentBuilder-Deployment'
$script:FinalStageStatuses = @('Succeeded', 'CompletedWithFollowUp', 'CompletedWithFailures', 'Failed', 'Offline')
$script:WddLogFile = $null

# ------------------------------------------------------------------------------------------------
# Adapters (replaced by the scenario tests)
# ------------------------------------------------------------------------------------------------

function Get-WddNow { [DateTime]::UtcNow }

function Get-WddIdentity {
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    $p = New-Object Security.Principal.WindowsPrincipal($id)
    @{ Name = $id.Name; IsSystem = ($id.User.Value -eq 'S-1-5-18'); IsAdmin = $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) }
}

# Windows PE (the installation environment) must never run the orchestrator.
function Test-WddWinPE { (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\MiniNT') -or ($env:SystemDrive -eq 'X:') }

function Get-WddTask {
    param([string] $TaskPath, [string] $TaskName)
    $null -ne (Get-ScheduledTask -TaskName $TaskName -TaskPath $TaskPath -ErrorAction SilentlyContinue)
}

function Unregister-WddTask {
    param([string] $TaskPath, [string] $TaskName)
    Get-ScheduledTask -TaskName $TaskName -TaskPath $TaskPath -ErrorAction SilentlyContinue | Unregister-ScheduledTask -Confirm:$false
}

function Start-WddTask {
    param([string] $TaskPath, [string] $TaskName)
    Start-ScheduledTask -TaskName $TaskName -TaskPath $TaskPath
}

function Get-WddBootTime { (Get-CimInstance -ClassName Win32_OperatingSystem).LastBootUpTime.ToUniversalTime() }

function Write-WddEvent {
    param([int] $EventId, [string] $Message, [ValidateSet('Information', 'Warning', 'Error')] [string] $EntryType = 'Information')
    try {
        if (-not [System.Diagnostics.EventLog]::SourceExists($script:EventSource)) { New-EventLog -LogName Application -Source $script:EventSource }
        Write-EventLog -LogName Application -Source $script:EventSource -EventId $EventId -EntryType $EntryType -Message $Message
    } catch {
        Write-WddLog "Could not write event $EventId to the Application log: $($_.Exception.Message)" 'WARN'
    }
}

function New-WddShortcut {
    param([string] $Name, [string] $Target, [string] $Arguments, [string] $Description)
    $path = Join-Path ([Environment]::GetFolderPath('CommonDesktopDirectory')) "$Name.lnk"
    $shell = New-Object -ComObject WScript.Shell
    $lnk = $shell.CreateShortcut($path)
    $lnk.TargetPath = $Target
    $lnk.Arguments = $Arguments
    $lnk.Description = $Description
    $lnk.Save()
}

function Remove-WddShortcut {
    param([string] $Name)
    $path = Join-Path ([Environment]::GetFolderPath('CommonDesktopDirectory')) "$Name.lnk"
    if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Force }
}

# ------------------------------------------------------------------------------------------------
# JSON, logging, paths
# ------------------------------------------------------------------------------------------------

function ConvertTo-WddHashtable {
    param($InputObject)
    if ($null -eq $InputObject) { return $null }
    if ($InputObject -is [System.Collections.IDictionary]) {
        $h = @{}
        foreach ($k in $InputObject.Keys) { $h[$k] = ConvertTo-WddHashtable $InputObject[$k] }
        return $h
    }
    if ($InputObject -is [System.Management.Automation.PSCustomObject]) {
        $h = @{}
        foreach ($p in $InputObject.PSObject.Properties) { $h[$p.Name] = ConvertTo-WddHashtable $p.Value }
        return $h
    }
    if ($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [string]) {
        return , @($InputObject | ForEach-Object { ConvertTo-WddHashtable $_ })
    }
    return $InputObject
}

<#
    Atomic write: <Path>.tmp is written through to disk, then replaces <Path> in one file-system
    operation; -Backup keeps the replaced file as <Path>.bak (the last good copy).
#>
function Write-WddJson {
    param([string] $Path, $Value, [switch] $Backup)
    $dir = Split-Path -Parent $Path
    if ($dir -and -not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $json = $Value | ConvertTo-Json -Depth 12
    $tmp = "$Path.tmp"
    $bytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes($json)
    $fs = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 4096, [System.IO.FileOptions]::WriteThrough)
    try { $fs.Write($bytes, 0, $bytes.Length); $fs.Flush($true) } finally { $fs.Dispose() }
    if (Test-Path -LiteralPath $Path) {
        try {
            [System.IO.File]::Replace($tmp, $Path, $(if ($Backup) { "$Path.bak" } else { $null }))
            return
        } catch {
            if ($Backup) { Copy-Item -LiteralPath $Path -Destination "$Path.bak" -Force }
        }
    }
    Move-Item -LiteralPath $tmp -Destination $Path -Force
}

function Read-WddJson {
    param([string] $Path)
    if (-not (Test-Path -LiteralPath $Path)) { return $null }
    # Engines write UTF-8 without a BOM; Get-Content would read that as ANSI in PowerShell 5.1.
    try { ConvertTo-WddHashtable ([System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8) | ConvertFrom-Json) } catch { $null }
}

function Write-WddLog {
    param([string] $Message, [ValidateSet('INFO', 'WARN', 'ERROR')] [string] $Level = 'INFO')
    $line = '{0}  {1,-5}  {2}' -f (Get-WddNow).ToString('yyyy-MM-dd HH:mm:ss'), $Level, $Message
    Write-Verbose $line
    if (-not $script:WddLogFile) { return }
    for ($i = 0; $i -lt 3; $i++) {
        try { [System.IO.File]::AppendAllText($script:WddLogFile, $line + "`r`n"); return } catch { Start-Sleep -Milliseconds 200 }
    }
}

function Get-WddPaths {
    param([string] $DataRoot)
    $deployment = Join-Path $DataRoot 'Deployment'
    $state = Join-Path $DataRoot 'state'
    $reports = Join-Path $DataRoot 'reports'
    @{
        Root          = $DataRoot
        Package       = Join-Path $DataRoot 'Package'
        Deployment    = $deployment
        Logs          = Join-Path $deployment 'logs'
        Log           = Join-Path (Join-Path $deployment 'logs') 'deployment.log'
        Status        = Join-Path $deployment 'status.json'
        StateDir      = $state
        State         = Join-Path $state 'deployment.json'
        Marker        = Join-Path $state 'deployment.done'
        RestartMarker = Join-Path $state 'restart-pending.json'
        Reports       = $reports
        ReportJson    = Join-Path $reports 'deployment-report.json'
        ReportText    = Join-Path $reports 'deployment-report.txt'
    }
}

function Initialize-WddLogging {
    param([hashtable] $Paths)
    foreach ($d in $Paths.Deployment, $Paths.Logs, $Paths.StateDir) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } }
    $script:WddLogFile = $Paths.Log
    if ((Test-Path -LiteralPath $Paths.Log) -and (Get-Item -LiteralPath $Paths.Log).Length -gt 5MB) { Move-Item -LiteralPath $Paths.Log -Destination "$($Paths.Log).1" -Force }
}

# ------------------------------------------------------------------------------------------------
# Manifest and integrity
# ------------------------------------------------------------------------------------------------

# Only plain relative paths: no drive, no root, no "..", a conservative character set.
function Test-WddRelativePath {
    param([string] $Path)
    if ([string]::IsNullOrWhiteSpace($Path) -or $Path.Length -gt 200) { return $false }
    if ($Path -notmatch '^[A-Za-z0-9._ -]+([\\/][A-Za-z0-9._ -]+)*$') { return $false }
    foreach ($seg in $Path -split '[\\/]') { if ($seg -eq '..' -or $seg -eq '.' -or $seg.Trim() -eq '') { return $false } }
    return $true
}

function Read-WddManifest {
    param([string] $Path)
    if (-not (Test-Path -LiteralPath $Path)) { throw "Deployment manifest not found: $Path" }
    try { $m = ConvertTo-WddHashtable ([System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8) | ConvertFrom-Json) } catch { throw "Deployment manifest is not valid JSON: $Path" }
    if ($m -isnot [hashtable] -or $m.format -ne $script:ManifestFormat) { throw "Not a Windows Deployment Builder deployment manifest: $Path" }
    if ([int] $m.manifestVersion -ne 1) { throw "Unsupported deployment manifest version $($m.manifestVersion) (this orchestrator reads version 1)." }
    if ([string] $m.packageId -notmatch '^[0-9A-F]{16}$') { throw 'Deployment manifest has no valid packageId.' }
    if ([string] $m.dataRoot -notmatch '^[A-Za-z]:\\[^"*?<>|]+$') { throw 'Deployment manifest has an invalid dataRoot.' }
    foreach ($f in @($m.files)) {
        if (-not (Test-WddRelativePath $f.path)) { throw "Deployment manifest lists an unsafe path: $($f.path)" }
        if ([string] $f.sha256 -notmatch '^[0-9A-F]{64}$') { throw "Deployment manifest has an invalid hash for $($f.path)." }
        if ($f.textSha256 -and [string] $f.textSha256 -notmatch '^[0-9A-F]{64}$') { throw "Deployment manifest has an invalid text hash for $($f.path)." }
        if ($f.embedded -and -not (Test-WddRelativePath $f.embedded)) { throw "Deployment manifest lists an unsafe embedded path: $($f.embedded)" }
    }
    $known = 'staging', 'windowsUpdate', 'applications', 'drivers', 'finalization'
    foreach ($s in @($m.stages)) {
        if ($s.id -notin $known) { throw "Deployment manifest lists an unknown stage: $($s.id)" }
        foreach ($k in 'launcher', 'result', 'status') { if ($s.ContainsKey($k) -and $s[$k] -and -not (Test-WddRelativePath $s[$k])) { throw "Stage $($s.id) has an unsafe $k path." } }
    }
    return $m
}

function Get-WddSha256 {
    param([byte[]] $Bytes)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { -join ($sha.ComputeHash($Bytes) | ForEach-Object { $_.ToString('X2') }) } finally { $sha.Dispose() }
}

# Hash of the exact file bytes (files in the package folder are byte-identical to the ZIP).
function Get-WddRawHash { param([string] $Path) Get-WddSha256 ([System.IO.File]::ReadAllBytes($Path)) }

# Hash of the text as the answer-file extraction writes it: .ps1/.xml as UTF-8 (BOM), other files
# in the system code page, line breaks normalised by the XML parser and the text trimmed. The
# manifest gives a text hash only where this is exact (ASCII text, or .ps1/.xml).
function Get-WddTextHash {
    param([string] $Path)
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    $ext = [System.IO.Path]::GetExtension($Path).ToLowerInvariant()
    $hasBom = $bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF
    $encoding = if ($hasBom -or $ext -in '.ps1', '.xml') { New-Object System.Text.UTF8Encoding($false) } else { [System.Text.Encoding]::Default }
    $start = if ($hasBom) { 3 } else { 0 }
    $text = $encoding.GetString($bytes, $start, $bytes.Length - $start)
    $text = $text.Replace("`r`n", "`n").Replace("`r", "`n").Trim()
    Get-WddSha256 ((New-Object System.Text.UTF8Encoding($false)).GetBytes($text))
}

<#
    Checks files under $Root against the manifest.
      Raw   exact bytes (a package folder copied from the ZIP).
      Text  the text hash (files extracted from the answer file, and the staged copy of either).
    $Paths limits the check to these manifest paths. A JSON file without a text hash (non-ASCII
    content in the system code page) must at least parse.
#>
function Test-WddFiles {
    param([string] $Root, [hashtable] $Manifest, [ValidateSet('Raw', 'Text')] [string] $Mode, [string[]] $Only = $null)
    $missing = @(); $mismatched = @(); $checked = 0
    foreach ($f in @($Manifest.files)) {
        if ($null -ne $Only -and $f.path -notin $Only) { continue }
        $p = Join-Path $Root ($f.path -replace '/', '\')
        if (-not (Test-Path -LiteralPath $p -PathType Leaf)) { $missing += $f.path; continue }
        $checked++
        if ($Mode -eq 'Raw') {
            if ((Get-WddRawHash $p) -ne $f.sha256) { $mismatched += $f.path }
        } elseif ($f.textSha256) {
            if ((Get-WddTextHash $p) -ne $f.textSha256) { $mismatched += $f.path }
        } elseif ($p -like '*.json') {
            try { Get-Content -LiteralPath $p -Raw | ConvertFrom-Json | Out-Null } catch { $mismatched += $f.path }
        }
    }
    @{ Ok = ($missing.Count -eq 0 -and $mismatched.Count -eq 0); Missing = $missing; Mismatched = $mismatched; Checked = $checked }
}

# ------------------------------------------------------------------------------------------------
# Single instance
# ------------------------------------------------------------------------------------------------

function Enter-WddMutex {
    param([int] $TimeoutSeconds = 0)
    $created = $false
    $m = New-Object System.Threading.Mutex($false, $script:MutexName, [ref] $created)
    try { if ($m.WaitOne([TimeSpan]::FromSeconds($TimeoutSeconds))) { return $m } } catch [System.Threading.AbandonedMutexException] { return $m }
    $m.Dispose()
    return $null
}

function Exit-WddMutex { param($Mutex) if ($Mutex) { try { $Mutex.ReleaseMutex() } catch { }; $Mutex.Dispose() } }

# ------------------------------------------------------------------------------------------------
# Deployment state and stage snapshot
# ------------------------------------------------------------------------------------------------

function Get-WddStage { param([hashtable] $Manifest, [string] $Id) @($Manifest.stages) | Where-Object { $_.id -eq $Id } | Select-Object -First 1 }

function Get-WddEngineStages { param([hashtable] $Manifest) @(@($Manifest.stages) | Where-Object { $_.id -in 'windowsUpdate', 'applications' -and $_.enabled } | Sort-Object { [int] $_.order }) }

function ConvertTo-WddDate {
    param($Value)
    if (-not $Value) { return $null }
    try { [DateTime]::Parse([string] $Value, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime() } catch { $null }
}

function Get-WddOutcome {
    param([string] $Status)
    switch ($Status) {
        'Succeeded' { 'ok' }
        'CompletedWithFollowUp' { 'followUp' }
        'CompletedWithFailures' { 'failures' }
        'Failed' { 'failed' }
        'Offline' { 'offline' }
        default { 'unknown' }
    }
}

function Test-WddRestartPending {
    param([hashtable] $Paths)
    $m = Read-WddJson $Paths.RestartMarker
    if (-not $m) { return $false }
    # The engines' shared Set-WdbRestartPending writes requestedUtc and the boot it was written in
    # (bootTimeUtc); writtenUtc is the Phase 4 name. A marker from an earlier boot is not pending.
    if ($m['bootTimeUtc']) {
        $markerBoot = ConvertTo-WddDate $m['bootTimeUtc']
        try { $boot = Get-WddBootTime } catch { return $true }
        if (-not $markerBoot -or [Math]::Abs(($markerBoot - $boot).TotalSeconds) -gt 2) { return $false }
    }
    $written = ConvertTo-WddDate $(if ($m['writtenUtc']) { $m['writtenUtc'] } else { $m['requestedUtc'] })
    if (-not $written -or ((Get-WddNow) - $written).TotalMinutes -gt 30) { return $false }
    try { $boot = Get-WddBootTime } catch { return $true }
    return $written -ge $boot
}

<#
    Snapshot of one engine stage, from what the engine itself wrote:
      Final       result.json exists (its status is the real outcome; a marker alone is never trusted)
      Running     the engine has checked in (status.json)
      Pending     launched, its task exists, not started yet
      Stalled     launched, but no task, no status and no result after the grace period, or the
                  task has gone while the stage is not final: needs manual attention
      NotStarted  not launched (yet)
      LaunchFailed the installer could not register the task
#>
function Get-WddStageSnapshot {
    param([hashtable] $Stage, [hashtable] $Paths, [hashtable] $State)
    $root = $Paths.Root
    $launch = if ($State -and $State.stages -and $State.stages.ContainsKey($Stage.id)) { $State.stages[$Stage.id] } else { $null }
    $o = [ordered]@{ id = $Stage.id; name = $Stage.name; enabled = [bool] $Stage.enabled; context = $Stage.context; state = 'NotStarted'; status = ''; outcome = ''; detail = ''; reboots = 0; updatedUtc = $null; current = ''; done = $null; total = $null; result = $null; idle = ''; outstanding = 0 }
    $result = Read-WddJson (Join-Path $root $Stage.result)
    if ($result -and $result.status -in $script:FinalStageStatuses) {
        $o.state = 'Final'; $o.status = $result.status; $o.outcome = Get-WddOutcome $result.status; $o.detail = [string] $result.reason
        $o.reboots = [int] $result.reboots; $o.updatedUtc = $result.finishedUtc; $o.result = $result
        if ($result.ContainsKey('outstanding')) { $o.outstanding = @($result.outstanding).Count }
        return $o
    }
    $status = Read-WddJson (Join-Path $root $Stage.status)
    $taskExists = Get-WddTask $Stage.task.path $Stage.task.name
    if ($status) {
        $o.status = [string] $status.phase; $o.detail = [string] $status.detail; $o.updatedUtc = $status.updatedUtc
        if ($status.ContainsKey('reboots')) { $o.reboots = [int] $status.reboots }
        if ($status.ContainsKey('done')) { $o.done = [int] $status.done; $o.total = [int] $status.total }
        if ($status.phase -eq 'Installing' -and $status.detail) { $o.current = [string] $status.detail }
    }
    if (-not $launch) { return $o }
    if ($launch.launchResult -eq 'LaunchFailed') { $o.state = 'LaunchFailed'; $o.detail = [string] $launch.message; return $o }
    $since = ConvertTo-WddDate $launch.launchedUtc
    $age = if ($since) { ((Get-WddNow) - $since).TotalMinutes } else { 0 }
    if ($taskExists) {
        $o.state = $(if ($status) { 'Running' } else { 'Pending' })
        # Phase 5: the user-context stage runs only while its user is signed in; say so when it has
        # not checked in for a long time instead of looking busy.
        $seen = ConvertTo-WddDate $o.updatedUtc
        $limit = [int] $State.stalledAfterMinutes
        if ($Stage.context -eq 'user' -and $limit -gt 0 -and $age -ge $limit -and (-not $seen -or ((Get-WddNow) - $seen).TotalMinutes -ge $limit)) {
            $who = $(if ($launch.ContainsKey('user') -and $launch.user) { [string] $launch.user } else { 'the user who started the deployment' })
            $o.idle = "has not run for more than $limit minutes; it runs only while $who is signed in."
        }
        return $o
    }
    # No task and no result: the engine removed its task without a result, or the task was deleted.
    if ($age -ge [int] $State.stalledAfterMinutes) { $o.state = 'Stalled'; if (-not $o.detail) { $o.detail = 'The scheduled task is missing and there is no result. Run Resume-Deployment.ps1.' } }
    else { $o.state = $(if ($status) { 'Running' } else { 'Pending' }) }
    return $o
}

function Get-WddSnapshot {
    param([hashtable] $Manifest, [hashtable] $Paths, [hashtable] $State)
    $stages = @()
    foreach ($s in Get-WddEngineStages $Manifest) { $stages += , (Get-WddStageSnapshot $s $Paths $State) }
    $drivers = Get-WddStage $Manifest 'drivers'
    $engine = @($stages)
    $allFinal = ($engine.Count -eq 0) -or (@($engine | Where-Object { $_.state -ne 'Final' }).Count -eq 0)
    $blocked = @($engine | Where-Object { $_.state -in 'Stalled', 'LaunchFailed' })
    $current = @($engine | Where-Object { $_.state -in 'Running', 'Pending' } | Select-Object -First 1)
    $snap = [ordered]@{
        packageId       = $Manifest.packageId
        updatedUtc      = (Get-WddNow).ToString('o')
        deploymentState = $(if ($State) { [string] $State.status } else { 'NotInitialized' })
        currentStage    = $(if ($current.Count) { $current[0].id } else { '' })
        stages          = $stages
        drivers         = [ordered]@{ id = 'drivers'; state = 'NotImplemented'; detail = $(if ($drivers) { [string] $drivers.note } else { '' }) }
        allFinal        = $allFinal
        restartPending  = (Test-WddRestartPending $Paths)
        needsAttention  = @($blocked | ForEach-Object { "$($_.name): $($_.state). $($_.detail)" })
        overall         = $(if ($allFinal) { Get-WddOverall $engine } else { 'InProgress' })
    }
    Set-WddSnapshotOutcome $snap $State
    return $snap
}

<# Adds outcome, outcomeCode and outcomeDetail (Phase 5) to a snapshot. #>
function Set-WddSnapshotOutcome {
    param($Snapshot, $State, [string] $Problem = '')
    $out = Get-WddDeploymentOutcome $State $Snapshot $Problem
    $Snapshot.outcome = $out.outcome
    $Snapshot.outcomeCode = $out.exitCode
    $Snapshot.outcomeDetail = $out.detail
}

<#
    Overall result, from the worst stage:
      Succeeded              every enabled stage Succeeded (or nothing to do)
      CompletedWithFollowUp  finished; some items need a person (interaction, sign-in, restart)
      CompletedWithFailures  finished; some updates or packages failed or were unavailable
      Incomplete             a stage ended Offline, stalled, or the deadline passed first
      Failed                 a stage Failed (or staging/integrity failed before any stage ran)
#>
function Get-WddOverall {
    param([object[]] $Stages, [switch] $DeadlineReached)
    $rank = @{ ok = 0; followUp = 1; failures = 2; offline = 3; incomplete = 3; failed = 4 }
    $worst = 'ok'
    foreach ($s in @($Stages)) {
        $o = if ($s.state -eq 'Final') { $s.outcome } else { 'incomplete' }
        if (-not $rank.ContainsKey($o)) { $o = 'failed' }
        if ($rank[$o] -gt $rank[$worst]) { $worst = $o }
    }
    if ($DeadlineReached -and $worst -ne 'failed' -and @($Stages | Where-Object { $_.state -ne 'Final' }).Count -gt 0) { $worst = 'incomplete' }
    switch ($worst) { 'ok' { 'Succeeded' } 'followUp' { 'CompletedWithFollowUp' } 'failures' { 'CompletedWithFailures' } 'failed' { 'Failed' } default { 'Incomplete' } }
}

function Save-WddState { param([hashtable] $Paths, [hashtable] $State) Write-WddJson $Paths.State $State -Backup }

$script:DeployStates = @('Staging', 'StagingFailed', 'Launching', 'InProgress', 'Completed', 'IntegrityFailed')

<# Shape check of deployment.json: a reason, or $null when the state is usable. #>
function Test-WddStateShape {
    param($S)
    if ($S -isnot [hashtable]) { return 'not an object' }
    if ("$($S['schemaVersion'])" -notmatch '^\d{1,3}$' -or [int] $S['schemaVersion'] -lt 1 -or [int] $S['schemaVersion'] -gt $script:DeployStateVersion) { return "unsupported schema version '$($S['schemaVersion'])'" }
    if ([string] $S['packageId'] -notmatch '^[0-9A-F]{16}$') { return 'no valid packageId' }
    if ([string] $S['status'] -notin $script:DeployStates) { return "unknown status '$($S['status'])'" }
    if ($S.ContainsKey('stages') -and $null -ne $S['stages'] -and $S['stages'] -isnot [hashtable]) { return 'stages is not a map' }
    return $null
}

<#
    Reads deployment.json, falling back to the last good copy (deployment.json.bak). Returns
      @{ State; Source = main | backup | missing | corrupt; Problem }
    "corrupt" (a state file exists but neither copy is usable) is never treated as "no deployment":
    callers stop and leave the decision to a technician (DeploymentRecovery.ps1 -Action Resume
    rebuilds the state from the manifest and the engines' own files).
#>
function Read-WddDeploymentState {
    param([hashtable] $Paths)
    $problems = @()
    $exists = $false
    foreach ($candidate in @($Paths.State, "$($Paths.State).bak")) {
        if (-not (Test-Path -LiteralPath $candidate)) { continue }
        $exists = $true
        $s = Read-WddJson $candidate
        $why = $(if ($null -eq $s) { 'not valid JSON' } else { Test-WddStateShape $s })
        if (-not $why) {
            if (-not $s.ContainsKey('recoveries') -or $null -eq $s['recoveries']) { $s['recoveries'] = @() }
            if (-not $s.ContainsKey('stages') -or $null -eq $s['stages']) { $s['stages'] = @{} }
            $s.schemaVersion = $script:DeployStateVersion
            if ($candidate -ne $Paths.State) {
                Write-WddLog "Deployment state recovered from its last good copy ($(Split-Path -Leaf $candidate)); the damaged file was kept as deployment.json.corrupt." 'WARN'
                if (Test-Path -LiteralPath $Paths.State) { Copy-Item -LiteralPath $Paths.State -Destination "$($Paths.State).corrupt" -Force -ErrorAction SilentlyContinue }
                return @{ State = $s; Source = 'backup'; Problem = ($problems -join '; ') }
            }
            return @{ State = $s; Source = 'main'; Problem = '' }
        }
        $problems += "$(Split-Path -Leaf $candidate): $why"
    }
    if (-not $exists) { return @{ State = $null; Source = 'missing'; Problem = '' } }
    return @{ State = $null; Source = 'corrupt'; Problem = ($problems -join '; ') }
}

# ------------------------------------------------------------------------------------------------
# Outcome (Phase 5): one machine-readable result with a stable exit code
# ------------------------------------------------------------------------------------------------

$script:OutcomeCodes = [ordered]@{
    Succeeded = 0; CompletedWithWarnings = 10; CompletedWithFailures = 20; Incomplete = 25
    PausedAwaitingNetwork = 30; PausedAwaitingReboot = 31; PausedAwaitingUser = 32; InProgress = 40
    FailedToInitialize = 50; Failed = 60
}

<#
    Where the deployment stands, for people and programs:
      ended    Succeeded, CompletedWithWarnings (manual actions or follow-ups), CompletedWithFailures,
               Incomplete (ended before every stage finished), Failed
      running  PausedAwaitingNetwork, PausedAwaitingReboot, PausedAwaitingUser, InProgress
      never    FailedToInitialize (no usable state, staging or integrity failure)
#>
function Get-WddDeploymentOutcome {
    param($State, $Snapshot, [string] $Problem = '')
    $o = { param([string] $Name, [string] $Detail) [ordered]@{ outcome = $Name; exitCode = $script:OutcomeCodes[$Name]; detail = $Detail } }
    if (-not $State) { return & $o 'FailedToInitialize' $(if ($Problem) { "The deployment state is unusable: $Problem" } else { 'No deployment has been started on this computer.' }) }
    switch ([string] $State.status) {
        'StagingFailed' { return & $o 'FailedToInitialize' ([string] $State.message) }
        'IntegrityFailed' { return & $o 'FailedToInitialize' ([string] $State.message) }
        'Completed' {
            $map = @{ Succeeded = 'Succeeded'; CompletedWithFollowUp = 'CompletedWithWarnings'; CompletedWithFailures = 'CompletedWithFailures'; Incomplete = 'Incomplete'; Failed = 'Failed' }
            $name = $(if ($map.ContainsKey([string] $State.overall)) { $map[[string] $State.overall] } else { 'Failed' })
            return & $o $name ([string] $State.message)
        }
    }
    $stages = @(if ($Snapshot) { @($Snapshot.stages) } else { @() })
    $live = @($stages | Where-Object { $_ -and $_.state -ne 'Final' })
    if (($Snapshot -and $Snapshot.restartPending) -or @($live | Where-Object { $_.status -in 'Rebooting', 'RebootDeferred' }).Count) { return & $o 'PausedAwaitingReboot' 'A restart is scheduled or in progress; the deployment continues after it.' }
    $net = @($live | Where-Object { $_.status -eq 'WaitingForNetwork' })
    if ($net.Count) { return & $o 'PausedAwaitingNetwork' ("$(($net | ForEach-Object { $_.name }) -join ', '): waiting for the network. $(($net | ForEach-Object { $_.detail } | Where-Object { $_ }) -join '; ')".Trim()) }
    $user = @($live | Where-Object { $_.state -in 'Stalled', 'LaunchFailed' -or $_.idle })
    if ($user.Count) { return & $o 'PausedAwaitingUser' (($user | ForEach-Object { "$($_.name): $(if ($_.idle) { $_.idle } else { "$($_.state). $($_.detail)" })" }) -join ' ') }
    return & $o 'InProgress' $(if ($Snapshot -and $Snapshot.currentStage) { "Current stage: $($Snapshot.currentStage)." } else { 'Stages are starting.' })
}

#Requires -Version 5.1
<#
.SYNOPSIS
    Verifies the deployment files and copies them to the protected package folder.

.DESCRIPTION
    Called by Initialize-Deployment.ps1 (and by Resume-Deployment.ps1 for a re-check). Run by hand
    it only verifies a package and changes nothing.

    Sources:
      Embedded  The files the answer file extracted during specialize under C:\Windows\Setup\Scripts
                (Administrators-only). Used at the first sign-in of a USB installation, so nothing
                depends on the USB drive still being attached or on its drive letter.
      Package   A WindowsDeployment folder (from the ZIP, on a USB drive or a local disk), identified
                by the location of the script that was started, never by guessing a drive letter.

    Every file is checked against deployment-manifest.json before anything is copied, copied to
    <dataRoot>\Package, and checked again there. Nothing is executed from the source location.
#>
[CmdletBinding()]
param(
    [ValidateSet('Embedded', 'Package')]
    [string] $SourceMode = 'Embedded',
    [string] $SourceRoot = '',
    [string] $EmbeddedRoot = 'C:\Windows\Setup\Scripts'
)

$script:StageMain = $MyInvocation.InvocationName -ne '.'
. (Join-Path $PSScriptRoot '..\common\DeploymentCommon.ps1')

# Files the orchestrator needs before it can launch anything (both modes).
$script:RequiredForStart = @(
    'scripts/common/DeploymentCommon.ps1',
    'scripts/bootstrap/Initialize-Deployment.ps1',
    'scripts/orchestrator/DeploymentOrchestrator.ps1',
    'scripts/finalization/Complete-Deployment.ps1'
)

function Set-WddAcl {
    param([string] $Root)
    # SYSTEM and Administrators full control, Users read and execute, no inherited entries (the
    # same rule as the engine installers). Elevated tasks run scripts from here.
    & icacls.exe $Root /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' '*S-1-5-32-545:(OI)(CI)RX' /T /C /Q | Out-Null
    if ($LASTEXITCODE -ne 0) { throw "icacls failed with exit code $LASTEXITCODE; refusing to run elevated scripts from an unprotected folder." }
}

# Where a manifest file comes from in each mode.
function Get-WddSourcePath {
    param([hashtable] $File, [string] $SourceMode, [string] $SourceRoot, [string] $EmbeddedRoot)
    if ($SourceMode -eq 'Package') { return Join-Path $SourceRoot ($File.path -replace '/', '\') }
    if (-not $File.embedded) { return $null }
    return Join-Path $EmbeddedRoot $File.embedded
}

<#
    Returns @{ Ok; Message; Files (staged manifest paths); Missing; Mismatched }.
#>
function Invoke-WddStage {
    param([hashtable] $Manifest, [string] $ManifestPath, [string] $SourceMode, [string] $SourceRoot, [string] $EmbeddedRoot, [hashtable] $Paths, [switch] $VerifyOnly)
    $files = @(@($Manifest.files) | Where-Object { $SourceMode -eq 'Package' -or $_.embedded })
    $relPaths = @($files | ForEach-Object { $_.path })
    foreach ($r in $script:RequiredForStart) {
        if ($r -notin $relPaths) { return @{ Ok = $false; Message = "The manifest does not list the required file $r."; Files = @(); Missing = @($r); Mismatched = @() } }
    }

    # 1. Verify the source.
    $missing = @(); $mismatched = @()
    foreach ($f in $files) {
        $src = Get-WddSourcePath $f $SourceMode $SourceRoot $EmbeddedRoot
        if (-not $src -or -not (Test-Path -LiteralPath $src -PathType Leaf)) { $missing += $f.path; continue }
        if ($SourceMode -eq 'Package') {
            if ((Get-WddRawHash $src) -ne $f.sha256) { $mismatched += $f.path }
        } elseif ($f.textSha256) {
            if ((Get-WddTextHash $src) -ne $f.textSha256) { $mismatched += $f.path }
        } elseif ($src -like '*.json') {
            try { Get-Content -LiteralPath $src -Raw | ConvertFrom-Json | Out-Null } catch { $mismatched += $f.path }
        }
    }
    if ($missing.Count -or $mismatched.Count) {
        $msg = "Package verification failed ($SourceMode): $($missing.Count) missing, $($mismatched.Count) modified."
        Write-WddLog $msg 'ERROR'
        foreach ($m in $missing) { Write-WddLog "  missing   $m" 'ERROR' }
        foreach ($m in $mismatched) { Write-WddLog "  modified  $m" 'ERROR' }
        return @{ Ok = $false; Message = $msg; Files = @(); Missing = $missing; Mismatched = $mismatched }
    }
    Write-WddLog "Verified $($files.Count) file(s) from the $SourceMode source against manifest $($Manifest.packageId)."
    if ($VerifyOnly) { return @{ Ok = $true; Message = 'Verified (no changes made).'; Files = $relPaths; Missing = @(); Mismatched = @() } }

    # 2. Copy into a fresh package folder; the previous one (from an earlier run) is kept aside.
    $target = $Paths.Package
    if (Test-Path -LiteralPath $target) {
        $previous = "$target.previous"
        if (Test-Path -LiteralPath $previous) { Remove-Item -LiteralPath $previous -Recurse -Force }
        Move-Item -LiteralPath $target -Destination $previous -Force
    }
    New-Item -ItemType Directory -Path $target -Force | Out-Null
    foreach ($f in $files) {
        $src = Get-WddSourcePath $f $SourceMode $SourceRoot $EmbeddedRoot
        $dst = Join-Path $target ($f.path -replace '/', '\')
        $dir = Split-Path -Parent $dst
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        Copy-Item -LiteralPath $src -Destination $dst -Force
    }
    Copy-Item -LiteralPath $ManifestPath -Destination (Join-Path $target 'deployment-manifest.json') -Force

    # 3. Verify the copies (text hash works for both sources).
    $check = Test-WddFiles $target $Manifest 'Text' $relPaths
    if (-not $check.Ok) {
        $msg = "Staged copy failed verification: $($check.Missing.Count) missing, $($check.Mismatched.Count) modified."
        Write-WddLog $msg 'ERROR'
        return @{ Ok = $false; Message = $msg; Files = @(); Missing = $check.Missing; Mismatched = $check.Mismatched }
    }
    Write-WddLog "Staged $($files.Count) file(s) to $target and verified them."
    @{ Ok = $true; Message = "Staged $($files.Count) file(s)."; Files = $relPaths; Missing = @(); Mismatched = @() }
}

# Dot-sourcing (tests, Initialize-Deployment.ps1) only defines the functions.
if ($script:StageMain) {
    $root = if ($SourceRoot) { $SourceRoot } else { Split-Path -Parent (Split-Path -Parent $PSScriptRoot) }
    $manifestPath = Join-Path $root 'deployment-manifest.json'
    $manifest = Read-WddManifest $manifestPath
    $paths = Get-WddPaths $manifest.dataRoot
    $r = Invoke-WddStage $manifest $manifestPath $SourceMode $root $EmbeddedRoot $paths -VerifyOnly
    $r.Message
    foreach ($m in $r.Missing) { "  missing   $m" }
    foreach ($m in $r.Mismatched) { "  modified  $m" }
    if (-not $r.Ok) { exit 1 }
    exit 0
}

#Requires -Version 5.1
<#
.SYNOPSIS
    Starts the post-installation deployment: verifies and stages the package, launches each
    enabled stage once in its own context and registers the deployment monitor.

.DESCRIPTION
    The answer file runs this as the last FirstLogon command (elevated, as the user that signs in
    first). setup.ps1 runs it for a manual deployment from a WindowsDeployment folder.

    1. Refuses Windows PE, non-elevated sessions, and a second concurrent run (mutex).
    2. Reads deployment-manifest.json and the persistent state (<dataRoot>\state\deployment.json).
       A finished deployment is not started again; a running one is not launched twice.
    3. Secures <dataRoot>, verifies the package and copies it to <dataRoot>\Package
       (Stage-Deployment.ps1). Nothing is launched if verification fails.
    4. Launches each enabled stage once, in manifest order, by running that engine's own installer
       from the staged copy:
         windowsUpdate  Install-UpdateEngine.ps1      registers a SYSTEM task
         applications   Install-ApplicationEngine.ps1 registers a task for this user (WinGet is not
                        supported as SYSTEM, so this script must run as the user, not SYSTEM)
       Each launch is recorded before it starts, so a crash cannot launch a stage twice.
    5. Registers \WindowsDeploymentBuilder\Deployment (SYSTEM; at startup and every 15 minutes),
       which follows the engines, writes status.json and, at the end, the deployment report.
    6. Opens a progress window for the signed-in user (unless -NoConsole).
#>
[CmdletBinding()]
param(
    [ValidateSet('Embedded', 'Package')]
    [string] $SourceMode = 'Embedded',
    [string] $SourceRoot = '',
    [string] $EmbeddedRoot = 'C:\Windows\Setup\Scripts',
    [switch] $NoConsole
)

$script:InitMain = $MyInvocation.InvocationName -ne '.'
# Captured first: dot-sourcing Stage-Deployment.ps1 binds its own parameters in this scope.
$script:InitArgs = @{ SourceMode = $SourceMode; SourceRoot = $SourceRoot; EmbeddedRoot = $EmbeddedRoot; NoConsole = [bool] $NoConsole }
. (Join-Path $PSScriptRoot '..\common\DeploymentCommon.ps1')
. (Join-Path $PSScriptRoot 'Stage-Deployment.ps1')

$script:MonitorTask = @{ path = '\WindowsDeploymentBuilder\'; name = 'Deployment' }

# ------------------------------------------------------------------------------------------------
# Adapters
# ------------------------------------------------------------------------------------------------

# Runs an engine installer in its own Windows PowerShell process; returns the exit code.
function Invoke-WddInstaller {
    param([string] $Path)
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $out = & $ps -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $Path 2>&1
    foreach ($line in @($out)) { Write-WddLog "    | $line" }
    return $LASTEXITCODE
}

function Register-WddMonitorTask {
    param([hashtable] $Paths, [hashtable] $Manifest)
    $script = Join-Path $Paths.Package 'scripts\orchestrator\DeploymentOrchestrator.ps1'
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $action = New-ScheduledTaskAction -Execute $ps -Argument "-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$script`""
    $atStartup = New-ScheduledTaskTrigger -AtStartup
    $atStartup.Delay = 'PT3M'
    $days = [Math]::Ceiling(([double] $Manifest.failureHandling.orchestrator.deadlineHours) / 24) + 1
    $every = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(2) -RepetitionInterval (New-TimeSpan -Minutes 15) -RepetitionDuration (New-TimeSpan -Days $days)
    $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Minutes 30)
    Register-ScheduledTask -TaskName $script:MonitorTask.name -TaskPath $script:MonitorTask.path -Action $action -Trigger @($atStartup, $every) -Principal $principal -Settings $settings -Force `
        -Description 'Windows Deployment Builder: follows the deployment stages, writes status.json and the final report, then removes itself.' | Out-Null
}

function Start-WddConsole {
    param([hashtable] $Paths)
    $show = Join-Path $Paths.Package 'scripts\orchestrator\Show-DeploymentStatus.ps1'
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    Start-Process -FilePath $ps -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$show`"", '-Watch')
}

function Get-WddRecoveryShortcut {
    param([hashtable] $Paths)
    $tool = Join-Path $Paths.Package 'scripts\recovery\DeploymentRecovery.ps1'
    if (-not (Test-Path -LiteralPath $tool)) { return $null }
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    @{ Target = $ps; Arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$tool`" -Elevate" }
}

function Get-WddProgressShortcut {
    param([hashtable] $Paths)
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    @{ Target = $ps; Arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$(Join-Path $Paths.Package 'scripts\orchestrator\Show-DeploymentStatus.ps1')`" -Watch" }
}

# ------------------------------------------------------------------------------------------------
# Initialization
# ------------------------------------------------------------------------------------------------

function New-WddState {
    param([hashtable] $Manifest, [string] $SourceMode, [hashtable] $Identity)
    $now = Get-WddNow
    @{
        schemaVersion        = 2
        packageId            = $Manifest.packageId
        packageVersion       = $Manifest.packageVersion
        orchestratorVersion  = $script:DeployVersion
        sourceMode           = $SourceMode
        status               = 'Staging'
        initializedUtc       = $now.ToString('o')
        initializedBy        = $Identity.Name
        deadlineUtc          = $now.AddHours([double] $Manifest.failureHandling.orchestrator.deadlineHours).ToString('o')
        stalledAfterMinutes  = [int] $Manifest.failureHandling.orchestrator.stalledAfterMinutes
        stagedFiles          = @()
        stages               = @{}
        monitorRuns          = 0
        overall              = ''
        message              = ''
        recoveries           = @()
    }
}

<#
    Launches one engine stage unless it was already launched. Returns its launch record.
#>
function Invoke-WddLaunchStage {
    param([hashtable] $Stage, [hashtable] $Paths, [hashtable] $State, [hashtable] $Identity, [int] $MaxAttempts)
    $rec = if ($State.stages.ContainsKey($Stage.id)) { $State.stages[$Stage.id] } else { @{ launchResult = ''; attempts = 0; launchedUtc = $null; exitCode = $null; message = '' } }
    $State.stages[$Stage.id] = $rec
    # Phase 5: who the stage runs as (a user-context stage only runs while that user is signed in).
    if (-not $rec.ContainsKey('user') -or -not $rec.user) { $rec.user = $(if ($Stage.context -eq 'user') { [string] $Identity.Name } else { 'SYSTEM' }) }
    if ($rec.launchResult -eq 'Launched') { Write-WddLog "Stage $($Stage.id) was already launched; not launching it again."; return $rec }
    # Interrupted earlier launch: if its task exists the installer finished registering it.
    if ($rec.launchResult -eq 'Launching' -and (Get-WddTask $Stage.task.path $Stage.task.name)) {
        $rec.launchResult = 'Launched'; $rec.message = 'Task found after an interrupted launch.'
        Write-WddLog "Stage $($Stage.id): task found after an interrupted launch; marked launched."
        return $rec
    }
    if ($Stage.context -eq 'user' -and $Identity.IsSystem) {
        $rec.launchResult = 'LaunchFailed'
        $rec.message = 'This stage must be started by the signed-in user (WinGet is not supported as SYSTEM). Sign in and run Resume-Deployment.ps1 -RestartStage applications.'
        Write-WddLog "Stage $($Stage.id): $($rec.message)" 'ERROR'
        return $rec
    }
    if ([int] $rec.attempts -ge $MaxAttempts) {
        $rec.launchResult = 'LaunchFailed'
        if (-not $rec.message) { $rec.message = "Launch attempts exhausted ($MaxAttempts)." }
        return $rec
    }
    $installer = Join-Path $Paths.Package ($Stage.launcher -replace '/', '\')
    $rec.attempts = [int] $rec.attempts + 1
    $rec.launchResult = 'Launching'
    $rec.launchedUtc = (Get-WddNow).ToString('o')
    Save-WddState $Paths $State
    Write-WddLog "Launching stage $($Stage.id) ($($Stage.context)): $installer"
    $code = $null
    try { $code = Invoke-WddInstaller $installer } catch { $rec.message = $_.Exception.Message; Write-WddLog "  installer error: $($rec.message)" 'ERROR' }
    $rec.exitCode = $code
    if (Get-WddTask $Stage.task.path $Stage.task.name) {
        $rec.launchResult = 'Launched'
        if ($code -ne 0) { $rec.message = "The installer returned $code, but the task is registered; it will run at the next start or sign-in." }
        Write-WddLog "Stage $($Stage.id) launched (task $($Stage.task.path)$($Stage.task.name), installer exit code $code)."
    } elseif (Test-Path -LiteralPath (Join-Path $Paths.Root $Stage.result)) {
        $rec.launchResult = 'Launched'; $rec.message = 'Finished during launch.'
    } else {
        $rec.launchResult = $(if ([int] $rec.attempts -ge $MaxAttempts) { 'LaunchFailed' } else { 'Launching' })
        if (-not $rec.message) { $rec.message = "The installer returned $code and registered no task." }
        Write-WddLog "Stage $($Stage.id): $($rec.message)" 'ERROR'
    }
    Save-WddState $Paths $State
    return $rec
}

function Invoke-WddInitialize {
    param([hashtable] $Manifest, [string] $ManifestPath, [string] $SourceMode, [string] $SourceRoot, [string] $EmbeddedRoot, [hashtable] $Paths, [switch] $NoConsole)
    Initialize-WddLogging $Paths
    $identity = Get-WddIdentity
    Write-WddLog "==== Deployment orchestrator $script:DeployVersion: initialize ($SourceMode) as $($identity.Name), package $($Manifest.packageId) ===="
    if (Test-WddWinPE) { Write-WddLog 'Refusing to run in Windows PE.' 'ERROR'; return 'RefusedWinPE' }
    if (-not $identity.IsAdmin) { Write-WddLog 'Refusing to run without administrator rights.' 'ERROR'; return 'RefusedNotElevated' }

    $mutex = Enter-WddMutex 120
    if (-not $mutex) { Write-WddLog 'Another deployment process is running; nothing to do.' 'WARN'; return 'Busy' }
    try {
        $read = Read-WddDeploymentState $Paths
        if ($read.Source -eq 'corrupt') {
            # Never start over on top of a damaged state: that would launch stages a second time.
            Write-WddLog "The deployment state is damaged ($($read.Problem)); refusing to start over. Run DeploymentRecovery.ps1 -Action Resume." 'ERROR'
            return 'StateCorrupt'
        }
        $state = $read.State
        if ($state) {
            if ($state.packageId -ne $Manifest.packageId -and $state.status -notin 'Completed', 'StagingFailed') {
                Write-WddLog "A different deployment ($($state.packageId)) is still in progress; refusing to start $($Manifest.packageId). Finish or reset it first (see recovery instructions)." 'ERROR'
                return 'AnotherDeploymentInProgress'
            }
            if ($state.packageId -eq $Manifest.packageId -and $state.status -eq 'Completed') {
                Write-WddLog "This deployment already finished ($($state.overall)). Report: $($Paths.ReportText)"
                return 'AlreadyCompleted'
            }
            if ($state.packageId -ne $Manifest.packageId) { $state = $null }
        }
        if (-not $state -or $state.status -eq 'StagingFailed') { $state = New-WddState $Manifest $SourceMode $identity }
        # A staged copy that failed its integrity check is replaced; launch records are kept, so
        # stages that were already launched are not launched again.
        if ($state.status -eq 'IntegrityFailed') { $state.status = 'Staging'; $state.sourceMode = $SourceMode; $state.message = 'Re-staging after an integrity failure.' }
        foreach ($k in 'stages') { if (-not $state[$k]) { $state[$k] = @{} } }

        # Stage (verify + copy) unless already staged for this package.
        if ($state.status -eq 'Staging') {
            Set-WddAcl $Paths.Root
            $staged = Invoke-WddStage $Manifest $ManifestPath $SourceMode $SourceRoot $EmbeddedRoot $Paths
            if (-not $staged.Ok) {
                $state.status = 'StagingFailed'; $state.overall = 'Failed'; $state.message = $staged.Message
                Save-WddState $Paths $state
                $snap = [ordered]@{ packageId = $Manifest.packageId; updatedUtc = (Get-WddNow).ToString('o'); deploymentState = 'StagingFailed'; overall = 'Failed'; message = $staged.Message; missing = $staged.Missing; modified = $staged.Mismatched }
                Set-WddSnapshotOutcome $snap $state
                Write-WddJson $Paths.Status $snap
                Write-WddEvent 3002 "Deployment not started: $($staged.Message) See $($Paths.Log)." 'Error'
                return 'StagingFailed'
            }
            Set-WddAcl $Paths.Root
            $state.stagedFiles = $staged.Files
            $state.status = 'Launching'
            Save-WddState $Paths $state
        }

        # Launch each enabled engine stage once.
        $max = [int] $Manifest.failureHandling.orchestrator.launchAttempts
        foreach ($stage in Get-WddEngineStages $Manifest) {
            Invoke-WddLaunchStage $stage $Paths $state $identity $max | Out-Null
        }

        $state.status = 'InProgress'
        Save-WddState $Paths $state
        Register-WddMonitorTask $Paths $Manifest
        Write-WddLog "Registered $($script:MonitorTask.path)$($script:MonitorTask.name) (SYSTEM; at startup and every 15 minutes)."
        $snapshot = Get-WddSnapshot $Manifest $Paths $state
        Write-WddJson $Paths.Status $snapshot
        try {
            $sc = Get-WddProgressShortcut $Paths
            New-WddShortcut 'Deployment progress' $sc.Target $sc.Arguments 'Windows Deployment Builder: deployment progress'
        } catch { Write-WddLog "Could not create the progress shortcut: $($_.Exception.Message)" 'WARN' }
        # Phase 5: the technician recovery entry point, when the package carries it.
        $rt = Get-WddRecoveryShortcut $Paths
        if ($rt) {
            try { New-WddShortcut 'Deployment recovery' $rt.Target $rt.Arguments 'Windows Deployment Builder: status, retry failed applications, resume, diagnostics (asks for administrator rights)' }
            catch { Write-WddLog "Could not create the recovery shortcut: $($_.Exception.Message)" 'WARN' }
        }
        Write-WddEvent 3000 "Deployment $($Manifest.packageId) started. Status: $($Paths.Status)."
        try { Start-WddTask $script:MonitorTask.path $script:MonitorTask.name } catch { Write-WddLog "Could not start the monitor now; it runs within 15 minutes: $($_.Exception.Message)" 'WARN' }
        if (-not $NoConsole) { try { Start-WddConsole $Paths } catch { Write-WddLog "Could not open the progress window: $($_.Exception.Message)" 'WARN' } }
        return 'Initialized'
    } finally {
        Exit-WddMutex $mutex
    }
}

# Dot-sourcing (tests) only defines the functions.
if ($script:InitMain) {
    $a = $script:InitArgs
    $root = if ($a.SourceRoot) { $a.SourceRoot } else { Split-Path -Parent (Split-Path -Parent $PSScriptRoot) }
    $manifestPath = Join-Path $root 'deployment-manifest.json'
    try {
        $manifest = Read-WddManifest $manifestPath
    } catch {
        Write-Output "ERROR: $($_.Exception.Message)"
        exit 2
    }
    $paths = Get-WddPaths $manifest.dataRoot
    $outcome = Invoke-WddInitialize $manifest $manifestPath $a.SourceMode $root $a.EmbeddedRoot $paths -NoConsole:$a.NoConsole
    Write-Output "Deployment: $outcome. Log: $($paths.Log)"
    if ($outcome -in 'Initialized', 'AlreadyCompleted', 'Busy') { exit 0 }
    exit 1
}

#Requires -Version 5.1 <# .SYNOPSIS Deployment monitor: follows the stages, keeps status.json current and finishes the deployment.
.DESCRIPTION Runs as SYSTEM from \WindowsDeploymentBuilder\Deployment (registered by Initialize-Deployment.ps1) at startup and every 15 minutes, so it survives every restart. Each run is short and idempotent:
1. Single instance (mutex shared with Initialize and Resume). 2. Verifies the staged package against its manifest before doing anything else. A modified or missing file stops the deployment monitor (IntegrityFailed); nothing is executed. 3. Reads what each engine wrote (result.json, status.json, its task) and writes <dataRoot>\Deployment\status.json. Completion markers are not trusted on their own: the final status always comes from result.json. 4. Once the windowsUpdate stage is final, applies the ongoing update policy if the package carries one (Set-UpdatePolicy.ps1, Phase 4.3). 5. When every enabled stage is final, or the deadline has passed, runs Complete-Deployment.ps1 (report, marker, event, cleanup).
It never launches or re-launches an engine. A stage whose task disappeared without a result is reported as Stalled and needs Resume-Deployment.ps1, so no stage can loop.
Phase 5: a damaged deployment.json is replaced by its last good copy; if neither is usable the monitor stops (StateCorrupt) instead of acting on a guess, and the recovery tool rebuilds it. status.json carries the machine-readable outcome (outcome, outcomeCode, outcomeDetail). #> [CmdletBinding()] param()
$script:MonitorMain = $MyInvocation.InvocationName -ne '.' . (Join-Path $PSScriptRoot '..\common\DeploymentCommon.ps1') . (Join-Path $PSScriptRoot '..\finalization\Complete-Deployment.ps1')
function Invoke-WddMonitor { param([hashtable] $Paths) Initialize-WddLogging $Paths $mutex = Enter-WddMutex 30 if (-not $mutex) { Write-WddLog 'Monitor: another deployment process is running; skipping this run.'; return 'Busy' } try { $read = Read-WddDeploymentState $Paths $state = $read.State if ($read.Source -eq 'corrupt') { $msg = "The deployment state is damaged and its backup is unusable ($($read.Problem)). The monitor stopped; nothing is run. Run DeploymentRecovery.ps1 -Action Resume to rebuild it." Write-WddLog $msg 'ERROR' $snap = [ordered]@{ updatedUtc = (Get-WddNow).ToString('o'); deploymentState = 'StateCorrupt'; overall = 'Failed'; message = $msg } Set-WddSnapshotOutcome $snap $null $read.Problem Write-WddJson $Paths.Status $snap Write-WddEvent 3004 $msg 'Error' return 'StateCorrupt' } if (-not $state) { Write-WddLog 'Monitor: no deployment state; nothing to follow.' 'WARN'; return 'NoState' } if ($state.status -eq 'Completed') { Unregister-WddTask '\WindowsDeploymentBuilder\' 'Deployment'; return 'AlreadyCompleted' } if ($state.status -eq 'IntegrityFailed') { return 'IntegrityFailed' }
$manifestPath = Join-Path $Paths.Package 'deployment-manifest.json' try { $manifest = Read-WddManifest $manifestPath } catch { $manifest = $null; $err = $_.Exception.Message } $check = if ($manifest) { Test-WddFiles $Paths.Package $manifest 'Text' @($state.stagedFiles) } else { @{ Ok = $false; Missing = @('deployment-manifest.json'); Mismatched = @() } } if (-not $check.Ok -or ($manifest -and $manifest.packageId -ne $state.packageId)) { $state.status = 'IntegrityFailed' $state.message = "The staged package was modified or is incomplete ($($check.Missing.Count) missing, $($check.Mismatched.Count) modified). The monitor stopped; nothing more is run by it." Save-WddState $Paths $state Write-WddLog $state.message 'ERROR' foreach ($m in @($check.Missing) + @($check.Mismatched)) { Write-WddLog " $m" 'ERROR' } $snap = [ordered]@{ packageId = $state.packageId; updatedUtc = (Get-WddNow).ToString('o'); deploymentState = 'IntegrityFailed'; overall = 'Failed'; message = $state.message } Set-WddSnapshotOutcome $snap $state Write-WddJson $Paths.Status $snap Write-WddEvent 3003 $state.message 'Error' return 'IntegrityFailed' }
$state.monitorRuns = [int] $state.monitorRuns + 1 $state.lastMonitorUtc = (Get-WddNow).ToString('o') $snapshot = Get-WddSnapshot $manifest $Paths $state # Phase 4.3: the ongoing update policy, once the initial Windows Update stage is final. if (Get-Command Step-WddUpdatePolicy -ErrorAction SilentlyContinue) { $policy = Step-WddUpdatePolicy $manifest $Paths $state $snapshot if ($policy) { $snapshot.updatePolicy = $policy } } Save-WddState $Paths $state Write-WddJson $Paths.Status $snapshot $summary = (@($snapshot.stages) | ForEach-Object { "$($_.id)=$($_.state)$(if ($_.status) { "/$($_.status)" })" }) -join ', ' Write-WddLog "Monitor run $($state.monitorRuns): $summary"
if ($snapshot.allFinal) { $overall = Complete-WddDeployment $manifest $Paths $state $snapshot return "Completed:$overall" } $deadline = ConvertTo-WddDate $state.deadlineUtc if ($deadline -and (Get-WddNow) -ge $deadline) { Write-WddLog "Deadline $($state.deadlineUtc) reached with unfinished stages." 'WARN' $overall = Complete-WddDeployment $manifest $Paths $state $snapshot -DeadlineReached return "Completed:$overall" } return 'InProgress' } finally { Exit-WddMutex $mutex } }
if ($script:MonitorMain) { # The monitor lives in <dataRoot>\Package\scripts\orchestrator; dataRoot comes from the manifest. $package = Split-Path -Parent (Split-Path -Parent $PSScriptRoot) $manifest = Read-WddManifest (Join-Path $package 'deployment-manifest.json') $outcome = Invoke-WddMonitor (Get-WddPaths $manifest.dataRoot) Write-Output $outcome if ($outcome -in 'IntegrityFailed', 'StateCorrupt') { exit 1 } exit 0 }

#Requires -Version 5.1
<#
.SYNOPSIS
    Shows the deployment progress in the console (read-only; no elevation needed).

.DESCRIPTION
    Reads the deployment state and what each engine wrote, live (it does not wait for the monitor):
    current stage, finished stages, the application being installed, applications remaining,
    pending restart, warnings, failures and whether a person needs to act.

    -Watch refreshes every 15 seconds until the deployment has finished. The window that opens
    after the first sign-in runs this with -Watch; it can be closed at any time without affecting
    the deployment.
#>
[CmdletBinding()]
param(
    [switch] $Watch,
    [int] $IntervalSeconds = 15
)

$script:ShowMain = $MyInvocation.InvocationName -ne '.'
$script:ShowArgs = @{ Watch = [bool] $Watch; Interval = $IntervalSeconds }
. (Join-Path $PSScriptRoot '..\common\DeploymentCommon.ps1')

function Format-WddStatus {
    param([hashtable] $Manifest, [hashtable] $Paths, [hashtable] $State)
    $s = Get-WddSnapshot $Manifest $Paths $State
    $l = New-Object System.Collections.Generic.List[string]
    $l.Add('Windows Deployment Builder - deployment progress')
    $l.Add('================================================')
    $overall = if ($State -and $State.status -eq 'Completed') { "Finished: $($State.overall)" } elseif ($State) { $State.status } else { 'Not started' }
    $l.Add("Deployment     : $overall")
    $l.Add("Outcome        : $($s.outcome) (code $($s.outcomeCode)) $($s.outcomeDetail)")
    if ($State -and $State.message) { $l.Add("                 $($State.message)") }
    if ($State) { $l.Add("Started (UTC)  : $($State.initializedUtc)   deadline: $($State.deadlineUtc)") }
    $l.Add("Current stage  : $(if ($s.currentStage) { $s.currentStage } else { '-' })")
    $l.Add("Restart pending: $(if ($s.restartPending) { 'yes (a restart has been scheduled)' } else { 'no' })")
    $l.Add('')
    $l.Add(('{0,-22} {1,-12} {2,-22} {3}' -f 'Stage', 'State', 'Status', 'Detail'))
    foreach ($st in @($s.stages)) {
        $l.Add(('{0,-22} {1,-12} {2,-22} {3}' -f $st.name, $st.state, $st.status, $st.detail))
        if ($st.id -eq 'applications') {
            if ($st.current) { $l.Add("  installing now: $($st.current)") }
            if ($null -ne $st.total -and [int] $st.total -gt 0) { $l.Add("  applications: $($st.done) of $($st.total) done, $([int] $st.total - [int] $st.done) remaining") }
        }
        if ($st.reboots) { $l.Add("  restarts so far: $($st.reboots)") }
        if ($st.idle) { $l.Add("  note: $($st.idle)") }
        if ($st.outstanding) { $l.Add("  outstanding operations: $($st.outstanding) (retry them with the deployment recovery tool)") }
    }
    $l.Add(('{0,-22} {1,-12} {2,-22} {3}' -f 'Manufacturer drivers', 'NotImplemented', '', 'Not part of this version'))
    $l.Add('')
    if (@($s.needsAttention).Count) {
        $l.Add('NEEDS ATTENTION')
        foreach ($n in $s.needsAttention) { $l.Add("  - $n") }
        $l.Add("  Recovery: run (elevated) $(Join-Path $Paths.Package 'scripts\orchestrator\Resume-Deployment.ps1')")
        $l.Add('')
    }
    if ($State -and $State.status -in 'StagingFailed', 'IntegrityFailed') { $l.Add("FAILED: $($State.message)"); $l.Add('') }
    if (Test-Path -LiteralPath $Paths.ReportText) { $l.Add("Report: $($Paths.ReportText)") }
    $l.Add("Logs  : $($Paths.Log)")
    [pscustomobject]@{ Text = ($l -join "`r`n"); Done = [bool] ($State -and $State.status -in 'Completed', 'StagingFailed', 'IntegrityFailed') }
}

if ($script:ShowMain) {
    $package = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
    $manifest = Read-WddManifest (Join-Path $package 'deployment-manifest.json')
    $paths = Get-WddPaths $manifest.dataRoot
    do {
        $state = (Read-WddDeploymentState $paths).State
        $out = Format-WddStatus $manifest $paths $state
        if ($script:ShowArgs.Watch) { Clear-Host }
        Write-Output $out.Text
        if (-not $script:ShowArgs.Watch -or $out.Done) { break }
        Write-Output ''
        Write-Output "Refreshing every $($script:ShowArgs.Interval) s. You can close this window; the deployment continues."
        Start-Sleep -Seconds $script:ShowArgs.Interval
    } while ($true)
    if ($script:ShowArgs.Watch) { Write-Output ''; Read-Host 'Press Enter to close' | Out-Null }
    exit 0
}

#Requires -Version 5.1
<#
.SYNOPSIS
    Manual recovery for a deployment: re-checks the package, re-registers the monitor and, only
    when asked, restarts a stage.

.DESCRIPTION
    Run elevated (as the signed-in user when restarting the applications stage):

      Resume-Deployment.ps1
          Verifies <dataRoot>\Package, registers the monitor task again and runs it once. Use it
          after a stalled stage was fixed, after the deadline passed, or if the monitor task was
          removed. A finished deployment is reopened (its report is rewritten at the end).
      Resume-Deployment.ps1 -RestartStage windowsUpdate|applications
          Runs that engine's installer again. The installer archives the previous run and starts
          a new one; work already done is detected (installed updates are not offered again,
          installed applications are reported AlreadyInstalled).
      Resume-Deployment.ps1 -Status
          Prints the progress and changes nothing.

    It never deletes logs, results or the state file.
#>
[CmdletBinding()]
param(
    [ValidateSet('', 'windowsUpdate', 'applications')]
    [string] $RestartStage = '',
    [switch] $Status
)

$script:ResumeMain = $MyInvocation.InvocationName -ne '.'
$script:ResumeArgs = @{ RestartStage = $RestartStage; Status = [bool] $Status }
. (Join-Path $PSScriptRoot '..\common\DeploymentCommon.ps1')
. (Join-Path $PSScriptRoot '..\bootstrap\Initialize-Deployment.ps1')
. (Join-Path $PSScriptRoot 'Show-DeploymentStatus.ps1')

function Invoke-WddResume {
    param([hashtable] $Paths, [string] $RestartStage)
    Initialize-WddLogging $Paths
    $identity = Get-WddIdentity
    if (-not $identity.IsAdmin) { return 'RefusedNotElevated' }
    $mutex = Enter-WddMutex 60
    if (-not $mutex) { return 'Busy' }
    try {
        $read = Read-WddDeploymentState $Paths
        if ($read.Source -eq 'corrupt') { Write-WddLog "Resume: the deployment state is damaged ($($read.Problem)). Use DeploymentRecovery.ps1 -Action Resume, which rebuilds it." 'ERROR'; return 'StateCorrupt' }
        $state = $read.State
        if (-not $state) { Write-WddLog 'Resume: no deployment state. Start a deployment with setup.ps1 or Initialize-Deployment.ps1.' 'ERROR'; return 'NoState' }
        $manifestPath = Join-Path $Paths.Package 'deployment-manifest.json'
        $manifest = Read-WddManifest $manifestPath
        $check = Test-WddFiles $Paths.Package $manifest 'Text' @($state.stagedFiles)
        if (-not $check.Ok) {
            Write-WddLog "Resume refused: the staged package is modified or incomplete ($($check.Missing.Count) missing, $($check.Mismatched.Count) modified). Run setup.ps1 from the original package to stage it again." 'ERROR'
            return 'IntegrityFailed'
        }
        Write-WddLog "==== Resume requested by $($identity.Name)$(if ($RestartStage) { " (restart stage $RestartStage)" }) ===="
        if ($state.status -in 'Completed', 'IntegrityFailed') {
            if (Test-Path -LiteralPath $Paths.Marker) { Move-Item -LiteralPath $Paths.Marker -Destination "$($Paths.Marker).$((Get-WddNow).ToString('yyyyMMddHHmmss')).bak" -Force }
        }
        $state.status = 'InProgress'
        $state.message = 'Resumed manually.'
        $state.deadlineUtc = (Get-WddNow).AddHours([double] $manifest.failureHandling.orchestrator.deadlineHours).ToString('o')
        if ($RestartStage) {
            $stage = Get-WddStage $manifest $RestartStage
            if (-not $stage -or -not $stage.enabled) { Write-WddLog "Stage $RestartStage is not part of this deployment." 'ERROR'; return 'UnknownStage' }
            $state.stages[$RestartStage] = @{ launchResult = ''; attempts = 0; launchedUtc = $null; exitCode = $null; message = 'Restarted manually.' }
            Invoke-WddLaunchStage $stage $Paths $state $identity ([int] $manifest.failureHandling.orchestrator.launchAttempts) | Out-Null
        }
        Save-WddState $Paths $state
        Register-WddMonitorTask $Paths $manifest
        try { Start-WddTask $script:MonitorTask.path $script:MonitorTask.name } catch { }
        Write-WddEvent 3001 "Deployment $($manifest.packageId) resumed manually$(if ($RestartStage) { " (stage $RestartStage restarted)" })."
        return 'Resumed'
    } finally {
        Exit-WddMutex $mutex
    }
}

if ($script:ResumeMain) {
    $package = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
    $manifest = Read-WddManifest (Join-Path $package 'deployment-manifest.json')
    $paths = Get-WddPaths $manifest.dataRoot
    if ($script:ResumeArgs.Status) { (Format-WddStatus $manifest $paths (Read-WddDeploymentState $paths).State).Text; exit 0 }
    $outcome = Invoke-WddResume $paths $script:ResumeArgs.RestartStage
    Write-Output "Resume: $outcome. Log: $($paths.Log)"
    if ($outcome -eq 'Resumed') { exit 0 }
    exit 1
}

#Requires -Version 5.1
<#
.SYNOPSIS
    Writes the final deployment report and cleans up the deployment monitor.

.DESCRIPTION
    Called by DeploymentOrchestrator.ps1 when every enabled stage has a final result, or when the
    deployment deadline has passed. Run by hand (elevated) it writes the report for the current
    state without ending the deployment (-Preview), or ends it now (-Finish).

    Writes <dataRoot>\reports\deployment-report.json and deployment-report.txt, the marker
    <dataRoot>\state\deployment.done (with the overall status; a marker is never proof of success
    on its own), an Application event, and a "Deployment report" shortcut on the public desktop.
    It removes only the monitor task. Logs, state and the engines' results are kept.
#>
[CmdletBinding()]
param(
    [switch] $Preview,
    [switch] $Finish
)

$script:CompleteMain = $MyInvocation.InvocationName -ne '.'
$script:CompleteArgs = @{ Preview = [bool] $Preview; Finish = [bool] $Finish }
. (Join-Path $PSScriptRoot '..\common\DeploymentCommon.ps1')
# Phase 4.3: present only when the ongoing update policy is applied after the initial updates.
$script:PolicyScript = Join-Path $PSScriptRoot 'Set-UpdatePolicy.ps1'
if (Test-Path -LiteralPath $script:PolicyScript) { . $script:PolicyScript }

function Get-WddSystemInfo {
    $os = Get-CimInstance -ClassName Win32_OperatingSystem
    $cs = Get-CimInstance -ClassName Win32_ComputerSystem
    $cv = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
    [ordered]@{
        computerName   = $env:COMPUTERNAME
        windows        = [string] $os.Caption
        edition        = $(if ($cv) { [string] $cv.EditionID } else { '' })
        displayVersion = $(if ($cv -and $cv.PSObject.Properties['DisplayVersion']) { [string] $cv.DisplayVersion } else { '' })
        build          = $(if ($cv) { '{0}.{1}' -f $cv.CurrentBuildNumber, $cv.UBR } else { [string] $os.BuildNumber })
        installDateUtc = $os.InstallDate.ToUniversalTime().ToString('o')
        manufacturer   = [string] $cs.Manufacturer
        model          = [string] $cs.Model
    }
}

function New-WddReport {
    param([hashtable] $Manifest, [hashtable] $Paths, [hashtable] $State, $Snapshot, [string] $Overall, [string] $Reason)
    $system = try { Get-WddSystemInfo } catch { [ordered]@{ computerName = $env:COMPUTERNAME; error = $_.Exception.Message } }
    $wu = @($Snapshot.stages | Where-Object { $_.id -eq 'windowsUpdate' }) | Select-Object -First 1
    $apps = @($Snapshot.stages | Where-Object { $_.id -eq 'applications' }) | Select-Object -First 1
    $remaining = @(); $errors = @(); $incomplete = @()
    $wuReport = $null
    if ($wu) {
        $r = $wu.result
        $failed = @(if ($r) { @($r.failed) | Where-Object { $_ } | ForEach-Object { [ordered]@{ kbs = @($_.kbs); title = $_.title; attempts = $_.attempts; lastResult = $_.lastResult; lastHResult = $_.lastHResult } } })
        $wuReport = [ordered]@{ state = $wu.state; status = $wu.status; reason = $wu.detail; reboots = $wu.reboots
                                installed = $(if ($r) { @($r.installed).Count } else { $null }); skipped = $(if ($r) { @($r.skipped).Count } else { $null }); failedUpdates = $failed }
        foreach ($f in $failed) { $remaining += "Windows Update: $((@($f.kbs) -join ', ')) $($f.title) failed after $($f.attempts) attempt(s)." }
        if ($wu.state -ne 'Final') { $incomplete += "Windows Update ($($wu.state))" }
        elseif ($wu.status -eq 'Offline') { $incomplete += 'Windows Update (Offline: no network before its runtime limit)' }
        elseif ($wu.status -eq 'Failed') { $errors += "Windows Update failed: $($wu.detail)" }
    }
    $appsReport = $null
    if ($apps) {
        $r = $apps.result
        # Phase 5: lifecycle, failure class and attempt totals come from result schema 2 (absent in schema 1).
        $pk = @(if ($r) { @($r.packages) | Where-Object { $_ } | ForEach-Object {
            $x = [ordered]@{ name = $_.name; packageIdentifier = $_.packageIdentifier; source = $_.source; status = $_.status; attempts = $_.attempts; exitCode = $_.exitCode; message = $_.message }
            foreach ($k in 'operationId', 'lifecycle', 'failureClass', 'retryable', 'detection', 'totalAttempts', 'manualRetries') { if ($_.ContainsKey($k)) { $x[$k] = $_[$k] } }
            $x
        } })
        $add = @(if ($r) { @($r.additionalSoftware) | Where-Object { $_ } })
        $appsReport = [ordered]@{ state = $apps.state; status = $apps.status; reason = $apps.detail; reboots = $apps.reboots
                                  counts = $(if ($r) { $r.counts } else { $null }); packages = $pk; additionalSoftware = $add
                                  requiresInteraction = @($pk | Where-Object { $_.status -eq 'RequiresInteraction' } | ForEach-Object { $_.name })
                                  bootstrap = $(if ($r) { $r.bootstrap } else { $null }) }
        foreach ($p in $pk) { if ($p.status -in 'RequiresInteraction', 'RequiresRestart', 'Failed', 'Unavailable', 'Pending') { $remaining += "Application $($p.name) ($($p.source):$($p.packageIdentifier)): $($p.status). $($p.message)" } }
        foreach ($a in $add) { if ($a.status -ne 'Succeeded') { $remaining += "Additional Software $($a.name): $($a.status). $($a.message)" } }
        if ($apps.state -ne 'Final') { $incomplete += "Applications ($($apps.state))" }
        elseif ($apps.status -eq 'Offline') { $incomplete += 'Applications (Offline)' }
        elseif ($apps.status -eq 'Failed') { $errors += "Application setup failed: $($apps.detail)" }
    }
    foreach ($n in @($Snapshot.needsAttention)) { $errors += $n }
    # Phase 4.3: written by Add-WifiProfile.ps1 when the answer file adds a Wi-Fi profile (never contains the key).
    $wifi = Read-WddJson (Join-Path $Paths.Root 'Network\wifi-result.json')
    if ($wifi -and $wifi.status -notin 'Added', 'ConnectRequested', 'ConnectFailed') { $remaining += "Wi-Fi: $($wifi.status). $($wifi.message)" }
    $policy = $(if ($State.ContainsKey('updatePolicy')) { $State.updatePolicy } else { $null })
    if ($Manifest.ContainsKey('updatePolicy') -and $Manifest.updatePolicy) {
        if (-not $policy) { $remaining += 'Ongoing Windows Update policy: not applied. Set it under Settings > Windows Update or re-run the deployment.' }
        elseif ($policy.status -notin 'Applied', 'AlreadyApplied') { $remaining += "Ongoing Windows Update policy: $($policy.status). $($policy.message)" }
    }
    $remaining += 'Manufacturer drivers: not part of this deployment (driver stage not implemented). Install chipset, graphics and OEM drivers manually if Windows Update did not provide them.'
    # Phase 5: what is still open and how to recover it, kept after the deployment ends.
    $tool = Join-Path $Paths.Package 'scripts\recovery\DeploymentRecovery.ps1'
    $hasTool = Test-Path -LiteralPath $tool
    $outstanding = @()
    if ($apps -and $apps.result -and $apps.result.ContainsKey('outstanding')) {
        foreach ($x in @($apps.result.outstanding) | Where-Object { $_ }) {
            $how = switch ([string] $x.lifecycle) {
                'FailedRetryable' { 'retry (automatic retries used up)' } 'BlockedByDependency' { 'retry (with its dependency)' }
                'WaitingForNetwork' { 'resume when the network is back' } 'Pending' { 'resume' } 'FailedPermanent' { 'correct the cause, then retry with -IncludePermanent' }
                'ManualActionRequired' { 'install or finish it by hand' } 'WaitingForReboot' { 'restart the computer' } default { 'check' }
            }
            $outstanding += [ordered]@{ operationId = $x.operationId; name = $x.name; lifecycle = $x.lifecycle; failureClass = $x.failureClass; retryable = $x.retryable; action = $how; message = $x.message }
        }
    } elseif ($apps -and $apps.state -ne 'Final') {
        $outstanding += [ordered]@{ operationId = 'stage:applications'; name = 'Applications'; lifecycle = 'Pending'; failureClass = ''; retryable = $true; action = 'resume'; message = "The application stage is $($apps.state)." }
    }
    if ($wu -and $wu.state -eq 'Final' -and $wu.status -in 'CompletedWithFailures', 'Failed', 'Offline') {
        $outstanding += [ordered]@{ operationId = 'stage:windowsUpdate'; name = 'Windows Update'; lifecycle = 'FailedRetryable'; failureClass = $(if ($wu.status -eq 'Offline') { 'Network' } else { 'Transient' }); retryable = $true; action = 'retry the update stage (installed updates are never offered again)'; message = [string] $wu.detail }
    }
    $recoveryCommands = [ordered]@{
        status      = "powershell.exe -ExecutionPolicy Bypass -File `"$tool`" -Action Status"
        retryFailed = "powershell.exe -ExecutionPolicy Bypass -File `"$tool`" -Action RetryFailed"
        retryOne    = "powershell.exe -ExecutionPolicy Bypass -File `"$tool`" -Action Retry -Operation <operationId>"
        resume      = "powershell.exe -ExecutionPolicy Bypass -File `"$tool`" -Action Resume"
        diagnostics = "powershell.exe -ExecutionPolicy Bypass -File `"$tool`" -Action ExportDiagnostics"
    }
    $outcome = Get-WddDeploymentOutcome @{ status = 'Completed'; overall = $Overall; message = $Reason } $null
    [ordered]@{
        format             = 'windows-deployment-builder/deployment-report'
        reportVersion      = 2
        overall            = $Overall
        outcome            = $outcome.outcome
        outcomeCode        = $outcome.exitCode
        reason             = $Reason
        generatedUtc       = (Get-WddNow).ToString('o')
        packageId          = $Manifest.packageId
        packageVersion     = $Manifest.packageVersion
        orchestratorVersion = $script:DeployVersion
        startedUtc         = $State.initializedUtc
        deadlineUtc        = $State.deadlineUtc
        system             = $system
        windowsUpdate      = $wuReport
        applications       = $appsReport
        updatePolicy       = $policy
        wifi               = $wifi
        drivers            = [ordered]@{ state = 'NotImplemented'; note = 'No driver was installed or changed by this deployment.' }
        restarts           = [ordered]@{ windowsUpdate = $(if ($wu) { $wu.reboots } else { 0 }); applications = $(if ($apps) { $apps.reboots } else { 0 }) }
        incompleteStages   = $incomplete
        errors             = $errors
        remainingTasks     = $remaining
        outstanding        = $outstanding
        recoveries         = @(if ($State.ContainsKey('recoveries')) { @($State.recoveries) })
        logs               = [ordered]@{ deployment = $Paths.Log; windowsUpdate = (Join-Path $Paths.Root 'Updates\logs\engine.log'); applications = (Join-Path $Paths.Root 'Applications\logs\engine.log'); attempts = (Join-Path $Paths.Root 'Applications\logs\attempts.jsonl') }
        recovery           = "$(if ($hasTool) { "Recovery tool (as administrator; status, retry, resume, diagnostics): $($recoveryCommands.status). " })Resume only: powershell.exe -ExecutionPolicy Bypass -File `"$(Join-Path $Paths.Package 'scripts\orchestrator\Resume-Deployment.ps1')`""
        recoveryCommands   = $(if ($hasTool) { $recoveryCommands } else { $null })
    }
}

function Format-WddReport {
    param($Report)
    $l = New-Object System.Collections.Generic.List[string]
    $l.Add('Windows Deployment Builder - deployment report')
    $l.Add('==============================================')
    $l.Add("Overall result : $($Report.overall)")
    if ($Report.Contains('outcome')) { $l.Add("Outcome        : $($Report.outcome) (exit code $($Report.outcomeCode))") }
    if ($Report.reason) { $l.Add("               : $($Report.reason)") }
    $l.Add("Generated (UTC): $($Report.generatedUtc)")
    $l.Add("Package        : $($Report.packageId) (package $($Report.packageVersion), orchestrator $($Report.orchestratorVersion))")
    $l.Add('')
    $l.Add('Computer')
    foreach ($k in $Report.system.Keys) { $l.Add(('  {0,-15} {1}' -f $k, $Report.system[$k])) }
    $l.Add('')
    $l.Add('Windows Update')
    if ($Report.windowsUpdate) {
        $w = $Report.windowsUpdate
        $l.Add("  Result: $($w.status) ($($w.state)). $($w.reason)")
        $l.Add("  Installed: $($w.installed)  Skipped by policy: $($w.skipped)  Restarts: $($w.reboots)")
        foreach ($f in @($w.failedUpdates)) { $l.Add("  FAILED  $((@($f.kbs) -join ', ')) $($f.title) ($($f.attempts) attempts, $($f.lastHResult))") }
    } else { $l.Add('  Not part of this deployment.') }
    $l.Add('')
    $l.Add('Applications (WinGet)')
    if ($Report.applications) {
        $a = $Report.applications
        $l.Add("  Result: $($a.status) ($($a.state)). $($a.reason)")
        $l.Add("  Restarts: $($a.reboots)")
        foreach ($p in @($a.packages)) {
            $tries = $(if ($p.Contains('totalAttempts') -and [int] $p.totalAttempts -gt 1) { " [$($p.totalAttempts) attempts$(if ([int] $p.manualRetries) { ", $($p.manualRetries) manual retr$(if ([int] $p.manualRetries -eq 1) { 'y' } else { 'ies' })" })]" } else { '' })
            $l.Add(('  {0,-20} {1} ({2}:{3}){4} {5}' -f $p.status, $p.name, $p.source, $p.packageIdentifier, $tries, $p.message))
        }
        foreach ($s in @($a.additionalSoftware)) { $l.Add(('  {0,-20} {1} (Additional Software) {2}' -f $s.status, $s.name, $s.message)) }
    } else { $l.Add('  Not part of this deployment.') }
    $l.Add('')
    if ($Report.Contains('updatePolicy') -and $Report.updatePolicy) {
        $l.Add('Ongoing Windows Update policy (after the initial updates)')
        $l.Add("  $($Report.updatePolicy.status). $($Report.updatePolicy.message)")
        $l.Add('')
    }
    if ($Report.Contains('wifi') -and $Report.wifi) {
        $l.Add('Wi-Fi profile')
        $l.Add("  $($Report.wifi.status) ($($Report.wifi.profileName)). $($Report.wifi.message)")
        $l.Add('')
    }
    $l.Add('Manufacturer drivers')
    $l.Add('  Not implemented in this version; nothing was installed or changed.')
    $l.Add('')
    $l.Add('Incomplete stages')
    if (@($Report.incompleteStages).Count) { foreach ($x in $Report.incompleteStages) { $l.Add("  - $x") } } else { $l.Add('  None.') }
    $l.Add('')
    $l.Add('Errors')
    if (@($Report.errors).Count) { foreach ($x in $Report.errors) { $l.Add("  - $x") } } else { $l.Add('  None.') }
    $l.Add('')
    $l.Add('Remaining tasks')
    foreach ($x in $Report.remainingTasks) { $l.Add("  - $x") }
    $l.Add('')
    if ($Report.Contains('outstanding')) {
        $l.Add('Outstanding work (kept for recovery)')
        if (@($Report.outstanding).Count) {
            foreach ($x in $Report.outstanding) { $l.Add(('  {0,-22} {1} [{2}]: {3}' -f $x.lifecycle, $x.name, $x.operationId, $x.action)) }
        } else { $l.Add('  None.') }
        $l.Add('')
    }
    $l.Add('Logs')
    foreach ($k in $Report.logs.Keys) { $l.Add(('  {0,-14} {1}' -f $k, $Report.logs[$k])) }
    $l.Add('')
    $l.Add("Recovery: $($Report.recovery)")
    if ($Report.Contains('recoveryCommands') -and $Report.recoveryCommands) {
        foreach ($k in $Report.recoveryCommands.Keys) { $l.Add(('  {0,-12} {1}' -f $k, $Report.recoveryCommands[$k])) }
    }
    return ($l -join "`r`n") + "`r`n"
}

function Write-WddReport {
    param($Report, [hashtable] $Paths)
    Write-WddJson $Paths.ReportJson $Report
    [System.IO.File]::WriteAllText($Paths.ReportText, (Format-WddReport $Report), (New-Object System.Text.UTF8Encoding($true)))
}

<#
    Ends the deployment: report, marker, event, shortcuts, monitor task removal. State is kept.
#>
function Complete-WddDeployment {
    param([hashtable] $Manifest, [hashtable] $Paths, [hashtable] $State, $Snapshot, [switch] $DeadlineReached)
    if (Get-Command Step-WddUpdatePolicy -ErrorAction SilentlyContinue) { $null = Step-WddUpdatePolicy $Manifest $Paths $State $Snapshot -Force }
    $overall = Get-WddOverall $Snapshot.stages -DeadlineReached:$DeadlineReached
    # A policy that could not be applied is a follow-up, never a silent success.
    if ($overall -eq 'Succeeded' -and $Manifest.ContainsKey('updatePolicy') -and $Manifest.updatePolicy -and -not ($State.ContainsKey('updatePolicy') -and $State.updatePolicy -and $State.updatePolicy.status -in 'Applied', 'AlreadyApplied')) { $overall = 'CompletedWithFollowUp' }
    $reason = if ($DeadlineReached -and -not $Snapshot.allFinal) { "The deployment deadline ($($State.deadlineUtc)) passed before every stage finished." } elseif (@($Snapshot.stages).Count -eq 0) { 'No post-installation stage was enabled.' } else { 'Every enabled stage has a final result.' }
    $report = New-WddReport $Manifest $Paths $State $Snapshot $overall $reason
    Write-WddReport $report $Paths
    $now = (Get-WddNow).ToString('o')
    Write-WddJson $Paths.Marker ([ordered]@{ status = $overall; finishedUtc = $now; report = $Paths.ReportJson })
    $State.status = 'Completed'; $State.overall = $overall; $State.completedUtc = $now; $State.message = $reason
    Save-WddState $Paths $State
    $Snapshot.deploymentState = 'Completed'
    $Snapshot.overall = $overall
    Set-WddSnapshotOutcome $Snapshot $State
    Write-WddJson $Paths.Status $Snapshot
    Write-WddLog "FINISHED: $overall. $reason Report: $($Paths.ReportText)" $(if ($overall -eq 'Succeeded') { 'INFO' } else { 'WARN' })
    $eventId = switch ($overall) { 'Succeeded' { 3100 } 'CompletedWithFollowUp' { 3101 } 'CompletedWithFailures' { 3102 } 'Failed' { 3103 } default { 3104 } }
    Write-WddEvent $eventId "Deployment $($Manifest.packageId) finished: $overall. $reason Report: $($Paths.ReportText)" $(if ($overall -eq 'Succeeded') { 'Information' } elseif ($overall -eq 'Failed') { 'Error' } else { 'Warning' })
    try {
        Remove-WddShortcut 'Deployment progress'
        New-WddShortcut 'Deployment report' (Join-Path $env:SystemRoot 'System32\notepad.exe') "`"$($Paths.ReportText)`"" 'Windows Deployment Builder: deployment report'
    } catch { Write-WddLog "Could not update the desktop shortcuts: $($_.Exception.Message)" 'WARN' }
    try { Unregister-WddTask '\WindowsDeploymentBuilder\' 'Deployment' } catch { Write-WddLog "Could not remove the monitor task: $($_.Exception.Message)" 'WARN' }
    return $overall
}

if ($script:CompleteMain) {
    $package = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
    $manifest = Read-WddManifest (Join-Path $package 'deployment-manifest.json')
    $paths = Get-WddPaths $manifest.dataRoot
    Initialize-WddLogging $paths
    $state = (Read-WddDeploymentState $paths).State
    if (-not $state) { Write-Output 'No deployment state found.'; exit 1 }
    $snapshot = Get-WddSnapshot $manifest $paths $state
    if ($script:CompleteArgs.Finish) {
        $overall = Complete-WddDeployment $manifest $paths $state $snapshot -DeadlineReached
        Write-Output "Deployment ended: $overall. Report: $($paths.ReportText)"
    } else {
        $report = New-WddReport $manifest $paths $state $snapshot $snapshot.overall 'Preview of the current state (the deployment continues).'
        Format-WddReport $report
    }
    exit 0
}

#Requires -Version 5.1
<#
.SYNOPSIS
    Applies the ongoing (post-deployment) Windows Update policy after the initial update stage.

.DESCRIPTION
    Phase 4.3. Dot-sourced by Complete-Deployment.ps1 (and so by DeploymentOrchestrator.ps1). It is
    part of the package only when the deployment runs the initial Windows Update engine AND the
    chosen ongoing policy is a "notify" mode; otherwise the answer file writes the policy during
    specialize exactly as before.

    The initial update engine (WindowsUpdateEngine.ps1) is not changed and does not read this
    policy. This step runs from the SYSTEM monitor only once the windowsUpdate stage has a final
    result (or when the deployment ends at its deadline), applies the documented
    "Configure Automatic Updates" registry policy once, reads it back and records the outcome:

      Applied               NoAutoUpdate/AUOptions written and read back
      AlreadyApplied        the values were already exactly these
      Unsupported           Windows Home: the policy is not supported; Windows defaults stay
      ManagedByOrganization domain, MDM or update-server management detected; nothing written
      Conflict              other Automatic Updates policy values already exist; left unchanged
      Failed                writing or reading back failed

    The outcome is stored in the deployment state (explicit completion state) and in
    <dataRoot>\<updatePolicy.result>. It never stops the Windows Update service, never blocks
    endpoints and never touches Defender security intelligence updates.
#>

$script:WddPolicyWuKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
$script:WddPolicyAuKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU'
$script:WddPolicyOkStatuses = @('Applied', 'AlreadyApplied')

# Adapters (replaced by the scenario tests) --------------------------------------------------------

function Get-WddEditionId {
    $cv = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
    if ($cv -and $cv.PSObject.Properties['EditionID']) { [string] $cv.EditionID } else { '' }
}

<# Reasons why the computer is managed by an organization (empty when it is not). #>
function Get-WddUpdateManagement {
    $reasons = @()
    try { if ((Get-CimInstance -ClassName Win32_ComputerSystem).PartOfDomain) { $reasons += 'joined to an Active Directory domain' } } catch { }
    $wu = Get-ItemProperty -LiteralPath $script:WddPolicyWuKey -ErrorAction SilentlyContinue
    if ($wu -and $wu.PSObject.Properties['WUServer'] -and [string] $wu.WUServer) { $reasons += 'configured for an update server (WSUS)' }
    $mdm = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\PolicyManager\current\device\Update' -ErrorAction SilentlyContinue
    if ($mdm -and $mdm.PSObject.Properties['AllowAutoUpdate']) { $reasons += 'Windows Update is managed by device management (MDM)' }
    $reasons
}

function Get-WddAuPolicyValues {
    $k = Get-ItemProperty -LiteralPath $script:WddPolicyAuKey -ErrorAction SilentlyContinue
    $o = @{}
    foreach ($n in 'NoAutoUpdate', 'AUOptions', 'ScheduledInstallDay', 'ScheduledInstallTime', 'NoAutoRebootWithLoggedOnUsers') {
        $o[$n] = $(if ($k -and $k.PSObject.Properties[$n]) { [int] $k.$n } else { $null })
    }
    return $o
}

function Set-WddAuPolicyValue {
    param([string] $Name, [int] $Value)
    if (-not (Test-Path -LiteralPath $script:WddPolicyAuKey)) { New-Item -Path $script:WddPolicyAuKey -Force | Out-Null }
    New-ItemProperty -LiteralPath $script:WddPolicyAuKey -Name $Name -Value $Value -PropertyType DWord -Force | Out-Null
}

# Policy -------------------------------------------------------------------------------------------

function Invoke-WddUpdatePolicy {
    param([hashtable] $Policy, [hashtable] $Paths)
    $want = [ordered]@{ NoAutoUpdate = [int] $Policy.values.NoAutoUpdate; AUOptions = [int] $Policy.values.AUOptions }
    $r = [ordered]@{ status = ''; mode = [string] $Policy.mode; values = $want; appliedUtc = (Get-WddNow).ToString('o'); message = '' }
    try {
        $edition = Get-WddEditionId
        if ($edition -match '^Core') {
            $r.status = 'Unsupported'
            $r.message = "Windows $edition (Home) does not support the Configure Automatic Updates policy. Windows' default update behaviour stays in place."
        } else {
            $managed = @(Get-WddUpdateManagement | Where-Object { $_ })
            $have = Get-WddAuPolicyValues
            if ($managed.Count -gt 0) {
                $r.status = 'ManagedByOrganization'
                $r.message = "This computer is $($managed -join '; '). Organizational policy takes precedence, so the ongoing update policy was not written."
            } elseif ($have.NoAutoUpdate -eq $want.NoAutoUpdate -and $have.AUOptions -eq $want.AUOptions) {
                $r.status = 'AlreadyApplied'
                $r.message = 'The Automatic Updates policy already had these values.'
            } elseif (@($have.Keys | Where-Object { $null -ne $have[$_] }).Count -gt 0) {
                $r.status = 'Conflict'
                $r.existing = $have
                $r.message = 'Automatic Updates policy values already exist on this computer and were left unchanged.'
            } else {
                foreach ($n in $want.Keys) { Set-WddAuPolicyValue $n $want[$n] }
                $check = Get-WddAuPolicyValues
                if ($check.NoAutoUpdate -eq $want.NoAutoUpdate -and $check.AUOptions -eq $want.AUOptions) {
                    $r.status = 'Applied'
                    $r.message = "Configure Automatic Updates = $($want.AUOptions) ($(if ($want.AUOptions -eq 3) { 'download automatically, notify before installing' } else { 'notify before downloading and installing' }))."
                } else {
                    $r.status = 'Failed'
                    $r.message = 'The policy values could not be read back after writing them.'
                }
            }
        }
    } catch {
        $r.status = 'Failed'
        $r.message = "Applying the update policy failed: $($_.Exception.Message)"
    }
    Write-WddLog "Ongoing update policy: $($r.status). $($r.message)" $(if ($r.status -in $script:WddPolicyOkStatuses) { 'INFO' } else { 'WARN' })
    try { Write-WddJson (Join-Path $Paths.Root ([string] $Policy.result)) $r } catch { Write-WddLog "Could not write the update policy result: $($_.Exception.Message)" 'WARN' }
    return $r
}

<#
    Applies the policy once: only after the windowsUpdate stage is Final, or with -Force when the
    deployment ends. Returns the recorded result, or $null while it is still waiting.
#>
function Step-WddUpdatePolicy {
    param([hashtable] $Manifest, [hashtable] $Paths, [hashtable] $State, $Snapshot, [switch] $Force)
    if (-not $Manifest.ContainsKey('updatePolicy') -or -not $Manifest.updatePolicy) { return $null }
    if ($State.ContainsKey('updatePolicy') -and $State.updatePolicy) { return $State.updatePolicy }
    $wu = @(@($Snapshot.stages) | Where-Object { $_ -and $_.id -eq 'windowsUpdate' }) | Select-Object -First 1
    $final = [bool] ($wu -and $wu.state -eq 'Final')
    if (-not $final -and -not $Force) { return $null }
    $r = Invoke-WddUpdatePolicy $Manifest.updatePolicy $Paths
    if (-not $final) { $r.note = 'Applied when the deployment ended; the initial Windows Update stage had not reported a final result.' }
    $State.updatePolicy = $r
    return $r
}

#Requires -Version 5.1
<#
.SYNOPSIS
    Windows Deployment Recovery: status, retry of failed operations, resume and diagnostics for a
    deployment on this computer (Phase 5).

.DESCRIPTION
    A small console tool for the technician. It never installs anything itself: it re-verifies the
    staged package, reopens operations in the engines' own state (ApplicationEngine.ps1 -Mode Retry
    logic, under the engine's mutex), registers the engines' tasks again and lets the deployment
    monitor follow them, exactly as during the original deployment. Every security check of the
    first run applies again on the retried attempt.

      -Action Menu               (default) numbered menu; asks for administrator rights with -Elevate
      -Action Status [-Json]     the deployment outcome, stages and every operation (read-only)
      -Action PendingActions     what a person still has to do (manual installs, restarts, checks)
      -Action RetryFailed        reopens every retryable failed or unfinished application (and a
                                 failed Windows Update stage), keeping successful ones
      -Action Retry -Operation app:winget:git.git[,...]
                                 reopens the named operations (ids from Status); a dependency that
                                 did not install is reopened with what needs it
           [-IncludePermanent]   also permanent failures (hash, signature, policy, not found,
                                 cancelled): only after the cause has been corrected
      -Action Resume             continues interrupted provisioning: unfinished operations, a
                                 missing task or monitor, a damaged deployment state (rebuilt from
                                 the manifest and the engines' own files)
      -Action ExportDiagnostics [-OutputPath <zip>]
                                 logs, states, results and the report as one ZIP, with passwords
                                 and Wi-Fi keys removed; answer files and Wi-Fi profiles are never
                                 included

    Only operations of this deployment's verified configuration can be retried. Deselected apps,
    manual catalog entries, unresolved identifiers and anything already installed are refused. No
    input is ever executed: operation ids must match a strict pattern and the permitted set.

    Exit codes: Status returns the outcome code (0 Succeeded, 10 CompletedWithWarnings,
    20 CompletedWithFailures, 25 Incomplete, 30/31/32 paused for network/reboot/user, 40 InProgress,
    50 FailedToInitialize, 60 Failed). Actions return 0 (done), 1 (refused or nothing to do),
    2 (busy), 3 (package integrity), 4 (administrator rights needed).
#>
[CmdletBinding()]
param(
    [ValidateSet('Menu', 'Status', 'PendingActions', 'RetryFailed', 'Retry', 'Resume', 'ExportDiagnostics')]
    [string] $Action = 'Menu',
    [string[]] $Operation = @(),
    [switch] $IncludePermanent,
    [switch] $Json,
    [string] $OutputPath = '',
    [switch] $Elevate
)

$script:RecoveryMain = $MyInvocation.InvocationName -ne '.'
# Captured first: the scripts dot-sourced below bind their own parameters in this scope.
$script:RecoveryArgs = @{ Action = $Action; Operation = @($Operation); IncludePermanent = [bool] $IncludePermanent; Json = [bool] $Json; OutputPath = $OutputPath; Elevate = [bool] $Elevate }
. (Join-Path $PSScriptRoot '..\common\DeploymentCommon.ps1')
. (Join-Path $PSScriptRoot '..\bootstrap\Initialize-Deployment.ps1')
. (Join-Path $PSScriptRoot '..\orchestrator\Show-DeploymentStatus.ps1')
# The application engine's own functions (Retry mode, lifecycle); present when the stage is part of the package.
$script:AppEngineScript = Join-Path $PSScriptRoot '..\applications\ApplicationEngine.ps1'
if (Test-Path -LiteralPath $script:AppEngineScript) { . $script:AppEngineScript }
Set-StrictMode -Version 2.0

$script:RecoveryExit = @{ Done = 0; Refused = 1; NothingToDo = 1; Busy = 2; IntegrityFailed = 3; NotElevated = 4; NoState = 1; UnknownStage = 1 }

# ------------------------------------------------------------------------------------------------
# Adapters (replaced by the scenario tests)
# ------------------------------------------------------------------------------------------------

<# The application engine configuration of the staged package (the verified copy). #>
function Get-WdrAppConfig {
    param([hashtable] $Paths)
    $p = Join-Path $Paths.Package 'scripts\applications\applications-config.json'
    if (-not (Test-Path -LiteralPath $p) -or -not (Get-Command Get-WdaConfig -ErrorAction SilentlyContinue)) { return $null }
    Get-WdaConfig $p
}

<# Registers and starts the application task again without archiving its state (Install-ApplicationEngine.ps1 -Resume). #>
function Invoke-WdrAppInstaller {
    param([hashtable] $Paths)
    $installer = Join-Path $Paths.Package 'scripts\applications\Install-ApplicationEngine.ps1'
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $out = & $ps -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $installer -Resume 2>&1
    foreach ($line in @($out)) { Write-WddLog "    | $line" }
    return $LASTEXITCODE
}

function Get-WdrDesktop { [Environment]::GetFolderPath('Desktop') }

# ------------------------------------------------------------------------------------------------
# Status
# ------------------------------------------------------------------------------------------------

<# Every application operation from the engine's live state (or its last result). #>
function Get-WdrOperations {
    param([hashtable] $Paths)
    $app = Join-Path $Paths.Root 'Applications'
    $s = $null
    foreach ($f in 'state.json', 'state.json.bak') { $s = Read-WddJson (Join-Path $app $f); if ($s -and $s.ContainsKey('packages')) { break } }
    $ops = @()
    if (-not $s) { return @() }
    foreach ($map in 'packages', 'additional') {
        if (-not $s.ContainsKey($map) -or $s[$map] -isnot [hashtable]) { continue }
        foreach ($e in @($s[$map].Values)) {
            if ($e -isnot [hashtable]) { continue }
            $id = $(if ($e.ContainsKey('operationId') -and $e.operationId) { [string] $e.operationId } elseif ($map -eq 'packages') { "app:$($e['key'])" } else { "additional:$($e['id'])" })
            $life = $(if (Get-Command Get-WdaLifecycle -ErrorAction SilentlyContinue) { Get-WdaLifecycle $e } else { [string] $e.status })
            $ops += [ordered]@{ operationId = $id; name = [string] $e['name']; status = [string] $e['status']; lifecycle = $life; failureClass = [string] $e['failureClass']
                                retryable = [bool] $e['retryable']; attempts = [int] $e['attempts']; totalAttempts = [int] $e['totalAttempts']; detection = [string] $e['detection']; message = [string] $e['message'] }
        }
    }
    return @($ops | Sort-Object { $_.operationId })
}

function Get-WdrStatus {
    param([hashtable] $Manifest, [hashtable] $Paths)
    $read = Read-WddDeploymentState $Paths
    $snap = $(if ($read.State) { Get-WddSnapshot $Manifest $Paths $read.State } else { $null })
    $out = $(if ($snap) { [ordered]@{ outcome = $snap.outcome; exitCode = $snap.outcomeCode; detail = $snap.outcomeDetail } } else { Get-WddDeploymentOutcome $null $null $read.Problem })
    [ordered]@{
        format          = 'windows-deployment-builder/recovery-status'
        version         = 1
        generatedUtc    = (Get-WddNow).ToString('o')
        packageId       = $Manifest.packageId
        outcome         = $out.outcome
        exitCode        = $out.exitCode
        detail          = $out.detail
        deploymentState = $(if ($read.State) { [string] $read.State.status } elseif ($read.Source -eq 'corrupt') { 'StateCorrupt' } else { 'NotInitialized' })
        stateSource     = $read.Source
        stages          = @(if ($snap) { @($snap.stages) | ForEach-Object { [ordered]@{ id = $_.id; name = $_.name; state = $_.state; status = $_.status; detail = $_.detail; idle = $_.idle; outstanding = $_.outstanding } } })
        operations      = @(Get-WdrOperations $Paths)
        report          = $(if (Test-Path -LiteralPath $Paths.ReportText) { $Paths.ReportText } else { '' })
    }
}

function Format-WdrStatus {
    param($Status)
    $l = New-Object System.Collections.Generic.List[string]
    $l.Add('Windows Deployment Recovery - status')
    $l.Add('====================================')
    $l.Add("Outcome   : $($Status.outcome) (code $($Status.exitCode))")
    if ($Status.detail) { $l.Add("            $($Status.detail)") }
    $l.Add("State     : $($Status.deploymentState)$(if ($Status.stateSource -eq 'backup') { ' (recovered from its backup)' })")
    foreach ($s in @($Status.stages)) { $l.Add(('  {0,-24} {1,-10} {2} {3}' -f $s.name, $s.state, $s.status, $(if ($s.idle) { $s.idle } else { $s.detail }))) }
    $ops = @($Status.operations)
    if ($ops.Count) {
        $l.Add('')
        $l.Add(('{0,-22} {1,-36} {2,-10} {3}' -f 'Lifecycle', 'Operation', 'Attempts', 'Message'))
        foreach ($o in $ops) { $l.Add(('{0,-22} {1,-36} {2,-10} {3}' -f $o.lifecycle, $o.operationId, "$($o.totalAttempts)", $o.message)) }
        $retry = @($ops | Where-Object { $_.lifecycle -in 'FailedRetryable', 'BlockedByDependency', 'WaitingForNetwork' })
        $perm = @($ops | Where-Object { $_.lifecycle -eq 'FailedPermanent' })
        $l.Add('')
        $l.Add("Retryable: $($retry.Count) (RetryFailed)   Permanent: $($perm.Count) (fix the cause, then Retry -Operation <id> -IncludePermanent)")
    }
    if ($Status.report) { $l.Add("Report    : $($Status.report)") }
    return ($l -join "`r`n")
}

<# What a person still has to do; never includes secrets. #>
function Get-WdrPendingActions {
    param([hashtable] $Manifest, [hashtable] $Paths)
    $items = @()
    foreach ($o in @(Get-WdrOperations $Paths)) {
        switch ($o.lifecycle) {
            'ManualActionRequired' { $items += "$($o.name): $($o.message)" }
            'WaitingForReboot' { $items += "$($o.name): restart the computer to finish. $($o.message)" }
            'FailedPermanent' { $items += "$($o.name) [$($o.operationId)]: $($o.failureClass) failure; correct the cause, then retry with -IncludePermanent. $($o.message)" }
            'FailedRetryable' { $items += "$($o.name) [$($o.operationId)]: failed after automatic retries; run RetryFailed. $($o.message)" }
            'BlockedByDependency' { $items += "$($o.name) [$($o.operationId)]: blocked by a dependency; run RetryFailed. $($o.message)" }
            'WaitingForNetwork' { $items += "$($o.name): waiting for the network or its package source." }
        }
        if ($o.status -eq 'Succeeded' -and $o.detection -eq 'Unconfirmed') { $items += "$($o.name): WinGet reported success but could not confirm it; check that it is installed." }
    }
    $report = Read-WddJson $Paths.ReportJson
    if ($report -and $report.ContainsKey('remainingTasks')) {
        foreach ($t in @($report.remainingTasks)) { if ($t -and $t -notmatch '^Application ' -and $t -notmatch '^Additional Software ') { $items += [string] $t } }
    }
    return @($items | Select-Object -Unique)
}

# ------------------------------------------------------------------------------------------------
# Recovery actions
# ------------------------------------------------------------------------------------------------

<#
    Rebuilds a deployment state that is damaged beyond its backup: from the verified manifest and
    what the engines wrote themselves. A stage with a result, a status file or a task counts as
    launched (it is never launched twice); the damaged file is kept for diagnosis.
#>
function Repair-WddDeploymentState {
    param([hashtable] $Manifest, [hashtable] $Paths, [hashtable] $Identity)
    $stamp = (Get-WddNow).ToString('yyyyMMddHHmmss')
    foreach ($f in $Paths.State, "$($Paths.State).bak") { if (Test-Path -LiteralPath $f) { Move-Item -LiteralPath $f -Destination "$f.corrupt-$stamp" -Force } }
    $state = New-WddState $Manifest 'Embedded' $Identity
    $state.status = 'InProgress'
    $state.message = 'Rebuilt by the recovery tool after the deployment state was damaged.'
    $state.stagedFiles = @(@($Manifest.files) | Where-Object { $_.embedded -and (Test-Path -LiteralPath (Join-Path $Paths.Package ($_.path -replace '/', '\'))) } | ForEach-Object { $_.path })
    foreach ($s in Get-WddEngineStages $Manifest) {
        $seen = (Test-Path -LiteralPath (Join-Path $Paths.Root $s.result)) -or (Test-Path -LiteralPath (Join-Path $Paths.Root $s.status)) -or (Get-WddTask $s.task.path $s.task.name)
        $state.stages[$s.id] = @{ launchResult = $(if ($seen) { 'Launched' } else { '' }); attempts = 0; launchedUtc = $(if ($seen) { (Get-WddNow).ToString('o') } else { $null }); exitCode = $null
                                  message = $(if ($seen) { 'Found running or finished while rebuilding the state.' } else { 'Not launched before the state was lost.' }); user = $(if ($s.context -eq 'user') { [string] $Identity.Name } else { 'SYSTEM' }) }
    }
    Save-WddState $Paths $state
    Write-WddLog "Deployment state rebuilt from the manifest (stages: $(($state.stages.Keys | ForEach-Object { "$_=$($state.stages[$_].launchResult)" }) -join ', '))." 'WARN'
    return $state
}

<#
    RetryFailed, Retry and Resume. Steps: administrator check, deployment mutex, state (rebuilt
    only for Resume), package integrity, the application stage (engine Retry logic, then its task
    again without archiving), the Windows Update stage (relaunched only when it ended with
    failures, or for Resume when its task is gone), then the deployment is reopened for the monitor.
#>
function Invoke-WdrRecovery {
    param([hashtable] $Manifest, [hashtable] $Paths, [ValidateSet('RetryFailed', 'Retry', 'Resume')] [string] $Mode, [string[]] $Operations = @(), [switch] $IncludePermanent)
    Initialize-WddLogging $Paths
    $identity = Get-WddIdentity
    if (-not $identity.IsAdmin) { return @{ Outcome = 'NotElevated'; Message = 'Run the recovery tool as administrator.'; Accepted = @(); Refused = @() } }
    $mutex = Enter-WddMutex 60
    if (-not $mutex) { return @{ Outcome = 'Busy'; Message = 'Another deployment process (monitor or setup) is running; try again in a minute.'; Accepted = @(); Refused = @() } }
    try {
        Write-WddLog "==== Recovery ($Mode) requested by $($identity.Name)$(if (@($Operations).Count) { ': ' + (@($Operations) -join ', ') }) ===="
        $read = Read-WddDeploymentState $Paths
        $state = $read.State
        if ($read.Source -eq 'corrupt') {
            if ($Mode -ne 'Resume') { return @{ Outcome = 'Refused'; Message = "The deployment state is damaged ($($read.Problem)). Run -Action Resume first; it rebuilds the state."; Accepted = @(); Refused = @() } }
            $state = Repair-WddDeploymentState $Manifest $Paths $identity
        }
        if (-not $state) { return @{ Outcome = 'NoState'; Message = 'No deployment has been started on this computer (run setup.cmd from the package).'; Accepted = @(); Refused = @() } }
        if ($state.packageId -ne $Manifest.packageId) { return @{ Outcome = 'Refused'; Message = "The deployment on this computer ($($state.packageId)) is not this package ($($Manifest.packageId))."; Accepted = @(); Refused = @() } }
        $check = Test-WddFiles $Paths.Package $Manifest 'Text' @($state.stagedFiles)
        if (-not $check.Ok) {
            Write-WddLog "Recovery refused: the staged package is modified or incomplete ($($check.Missing.Count) missing, $($check.Mismatched.Count) modified)." 'ERROR'
            return @{ Outcome = 'IntegrityFailed'; Message = 'The staged package was modified or is incomplete; run setup.cmd from the original package to stage it again. Nothing was retried.'; Accepted = @(); Refused = @(@($check.Missing) + @($check.Mismatched) | ForEach-Object { @{ operationId = "file:$_"; reason = 'missing or modified' } }) }
        }

        $accepted = @(); $refused = @(); $notes = @()
        $ops = @($Operations | Where-Object { $_ } | ForEach-Object { ([string] $_).Trim() })
        $wuRequested = $ops -contains 'stage:windowsUpdate'
        $appOps = @($ops | Where-Object { $_ -ne 'stage:windowsUpdate' })

        # Applications: the engine's own Retry logic decides what may run again.
        $appStage = Get-WddStage $Manifest 'applications'
        if ($appStage -and $appStage.enabled) {
            $cfg = Get-WdrAppConfig $Paths
            if (-not $cfg) { $notes += 'The application engine is not part of the staged package.' }
            elseif ($Mode -ne 'Retry' -or $appOps.Count) {
                if ($identity.IsSystem) {
                    $refused += @{ operationId = 'stage:applications'; reason = 'the application stage runs as the signed-in user (WinGet is not supported as SYSTEM); run the recovery tool as that user' }
                } else {
                    $r = switch ($Mode) {
                        'RetryFailed' { Invoke-WdaRetry $cfg -AllFailed -IncludePermanent:$IncludePermanent -RequestedBy $identity.Name }
                        'Retry' { Invoke-WdaRetry $cfg -Operations $appOps -IncludePermanent:$IncludePermanent -RequestedBy $identity.Name }
                        'Resume' { Invoke-WdaRetry $cfg -PendingOnly -RequestedBy $identity.Name }
                    }
                    $accepted += @($r.Accepted); $refused += @($r.Refused)
                    if ($r.Outcome -eq 'Busy') { return @{ Outcome = 'Busy'; Message = $r.Message; Accepted = @(); Refused = @() } }
                    $snapApp = Get-WddStageSnapshot $appStage $Paths $state
                    $needsTask = ($r.Outcome -eq 'Accepted') -or ($Mode -eq 'Resume' -and $snapApp.state -ne 'Final' -and -not (Get-WddTask $appStage.task.path $appStage.task.name))
                    if ($needsTask) {
                        $code = $null
                        try { $code = Invoke-WdrAppInstaller $Paths } catch { $notes += "Application task: $($_.Exception.Message)" }
                        $rec = $(if ($state.stages.ContainsKey('applications')) { $state.stages['applications'] } else { @{ attempts = 0 } })
                        $rec.launchResult = $(if (Get-WddTask $appStage.task.path $appStage.task.name) { 'Launched' } else { 'LaunchFailed' })
                        $rec.launchedUtc = (Get-WddNow).ToString('o'); $rec.exitCode = $code; $rec.user = $identity.Name
                        $rec.message = $(if ($rec.launchResult -eq 'Launched') { "Restarted by the recovery tool ($Mode)." } else { "The recovery tool could not register the application task (exit code $code)." })
                        $state.stages['applications'] = $rec
                        $notes += "Application stage: $($rec.message)"
                        if ($r.Outcome -ne 'Accepted') { $accepted += 'stage:applications' }
                    }
                }
            }
        }

        # Windows Update: its engine never offers an installed update again, so a relaunch is safe.
        $wuStage = Get-WddStage $Manifest 'windowsUpdate'
        if ($wuStage -and $wuStage.enabled -and ($Mode -ne 'Retry' -or $wuRequested)) {
            $wu = Get-WddStageSnapshot $wuStage $Paths $state
            $failed = $wu.state -eq 'Final' -and $wu.status -in 'CompletedWithFailures', 'Failed', 'Offline'
            $lost = $Mode -eq 'Resume' -and $wu.state -in 'Stalled', 'LaunchFailed', 'NotStarted'
            if (($Mode -ne 'Resume' -and $failed) -or $lost) {
                $state.stages['windowsUpdate'] = @{ launchResult = ''; attempts = 0; launchedUtc = $null; exitCode = $null; message = "Restarted by the recovery tool ($Mode)."; user = 'SYSTEM' }
                $rec = Invoke-WddLaunchStage $wuStage $Paths $state $identity ([int] $Manifest.failureHandling.orchestrator.launchAttempts)
                if ($rec.launchResult -eq 'Launched') { $accepted += 'stage:windowsUpdate' } else { $refused += @{ operationId = 'stage:windowsUpdate'; reason = [string] $rec.message } }
            } elseif ($wuRequested) {
                $refused += @{ operationId = 'stage:windowsUpdate'; reason = "the Windows Update stage is $($wu.state)$(if ($wu.status) { "/$($wu.status)" }); only a stage that ended with failures is retried" }
            }
        }

        $reopen = ($accepted.Count -gt 0) -or ($Mode -eq 'Resume')
        if ($reopen) {
            if ($state.status -in 'Completed', 'IntegrityFailed' -and (Test-Path -LiteralPath $Paths.Marker)) {
                Move-Item -LiteralPath $Paths.Marker -Destination "$($Paths.Marker).$((Get-WddNow).ToString('yyyyMMddHHmmss')).bak" -Force
            }
            $state.status = 'InProgress'
            $state.message = "Recovery ($Mode) by $($identity.Name)."
            $state.deadlineUtc = (Get-WddNow).AddHours([double] $Manifest.failureHandling.orchestrator.deadlineHours).ToString('o')
        }
        $state.recoveries = @(@($state.recoveries) + @(@{ atUtc = (Get-WddNow).ToString('o'); by = $identity.Name; action = $Mode; accepted = @($accepted); refused = @($refused | ForEach-Object { $_.operationId }) }))
        Save-WddState $Paths $state
        if ($reopen) {
            Register-WddMonitorTask $Paths $Manifest
            try { Start-WddTask $script:MonitorTask.path $script:MonitorTask.name } catch { }
        }
        $outcome = $(if ($accepted.Count) { 'Done' } elseif ($Mode -eq 'Resume') { 'Done' } elseif ($refused.Count) { 'Refused' } else { 'NothingToDo' })
        $msg = "Reopened: $(if ($accepted.Count) { $accepted -join ', ' } else { 'none' }). Refused: $(if ($refused.Count) { ($refused | ForEach-Object { "$($_.operationId) ($($_.reason))" }) -join '; ' } else { 'none' }).$(if ($notes.Count) { ' ' + ($notes -join ' ') })"
        Write-WddLog "Recovery ($Mode): $msg" $(if ($outcome -eq 'Done') { 'INFO' } else { 'WARN' })
        Write-WddEvent 3005 "Deployment recovery ($Mode) by $($identity.Name): $msg" $(if ($outcome -eq 'Done') { 'Information' } else { 'Warning' })
        return @{ Outcome = $outcome; Message = $msg; Accepted = @($accepted); Refused = @($refused) }
    } finally {
        Exit-WddMutex $mutex
    }
}

# ------------------------------------------------------------------------------------------------
# Diagnostics
# ------------------------------------------------------------------------------------------------

<#
    Removes passwords and Wi-Fi keys from text (defence in depth: these files should contain none).
    The Wi-Fi element name is written as key[M]aterial so this script itself never contains the
    literal token the answer-file secret checks look for.
#>
function Protect-WdrText {
    param([string] $Text)
    $t = [regex]::Replace($Text, '(?i)("(?:password|passphrase|key[M]aterial|networkKey|secret|token|apiKey|adminPassword)"\s*:\s*)"(?:[^"\\]|\\.)*"', '$1"[redacted]"')
    $t = [regex]::Replace($t, '(?is)(<(key[M]aterial|Password)>).*?(</\2>)', '$1[redacted]$3')
    $t = [regex]::Replace($t, '(?i)\b(password|passwd|pwd|key[M]aterial|networkKey)(\s*[=:]\s*)[^\s,;"]+', '$1$2[redacted]')
    return $t
}

<#
    Only these files below the data root are collected; anything else (answer files, Wi-Fi
    profiles, Panther logs, user files) is never read.
#>
$script:DiagnosticFiles = @(
    'Deployment\status.json', 'Deployment\logs\*.log', 'Deployment\logs\*.log.1',
    'state\*.json', 'state\*.done', 'state\*.bak', 'state\*.corrupt*',
    'reports\deployment-report.json', 'reports\deployment-report.txt',
    'Applications\state.json', 'Applications\state.json.bak', 'Applications\state.json.corrupt', 'Applications\status.json', 'Applications\result.json', 'Applications\follow-up.txt',
    'Applications\logs\*.log', 'Applications\logs\*.log.1', 'Applications\logs\attempts.jsonl', 'Applications\logs\packages\*.log', 'Applications\history\*.json',
    'Updates\state.json', 'Updates\status.json', 'Updates\result.json', 'Updates\policy-result.json', 'Updates\logs\*.log',
    'Network\wifi-result.json', 'Network\*.log',
    'Package\deployment-manifest.json', 'Package\config\orchestration.json', 'Package\scripts\applications\applications-config.json', 'Package\scripts\windows-update\config.json'
)

function Export-WdrDiagnostics {
    param([hashtable] $Manifest, [hashtable] $Paths, [string] $OutputPath = '')
    $identity = Get-WddIdentity
    $stamp = (Get-WddNow).ToString('yyyyMMdd-HHmmss')
    if (-not $OutputPath) {
        $dir = $(if ($identity.IsAdmin) { $Paths.Reports } else { Get-WdrDesktop })
        $OutputPath = Join-Path $dir ("deployment-diagnostics-{0}-{1}.zip" -f $env:COMPUTERNAME, $stamp)
    }
    if ($OutputPath -notmatch '\.zip$') { throw 'The diagnostics file must end in .zip.' }
    $staging = Join-Path ([IO.Path]::GetTempPath()) ("wdr-diag-" + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Path $staging -Force | Out-Null
    $index = @()
    $redacted = 0
    try {
        $root = [IO.Path]::GetFullPath($Paths.Root).TrimEnd('\') + '\'
        foreach ($pattern in $script:DiagnosticFiles) {
            $dir = Join-Path $Paths.Root (Split-Path -Parent $pattern)
            if (-not (Test-Path -LiteralPath $dir)) { continue }
            foreach ($f in @(Get-ChildItem -LiteralPath $dir -Filter (Split-Path -Leaf $pattern) -File -ErrorAction SilentlyContinue)) {
                $full = [IO.Path]::GetFullPath($f.FullName)
                if (-not $full.StartsWith($root, [StringComparison]::OrdinalIgnoreCase) -or ($f.Attributes -band [IO.FileAttributes]::ReparsePoint)) { continue }
                if ($f.Extension -in '.xml', '.wim', '.exe', '.msi') { continue }
                $rel = $full.Substring($root.Length)
                $bytes = [IO.File]::ReadAllBytes($full)
                $max = 20MB
                if ($bytes.Length -gt $max) { $bytes = $bytes[($bytes.Length - $max)..($bytes.Length - 1)] }
                $text = [Text.Encoding]::UTF8.GetString($bytes)
                $safeText = Protect-WdrText $text
                if ($safeText -ne $text) { $redacted++ }
                $target = Join-Path $staging $rel
                New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null
                [IO.File]::WriteAllText($target, $safeText, (New-Object Text.UTF8Encoding($false)))
                $index += [ordered]@{ path = $rel; size = $f.Length; truncated = ($f.Length -gt $max); redacted = ($safeText -ne $text) }
            }
        }
        $status = Get-WdrStatus $Manifest $Paths
        $info = [ordered]@{
            format = 'windows-deployment-builder/diagnostics'; version = 1; generatedUtc = (Get-WddNow).ToString('o'); computer = $env:COMPUTERNAME
            windows = [string] [Environment]::OSVersion.VersionString; powershell = $PSVersionTable.PSVersion.ToString(); packageId = $Manifest.packageId
            outcome = $status.outcome; outcomeCode = $status.exitCode; files = $index; redactedFiles = $redacted
            excluded = 'Answer files (autounattend.xml, unattend.xml), Wi-Fi profiles (*.xml), Panther logs and anything outside the data root are never collected; password and key values are replaced by [redacted].'
        }
        [IO.File]::WriteAllText((Join-Path $staging 'diagnostics.json'), ($info | ConvertTo-Json -Depth 6), (New-Object Text.UTF8Encoding($false)))
        [IO.File]::WriteAllText((Join-Path $staging 'recovery-status.txt'), (Format-WdrStatus $status), (New-Object Text.UTF8Encoding($true)))
        $outDir = Split-Path -Parent $OutputPath
        if ($outDir -and -not (Test-Path -LiteralPath $outDir)) { New-Item -ItemType Directory -Path $outDir -Force | Out-Null }
        if (Test-Path -LiteralPath $OutputPath) { Remove-Item -LiteralPath $OutputPath -Force }
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        [IO.Compression.ZipFile]::CreateFromDirectory($staging, $OutputPath)
        return @{ Outcome = 'Done'; Path = $OutputPath; Files = $index.Count; Redacted = $redacted }
    } finally {
        Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction SilentlyContinue
    }
}

# ------------------------------------------------------------------------------------------------
# Console
# ------------------------------------------------------------------------------------------------

function Invoke-WdrAction {
    param([hashtable] $Manifest, [hashtable] $Paths, [string] $Action, [string[]] $Operation = @(), [switch] $IncludePermanent, [switch] $Json, [string] $OutputPath = '')
    switch ($Action) {
        'Status' {
            $st = Get-WdrStatus $Manifest $Paths
            return @{ Text = $(if ($Json) { $st | ConvertTo-Json -Depth 8 } else { Format-WdrStatus $st }); Exit = [int] $st.exitCode }
        }
        'PendingActions' {
            $items = @(Get-WdrPendingActions $Manifest $Paths)
            $text = $(if ($Json) { ConvertTo-Json @($items) } elseif ($items.Count) { "Pending actions`r`n===============`r`n" + (($items | ForEach-Object { "- $_" }) -join "`r`n") } else { 'Nothing is waiting for a person.' })
            return @{ Text = $text; Exit = 0 }
        }
        'ExportDiagnostics' {
            $r = Export-WdrDiagnostics $Manifest $Paths $OutputPath
            return @{ Text = "Diagnostics: $($r.Path) ($($r.Files) file(s), $($r.Redacted) with values redacted)."; Exit = 0 }
        }
        default {
            $r = Invoke-WdrRecovery $Manifest $Paths $Action -Operations $Operation -IncludePermanent:$IncludePermanent
            $text = $(if ($Json) { [pscustomobject]$r | ConvertTo-Json -Depth 6 } else { "$($Action): $($r.Outcome). $($r.Message)" })
            return @{ Text = $text; Exit = [int] $script:RecoveryExit[$r.Outcome] }
        }
    }
}

function Show-WdrMenu {
    param([hashtable] $Manifest, [hashtable] $Paths)
    while ($true) {
        Write-Output ''
        Write-Output (Format-WdrStatus (Get-WdrStatus $Manifest $Paths))
        Write-Output ''
        Write-Output 'Windows Deployment Recovery'
        Write-Output '  1  Refresh status            4  Retry one application'
        Write-Output '  2  Retry failed operations   5  Resume interrupted provisioning'
        Write-Output '  3  View pending actions      6  Export diagnostic report'
        Write-Output '  0  Exit'
        $c = Read-Host 'Choose'
        $r = switch ($c) {
            '1' { $null }
            '2' { Invoke-WdrAction $Manifest $Paths 'RetryFailed' }
            '3' { Invoke-WdrAction $Manifest $Paths 'PendingActions' }
            '4' {
                $id = Read-Host 'Operation id (from the list, for example app:winget:git.git)'
                $perm = (Read-Host 'Is this a permanent failure whose cause you have corrected? (y/N)') -match '^(y|yes)$'
                Invoke-WdrAction $Manifest $Paths 'Retry' -Operation @($id) -IncludePermanent:$perm
            }
            '5' { Invoke-WdrAction $Manifest $Paths 'Resume' }
            '6' { Invoke-WdrAction $Manifest $Paths 'ExportDiagnostics' }
            '0' { return }
            default { @{ Text = 'Choose 0-6.'; Exit = 0 } }
        }
        if ($r) { Write-Output ''; Write-Output $r.Text }
    }
}

if ($script:RecoveryMain) {
    $a = $script:RecoveryArgs
    $package = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
    try { $manifest = Read-WddManifest (Join-Path $package 'deployment-manifest.json') } catch { Write-Output "ERROR: $($_.Exception.Message)"; exit 50 }
    $paths = Get-WddPaths $manifest.dataRoot
    $id = Get-WddIdentity
    if ($a.Elevate -and -not $id.IsAdmin) {
        $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        Start-Process -FilePath $ps -Verb RunAs -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$PSCommandPath`"", '-Action', $a.Action)
        exit 0
    }
    if ($a.Action -eq 'Menu') {
        if (-not $id.IsAdmin) { Write-Output 'Not running as administrator: status only. Retry, resume and diagnostics need administrator rights (use the "Deployment recovery" shortcut or -Elevate).' }
        Show-WdrMenu $manifest $paths
        exit 0
    }
    $r = Invoke-WdrAction $manifest $paths $a.Action -Operation $a.Operation -IncludePermanent:$a.IncludePermanent -Json:$a.Json -OutputPath $a.OutputPath
    Write-Output $r.Text
    exit $r.Exit
}
